                background: isDarkMode ? '#1f2937' : '#ffffff',
                color: isDarkMode ? '#f3f4f6' : '#111827',
                cursor: 'pointer',
              }
            }}
          />
        </div>
      </div>
    </NotificationContainer>
  );
}

function AppTablet() {
  return (
    <ErrorBoundary>
      <AuthProvider>
        <ConfirmationProvider>
          <Router>
            <AppContent />
          </Router>
        </ConfirmationProvider>
      </AuthProvider>
    </ErrorBoundary>
  );
}

