                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder={t('auth.passwordPlaceholder') || 'ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó'}
                  required
                  className={`${inputClass} pl-10`}
                />
              </div>
            </div>
          </>
        )}

        {/* Step 2: Customer Details */}
        {step === 2 && (
          <>
            <div className="grid grid-cols-2 gap-4">
