                {t('profile.country') || 'Country'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <Globe className={`absolute left-3 top-2.5 w-4 h-4 ${isDark ? 'text-gray-500' : 'text-gray-400'}`} />
                <input
                  type="text"
                  value={country}
                  onChange={(e) => setCountry(e.target.value)}
                  placeholder={t('auth.countryPlaceholder') || 'Germany'}
                  required
                  className={`${inputClass} pl-10`}
                />
              </div>
            </div>

            <div>
              <label className={labelClass}>
                {t('profile.federalState') || 'Federal State'} <span className="text-red-500">*</span>
              </label>
              <select
                value={federalState}
                onChange={(e) => setFederalState(e.target.value)}
                required
                className={inputClass}
              >
                <option value="">{t('common.select') || 'Select...'}</option>
                {federalStates.map((state) => (
                  <option key={state} value={state}>
                    {state}
                  </option>
                ))}
              </select>
            </div>
          </>
        )}

        {/* Buttons */}
        <div className="flex gap-3 pt-4">
          {step > 1 && (
            <button
              type="button"
              onClick={handleBack}
              className={`flex-1 py-2 px-4 rounded-lg font-medium text-sm transition-colors ${
                isDark
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {t('common.back') || 'Back'}
            </button>
          )}

          {step === 1 && (
            <button
              type="button"
              onClick={onCancel}
              className={`flex-1 py-2 px-4 rounded-lg font-medium text-sm transition-colors ${
                isDark
                  ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {t('common.cancel') || 'Cancel'}
            </button>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`flex-1 py-2 px-4 rounded-lg font-semibold text-sm transition-colors ${
              loading
                ? 'opacity-50 cursor-not-allowed bg-blue-600 text-white'
                : 'bg-blue-600 hover:bg-blue-700 text-white'
            }`}
          >
            {loading
              ? (t('common.processing') || 'Processing...')
              : step === 3
              ? (t('auth.createAccount') || 'Create Account')
              : (t('common.continue') || 'Continue')}
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { hybridDB } from '../../services/hybridDatabase';
import toast from 'react-hot-toast';

export const SyncStatus: React.FC = () => {
  const { t } = useTranslation();
  const [diagnostics, setDiagnostics] = useState<any>(null);
  const [status, setStatus] = useState<any>(null);
  const [syncing, setSyncing] = useState(false);
  const [autoRefresh, setAutoRefresh] = useState(true);

  const refreshDiagnostics = () => {
    try {
      const diag = hybridDB.getSyncDiagnostics();
      const stat = hybridDB.getStatus();
      setDiagnostics(diag);
      setStatus(stat);
    } catch (error) {
      console.error('Failed to get diagnostics:', error);
    }
  };

  useEffect(() => {
    refreshDiagnostics();

    if (autoRefresh) {
      const interval = setInterval(refreshDiagnostics, 2000);
      return () => clearInterval(interval);
    }
  }, [autoRefresh]);

  const handleForceSync = async () => {
    if (syncing) {
      console.log('[SyncStatus] Sync already in progress, ignoring');
      return;
    }

    setSyncing(true);
    try {
      const result = await hybridDB.forceSyncNow();
      if (result.success) {
        toast.success(`Ô£à ${result.message}`);
      } else {
        toast.error(`ÔØî ${result.message}`);
      }
      refreshDiagnostics();
    } catch (error: any) {
      toast.error(`ÔØî Sync failed: ${error.message}`);
    } finally {
      // Always reset syncing state
      setSyncing(false);
      console.log('[SyncStatus] Sync completed, resetting state');
    }
  };

  if (!diagnostics || !status) {
    return <div className="p-4 text-gray-400">{t('common.loading') || 'Loading...'}</div>;
  }

  const getStatusColor = () => {
    if (!diagnostics.network.navigatorOnline) return 'text-red-500';
    if (!diagnostics.network.backendOnline) return 'text-yellow-500';
    if (diagnostics.queue.length > 0) return 'text-blue-500';
    return 'text-green-500';
  };

  const getStatusIcon = () => {
    if (!diagnostics.network.navigatorOnline) return '­ƒô┤';
    if (!diagnostics.network.backendOnline) return 'ÔÜá´©Å';
    if (diagnostics.queue.isSyncing) return '­ƒöä';
    if (diagnostics.queue.length > 0) return 'ÔÅ│';
    return 'Ô£à';
  };

  return (
    <div className="bg-gray-800 rounded-lg shadow-lg p-4 max-w-2xl">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-bold text-white flex items-center gap-2">
          <span className={`text-2xl ${getStatusColor()}`}>{getStatusIcon()}</span>
          {t('databaseSyncStatus.title')}
        </h3>
        <div className="flex gap-2">
          <button
            onClick={() => setAutoRefresh(!autoRefresh)}
            className={`px-3 py-1 rounded text-sm ${
              autoRefresh ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-300'
            }`}
          >
            {autoRefresh ? t('databaseSyncStatus.pauseAuto') : t('databaseSyncStatus.auto')}
          </button>
          <button
            onClick={refreshDiagnostics}
            className="px-3 py-1 bg-gray-700 text-white rounded text-sm hover:bg-gray-600"
          >
            {t('databaseSyncStatus.refresh')}
          </button>
        </div>
      </div>

      {/* Network Status */}
      <div className="mb-4 p-3 bg-gray-700 rounded">
        <h4 className="font-semibold text-white mb-2">{t('databaseSyncStatus.network')}</h4>
        <div className="grid grid-cols-2 gap-2 text-sm">
          <div className="text-gray-300">
            {t('databaseSyncStatus.device')}: <span className={diagnostics.network.navigatorOnline ? 'text-green-400' : 'text-red-400'}>
              {diagnostics.network.navigatorOnline ? t('databaseSyncStatus.online') : t('databaseSyncStatus.offline')}
            </span>
          </div>
          <div className="text-gray-300">
            {t('databaseSyncStatus.firebase')}: <span className={diagnostics.network.backendOnline ? 'text-green-400' : 'text-red-400'}>
              {diagnostics.network.backendOnline ? t('databaseSyncStatus.connected') : t('databaseSyncStatus.disconnected')}
            </span>
          </div>
          <div className="text-gray-300">
            {t('databaseSyncStatus.lastCheck')}: <span className="text-yellow-400">{diagnostics.network.lastCheck}</span>
          </div>
          <div className="text-gray-300">
            {t('databaseSyncStatus.backoff')}: <span className="text-yellow-400">{diagnostics.network.backoffMs}ms</span>
          </div>
        </div>
      </div>

      {/* Sync Queue */}
      <div className="mb-4 p-3 bg-gray-700 rounded">
        <h4 className="font-semibold text-white mb-2">{t('databaseSyncStatus.syncQueue')}</h4>
        <div className="grid grid-cols-2 gap-2 text-sm mb-2">
          <div className="text-gray-300">
            {t('databaseSyncStatus.items')}: <span className="text-blue-400 font-bold">{diagnostics.queue.length}</span>
          </div>
          <div className="text-gray-300">
            {t('databaseSyncStatus.status')}: <span className={diagnostics.queue.isSyncing ? 'text-yellow-400' : 'text-gray-400'}>
              {diagnostics.queue.isSyncing ? t('databaseSyncStatus.syncing') : t('databaseSyncStatus.idle')}
            </span>
          </div>
        </div>

        {diagnostics.queue.length > 0 && (
          <div className="mt-2">
            <button
              onClick={handleForceSync}
              disabled={syncing || diagnostics.queue.isSyncing || !diagnostics.network.navigatorOnline}
              className="w-full px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:bg-gray-600 disabled:cursor-not-allowed"
            >
              {syncing || diagnostics.queue.isSyncing ? t('databaseSyncStatus.syncing') : t('databaseSyncStatus.forceSyncNow')}
            </button>

            <div className="mt-2 max-h-40 overflow-y-auto">
              <table className="w-full text-xs text-gray-300">
                <thead className="bg-gray-800">
                  <tr>
                    <th className="px-2 py-1 text-left">{t('databaseSyncStatus.type')}</th>
                    <th className="px-2 py-1 text-left">{t('databaseSyncStatus.action')}</th>
                    <th className="px-2 py-1 text-right">{t('databaseSyncStatus.age')}</th>
                    <th className="px-2 py-1 text-right">{t('databaseSyncStatus.tries')}</th>
                  </tr>
                </thead>
                <tbody>
                  {diagnostics.queue.items.map((item: any, idx: number) => (
                    <tr key={idx} className="border-t border-gray-600">
                      <td className="px-2 py-1">{item.type}</td>
                      <td className="px-2 py-1">{item.action}</td>
                      <td className="px-2 py-1 text-right text-yellow-400">{item.age}</td>
                      <td className="px-2 py-1 text-right">{item.attempts}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {diagnostics.queue.length === 0 && (
          <div className="text-center text-gray-400 text-sm py-2">
            {t('databaseSyncStatus.allDataSynced')}
          </div>
        )}
      </div>

      {/* Auth Status */}
      <div className="mb-4 p-3 bg-gray-700 rounded">
        <h4 className="font-semibold text-white mb-2">{t('databaseSyncStatus.authentication')}</h4>
        <div className="grid grid-cols-2 gap-2 text-sm">
          <div className="text-gray-300">
            UID: <span className={diagnostics.auth.uid === 'SET' ? 'text-green-400' : 'text-red-400'}>
              {diagnostics.auth.uid}
            </span>
          </div>
          <div className="text-gray-300">
            {t('databaseSyncStatus.firebase')}: <span className={diagnostics.auth.firebaseUser !== 'NO_AUTH' ? 'text-green-400' : 'text-red-400'}>
              {diagnostics.auth.firebaseUser !== 'NO_AUTH' ? t('databaseSyncStatus.authenticated') : t('databaseSyncStatus.notAuthenticated')}
            </span>
          </div>
        </div>
      </div>

      {/* Platform Info */}
      <div className="p-3 bg-gray-700 rounded">
        <h4 className="font-semibold text-white mb-2">{t('databaseSyncStatus.platform')}</h4>
        <div className="text-sm text-gray-300">
          {t('databaseSyncStatus.storage')}: <span className="text-blue-400">{diagnostics.platform.type}</span>
        </div>
      </div>
    </div>
  );
};

import { useState, useEffect, useRef } from 'react';
import { X, Terminal, Trash2, Copy } from 'lucide-react';
import Button from '../ui/Button';
import { useLanguage } from '../../hooks/useLanguage';

interface LogEntry {
  id: number;
  timestamp: string;
  level: 'log' | 'warn' | 'error' | 'info';
  message: string;
  args: any[];
}

interface OnScreenConsoleProps {
  isVisible: boolean;
  onClose: () => void;
}

// Global log buffer that persists even when console is closed
const globalLogBuffer: LogEntry[] = [];
let globalLogId = 0;
let consoleIntercepted = false;
const originalConsoleMethods = {
  log: console.log,
  warn: console.warn,
  error: console.error,
  info: console.info
};

// Export the buffer so other components can see log count
export { globalLogBuffer };

// Intercept console IMMEDIATELY on module load (before any React renders)
if (!consoleIntercepted) {
  consoleIntercepted = true;

  const addToGlobalBuffer = (level: 'log' | 'warn' | 'error' | 'info', args: any[]) => {
    // Filter out noisy SQLite connection errors that are handled internally
    const messageStr = args.map(arg => 
      typeof arg === 'object' ? JSON.stringify(arg) : String(arg)
    ).join(' ');

    const isSQLiteConnectionNoise = 
      messageStr.includes('CloseConnection: No available connection') ||
      messageStr.includes('CreateConnection: Connection') && messageStr.includes('already exists');

    if (isSQLiteConnectionNoise && level === 'error') {
      // Still log to native console for debugging, but don't show in UI
      originalConsoleMethods[level](...args);
      return;
    }

    const logEntry: LogEntry = {
      id: globalLogId++,
      timestamp: new Date().toLocaleTimeString(),
      level,
      message: args.map(arg => 
        typeof arg === 'object' ? JSON.stringify(arg, null, 2) : String(arg)
      ).join(' '),
      args
    };

    globalLogBuffer.push(logEntry);
    // Keep only last 200 logs to prevent memory issues
    if (globalLogBuffer.length > 200) {
      globalLogBuffer.shift();
    }

    // Call original method
    originalConsoleMethods[level](...args);
  };

  console.log = (...args) => addToGlobalBuffer('log', args);
  console.warn = (...args) => addToGlobalBuffer('warn', args);
  console.error = (...args) => addToGlobalBuffer('error', args);
  console.info = (...args) => addToGlobalBuffer('info', args);

  // Wire global error handlers so runtime errors surface in the console
  window.addEventListener('error', (event) => {
    const msg = event?.error?.stack || event?.message || 'Unknown error';
    addToGlobalBuffer('error', [msg]);
  });
  window.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
    const reason: any = event.reason;
    const msg = typeof reason === 'object' ? (reason?.stack || JSON.stringify(reason)) : String(reason);
    addToGlobalBuffer('error', ['Unhandled promise rejection:', msg]);
  });
}

export default function OnScreenConsole({ isVisible, onClose }: OnScreenConsoleProps) {
  const { t } = useLanguage();
  const [logs, setLogs] = useState<LogEntry[]>([...globalLogBuffer]);
  const [isMinimized, setIsMinimized] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Sync with global buffer when opened
  useEffect(() => {
    if (isVisible) {
      setLogs([...globalLogBuffer]);
      console.log('­ƒÉø Debug Console Opened - Showing all captured logs');
    }
  }, [isVisible]);

  // Keep updating from global buffer while visible
  useEffect(() => {
    if (!isVisible) return;

    const interval = setInterval(() => {
      setLogs([...globalLogBuffer]);
    }, 500); // Update every 500ms

    return () => clearInterval(interval);
  }, [isVisible]);

  // Auto-scroll to bottom when new logs arrive
  useEffect(() => {
    if (containerRef.current && !isMinimized) {
      containerRef.current.scrollTop = containerRef.current.scrollHeight;
    }
  }, [logs, isMinimized]);

  const clearLogs = () => {
    globalLogBuffer.length = 0; // Clear the global buffer
    setLogs([]);
    console.log('­ƒº╣ Debug console cleared');
  };

  // Simple code runner: executes code asynchronously and logs start/success/error
  const [codeInput, setCodeInput] = useState('');
  const safeToString = (value: any) => {
    try {
      if (value === undefined) return 'undefined';
      if (value === null) return 'null';
      if (typeof value === 'string') return value;
      if (typeof value === 'number' || typeof value === 'boolean') return String(value);
      if (value instanceof Error) return value.stack || value.message || String(value);
      return JSON.stringify(value, null, 2);
    } catch {
      try { return String(value); } catch { return '[unprintable value]'; }
    }
  };

  const runCode = async (snippet?: string, label?: string) => {
    const code = (snippet ?? codeInput).trim();
    if (!code) {
      console.warn('ÔÜá´©Å Nothing to run: code input is empty');
      return;
    }

    const title = label ? `preset: ${label}` : 'custom';
    console.info(`ÔûÂ´©Å Running ${title}...`);
    console.info('­ƒº® Command:', code);

    try {
      // Always run inside an async IIFE so top-level await works
      const fn = new Function(
        'console',
        'window',
        'globalThis',
        `return (async () => {\n${code}\n})()`
      );
      const result = await fn(console, window, globalThis);
      console.info('Ô£à Completed');
      console.info('­ƒôª Result:', safeToString(result));
      // Clear input on successful execution
      setCodeInput('');
    } catch (err: any) {
      const msg = err?.stack || err?.message || String(err);
      console.error('ÔØî Failed', msg);
    }
  };

  // Prefilled diagnostic snippets
  const presetSnippets: Record<string, string> = {
    'Force Sync': 'await db.forceSync()',
    'Force Sync (Immediate Upload)': 'await db.forceSyncImmediate()',
    'Force DB Reset': 'await localDB.forceReset()',
    'Check DB Status': 'localDB.isReady()',
    'Get Pool Stats': 'localDB.getPoolStats()',
    'Retry Now': 'await FirebaseSyncDebugger.retryNow()',
    'Sync Status': 'await FirebaseSyncDebugger.checkSyncStatus()',
    'Inspect Queue': 'FirebaseSyncDebugger.inspectQueue()',
    'Clear Broken Items (10+ attempts)': 'await FirebaseSyncDebugger.clearBrokenItems(10)',
    'Clear Queue (all)': 'await FirebaseSyncDebugger.clearQueue()',
    'Clear Queue (tracks only)': "await FirebaseSyncDebugger.clearQueue({ type: 'track' })",
    'Compare Local vs Firebase': 'await FirebaseSyncDebugger.compareLocalVsFirebase()',
    'Clear Cache & Resync': 'await FirebaseSyncDebugger.clearCacheAndResync()'
  };
  const presetDescriptions: Record<string, string> = {
    'Force Sync': 'Initiates upload + download (non-blocking). Good to hydrate fresh installs and general sync.',
    'Force Sync (Immediate Upload)': 'Uploads pending queue now (blocking upstream). Use when you need a guaranteed push.',
    'Force DB Reset': 'Force reset and re-initialize the database. Use if database is stuck.',
    'Check DB Status': 'Check if database is initialized and ready.',
    'Get Pool Stats': 'Get SQLite connection pool statistics.',
    'Retry Now': 'Refresh connectivity and re-run sync for failed items. Non-destructive.',
    'Sync Status': 'Shows network/auth state and queue summary. Read-only, no data changes.',
    'Inspect Queue': 'Prints queued operations with IDs and attempts. Read-only.',
    'Clear Broken Items (10+ attempts)': 'Removes items with 10+ failed attempts from queue. Useful to clear stuck items.',
    'Clear Queue (all)': 'Clears all queued operations. Irreversible ÔÇö follow with Force Sync.',
    'Clear Queue (tracks only)': 'Clears only track-related queued items. Irreversible.',
    'Compare Local vs Firebase': 'Shows differences between local cache and Firestore. Read-only.',
    'Clear Cache & Resync': 'Purges local caches and fetches fresh data. Use to fix stale data.'
  };
  const [selectedPreset, setSelectedPreset] = useState<string>('Force Sync');
  const insertPreset = () => {
    setCodeInput(presetSnippets[selectedPreset] || '');
  };
  const runSelectedPreset = () => runCode(presetSnippets[selectedPreset] || '', selectedPreset);

  const copyLogs = () => {
    const logText = logs.map(log => 
      `[${log.timestamp}] ${log.level.toUpperCase()}: ${log.message}`
    ).join('\n');

    navigator.clipboard.writeText(logText).then(() => {
      console.log('­ƒôï Logs copied to clipboard');
    }).catch(() => {
      console.warn('ÔØî Failed to copy logs to clipboard');
    });
  };

  const getLogColor = (level: string) => {
    switch (level) {
      case 'error': return 'text-red-400';
      case 'warn': return 'text-yellow-400';
      case 'info': return 'text-blue-400';
      default: return 'text-gray-300';
    }
  };

  const getLogIcon = (level: string) => {
    switch (level) {
      case 'error': return 'ÔØî';
      case 'warn': return 'ÔÜá´©Å';
      case 'info': return 'Ôä╣´©Å';
      default: return '­ƒôØ';
    }
  };

  if (!isVisible) return null;

  return (
    <div className="fixed inset-0 z-[9999] flex items-start justify-center bg-black/50 backdrop-blur-sm pt-20">
      <div 
        className={`bg-gray-900 border border-gray-700 rounded-lg shadow-2xl transition-all duration-300 ${
          isMinimized ? 'w-80 h-16' : 'w-11/12 max-w-4xl h-5/6 max-h-[calc(100vh-160px)]'
        }`}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-3 border-b border-gray-700 bg-gray-800 rounded-t-lg">
          <div className="flex items-center gap-2">
            <Terminal className="w-5 h-5 text-green-400" />
            <span className="text-white font-medium">{t('debugConsole.title')}</span>
            <span className="text-gray-400 text-sm">({t('debugConsole.logsCount', { count: logs.length })})</span>
          </div>

          <div className="flex items-center gap-2">
            {!isMinimized && (
              <>
                <Button
                  onClick={copyLogs}
                  variant="secondary"
                  className="p-2 text-xs"
                  title={t('debugConsole.copyAllLogs')}
                >
                  <Copy className="w-4 h-4" />
                </Button>
                <Button
                  onClick={clearLogs}
                  variant="secondary"
                  className="p-2 text-xs"
                  title={t('debugConsole.clearLogs')}
                >
                  <Trash2 className="w-4 h-4" />
                </Button>
              </>
            )}
            <Button
              onClick={() => setIsMinimized(!isMinimized)}
              variant="secondary"
              className="p-2 text-xs"
              title={isMinimized ? t('debugConsole.maximize') : t('debugConsole.minimize')}
            >
              {isMinimized ? 'Ô¼å´©Å' : 'Ô¼ç´©Å'}
            </Button>
            <Button
              onClick={onClose}
              variant="danger"
              className="p-2 text-xs"
              title={t('debugConsole.close')}
            >
              <X className="w-4 h-4" />
            </Button>
          </div>
        </div>

        {/* Console Content */}
        {!isMinimized && (
          <div 
            ref={containerRef}
            className="p-3 h-full overflow-y-auto bg-black text-sm font-mono"
            style={{ maxHeight: 'calc(100% - 160px)' }}
          >
            {logs.length === 0 ? (
              <div className="text-gray-500 text-center py-8">
                {t('debugConsole.noLogsYet')}
              </div>
            ) : (
              <div className="space-y-1">
                {logs.map((log) => (
                  <div key={log.id} className="flex gap-2 leading-relaxed">
                    <span className="text-gray-500 text-xs min-w-[80px] flex-shrink-0">
                      {log.timestamp}
                    </span>
                    <span className="text-xs min-w-[16px] flex-shrink-0">
                      {getLogIcon(log.level)}
                    </span>
                    <span className={`${getLogColor(log.level)} break-all`}>
                      {log.message}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Inline code runner panel */}
        {!isMinimized && (
          <div className="border-t border-gray-700 bg-gray-800 p-3 flex flex-col gap-2">
            <div className="flex items-center gap-2">
              <div className="text-xs text-gray-300 flex-1">{t('debugConsole.runCodeHint')}</div>
              <select
                value={selectedPreset}
                onChange={(e) => setSelectedPreset(e.target.value)}
                className="text-xs bg-gray-900 text-white border border-gray-700 rounded px-2 py-1"
                title={t('debugConsole.commonCommands')}
              >
                {Object.keys(presetSnippets).map((name) => (
                  <option key={name} value={name}>{name}</option>
                ))}
              </select>
              <Button onClick={insertPreset} variant="secondary" className="px-2 py-1 text-xs">{t('debugConsole.insert')}</Button>
              <Button onClick={runSelectedPreset} variant="primary" className="px-2 py-1 text-xs">{t('debugConsole.run')}</Button>
            </div>
            <div className="text-[11px] text-gray-400 -mt-1 mb-1">{presetDescriptions[selectedPreset]}</div>
            <div className="flex gap-2">
              <textarea
                value={codeInput}
                onChange={(e) => setCodeInput(e.target.value)}
                onKeyDown={(e) => {
                  // Ctrl+Enter or Cmd+Enter to execute
                  if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                    e.preventDefault();
                    runCode();
                  }
                }}
                className="flex-1 h-24 rounded bg-black text-white p-2 text-sm font-mono border border-gray-700"
                placeholder={t('debugConsole.codePlaceholder')}
              />
              <div className="flex flex-col gap-2">
                <Button 
                  onClick={() => runCode()} 
                  variant="primary" 
