                                <span className={`ml-2 ${isTablet ? 'text-xs' : 'text-[10px]'} px-2 py-0.5 rounded backdrop-blur-sm`} style={{ 
                                  backgroundColor: isDark ? 'rgba(6, 95, 70, 0.25)' : 'rgba(209, 250, 229, 0.95)', 
                                  color: isDark ? '#6ee7b7' : '#065f46',
