        <div className={`flex flex-col ${isTablet ? 'md:flex-row' : 'sm:flex-row'} items-start ${isTablet ? 'md:items-center' : 'sm:items-center'} justify-between gap-2 ${isTablet ? 'mb-2' : 'mb-3'}`}>
