      setDraftDrawnFields([]);
      clearSelectedFields();
      setFocusedBoundaryId(null);
      setFocusedDrawnFieldId(null);
      setTracks([]);
      setMapSelectionEvent(null);
      setShowSidebar(true);
      setSelectedStep(getWizardStepSequence(newContractLabProvider)[0] || 2);
      setShowStepModal(true);
