        console.warn('[OrdersMainPage] Failed to clear draft cache:', error);
      }
    }

    setDraftOverrideId(null);
    setDraftOverrideName(null);
    setSelectedContractId(null);
    setUploadedFields([]);
    setDrawnFields([]);
    setDraftDrawnFields([]);
    clearSelectedFields();
    setFocusedBoundaryId(null);
    setFocusedDrawnFieldId(null);
    setTracks([]);
