      t('orders.confirmDeleteContractTitle'),
      `${nextConfirmationQuip()} ${t('orders.confirmDeleteContractMessage', {
        name: contract.name,
        defaultValue: `Delete "${contract.name}"? This cannot be undone.`,
      })}`,
      {
        type: 'danger',
        confirmText: t('common.delete'),
        cancelText: t('common.cancel')
      }
    );

    if (!confirmed) return;

    try {
      await deleteDoc(doc(db, `users/${contract.clientId}/projects/${contract.id}`));

      setContracts((prev) => prev.filter((item) => item.id !== contract.id));
