                    </span>
                    {landUseValue && (
                      <span className={`${compact ? 'text-[9px] px-1.5' : 'text-[11px] px-2'} py-0.5 rounded-full font-semibold bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-200`}>
