    });

    const samplingState = new Map<string, { sampleCount: number; status: 'pending' | 'in_progress' | 'completed' }>();
    uniqueFieldBoundaries.forEach((boundary) => {
      const sampleCount = counts.get(String(boundary.id)) || 0;
