    console.log('­ƒöä Falling back to default Firestore cache...');
    try {
      db = getFirestore(app);
      console.log('Ô£à Firestore initialized with fallback cache');
    } catch (retryError) {
      console.error('ÔØî Fatal: Cannot initialize Firestore:', retryError);
