    ]);

    const duration = Date.now() - startTime;
    console.log(`Ô£à Firebase connection successful (${duration}ms)`);

    if (duration > 5000) {
      console.warn('ÔÜá´©Å  Firebase connection is slow (>5s). This may cause timeout issues.');
      console.log('­ƒÆí Consider checking your internet speed or Firebase region configuration.');
    }
  } catch (error: any) {
    const duration = Date.now() - startTime;
    console.error(`ÔØî Firebase connection test failed (${duration}ms):`, error);
    console.error('Error code:', error.code);
    console.error('Error message:', error.message);

    if (error.code === 'unavailable') {
      console.error('­ƒÆí Firebase is unreachable. Check internet connection.');
    } else if (error.code === 'permission-denied') {
      console.error('­ƒÆí Firebase permission denied. You may need to log in first.');
    } else if (error.message?.includes('timeout')) {
      console.error('­ƒÆí Firebase connection timeout. Network may be slow or Firebase may be under heavy load.');
    } else {
