  } else {
    testFirebaseConnection();
  }
} else {
  // Firebase connection test skipped in development mode
}

export { app, analytics, db, auth, isCapacitor };

import { useState, useCallback, useRef, useEffect } from 'react';
import { GpsPositionUpdate } from '../types';
import { isCapacitorApp } from '../utils/platform';
import { BleClient, BleDevice, numbersToDataView, numberToUUID } from '@capacitor-community/bluetooth-le';
import { useNativeGpsManager } from './useNativeGpsManager';
import { GpsConnectionValidator, NotificationDebouncer } from '../utils/gpsValidation';

// NMEA service UUIDs - common GPS device services
const NMEA_SERVICE_UUIDS = [
  '00001101-0000-1000-8000-00805f9b34fb', // Serial Port Profile (SPP)
  '0000fff0-0000-1000-8000-00805f9b34fb', // Generic NMEA
  '49535343-fe7d-4ae5-8fa9-9fafd205e455', // Microchip Transparent UART
  '6e400001-b5a3-f393-e0a9-e50e24dcca9e', // Nordic UART Service (NUS)
];

// Characteristic UUIDs for reading NMEA data
const NMEA_RX_CHARACTERISTIC_UUIDS = [
  '49535343-1e4d-4bd9-ba61-23c647249616', // Microchip RX
  '6e400003-b5a3-f393-e0a9-e50e24dcca9e', // Nordic UART RX
  '0000fff4-0000-1000-8000-00805f9b34fb', // Generic NMEA RX
];

interface BluetoothGPSOptions {
  onPosition?: (position: GpsPositionUpdate) => void;
  onError?: (error: string) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
}

/**
 * Hook for connecting to external GPS devices via Bluetooth
 * - Web: Uses Web Bluetooth API (browser only)
 * - Android: Uses native Bluetooth Serial (capacitor-bluetooth-serial)
 * Works with Emlid Reach RS3 and other Bluetooth GPS devices that stream NMEA
 */
export function useBluetoothGPS(options: BluetoothGPSOptions = {}) {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [lastPosition, setLastPosition] = useState<GpsPositionUpdate | null>(null);
  const [deviceName, setDeviceName] = useState<string>('');

  const deviceRef = useRef<any>(null);
  const characteristicRef = useRef<any>(null);
  const nmeaBufferRef = useRef<string>('');
  const usingNativeRef = useRef<boolean>(false);
  const connectionValidatedRef = useRef<boolean>(false);
  const dataTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const notificationDebounceRef = useRef<NodeJS.Timeout | null>(null);
  const validatorRef = useRef<GpsConnectionValidator>(new GpsConnectionValidator());
  const notificationDebouncerRef = useRef<NotificationDebouncer>(new NotificationDebouncer());
  const isNative = isCapacitorApp();

  // Use native GPS manager when available (Android app)
  const nativeGpsManager = useNativeGpsManager({
    onPosition: (position) => {
      if (usingNativeRef.current) {
        setLastPosition(position);
        options.onPosition?.(position);

        // Add to validator
        validatorRef.current.addDataPoint(position);

        // Validate native connection on first GPS data
        if (!connectionValidatedRef.current && !isConnected) {
          const validation = validatorRef.current.validateConnection();

          if (validation.isValid) {
            connectionValidatedRef.current = true;
            setIsConnected(true);

            if (dataTimeoutRef.current) {
              clearTimeout(dataTimeoutRef.current);
              dataTimeoutRef.current = null;
            }

            // Use debounced notification
            notificationDebouncerRef.current.notify('native-connect', () => {
              console.log(`­ƒÄ» Native GPS Connection Validated:`, validation);
              options.onConnect?.();
            }, 1000);
          }
        }
      }
    },
    onConnect: () => {
      if (usingNativeRef.current) {
        setIsConnecting(false);
        connectionValidatedRef.current = false;

        // Set validation timeout for native connections
        dataTimeoutRef.current = setTimeout(() => {
          if (!connectionValidatedRef.current) {
            console.warn('ÔÜá´©Å Native GPS: No data received within 30 seconds');
            options.onError?.('Connected but no GPS data received from native GPS.');
          }
        }, 30000);

        console.log('Ô£à Native GPS connected - waiting for data validation...');
      }
    },
    onDisconnect: () => {
      if (usingNativeRef.current) {
        setIsConnected(false);
        setIsConnecting(false);
        setLastPosition(null);
        setDeviceName('');
        options.onDisconnect?.();
      }
    },
    onError: (error) => {
      if (usingNativeRef.current) {
        options.onError?.(error);
      }
    }
  });

  /**
   * Parse NMEA sentence to GPS position
   */
  const parseNMEA = useCallback((sentence: string): GpsPositionUpdate | null => {
    if (!sentence.startsWith('$')) return null;

    try {
      const parts = sentence.split(',');
      const type = parts[0].substring(3); // Remove $GP or $GN prefix

      // Parse GGA sentence (most common for position)
      if (type === 'GGA') {
        // $GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47
        const latRaw = parseFloat(parts[2]);
        const latDir = parts[3];
        const lonRaw = parseFloat(parts[4]);
        const lonDir = parts[5];
        const quality = parseInt(parts[6]); // 0=invalid, 1=GPS, 2=DGPS, 4=RTK fix, 5=RTK float
        const satellites = parseInt(parts[7]);
        const hdop = parseFloat(parts[8]);
        const altitude = parseFloat(parts[9]);

        if (isNaN(latRaw) || isNaN(lonRaw)) return null;

        // Convert NMEA format to decimal degrees
        const latDeg = Math.floor(latRaw / 100);
        const latMin = latRaw - (latDeg * 100);
        const latitude = (latDeg + latMin / 60) * (latDir === 'S' ? -1 : 1);

        const lonDeg = Math.floor(lonRaw / 100);
        const lonMin = lonRaw - (lonDeg * 100);
        const longitude = (lonDeg + lonMin / 60) * (lonDir === 'W' ? -1 : 1);

        // Determine fix type
        let fixType: 'none' | 'single' | 'float' | 'fix' = 'none';
        if (quality === 1) fixType = 'single';
        else if (quality === 2) fixType = 'single'; // DGPS
        else if (quality === 5) fixType = 'float'; // RTK float
        else if (quality === 4) fixType = 'fix'; // RTK fixed

        // Log parsed coordinates for debugging
        console.log('[GPS] GGA parsed:', {
          raw: `${latRaw},${latDir} ${lonRaw},${lonDir}`,
          decimal: `${latitude.toFixed(6)}┬░${latDir} ${longitude.toFixed(6)}┬░${lonDir}`,
          quality,
          fixType,
          satellites,
          hdop,
          altitude
        });

        // Estimate accuracy based on HDOP and fix type
        let accuracy = 50; // default
        if (fixType === 'fix') accuracy = 0.05; // RTK fixed: ~2-5cm
        else if (fixType === 'float') accuracy = 0.5; // RTK float: ~50cm
        else if (fixType === 'single') accuracy = hdop * 5; // GPS: HDOP * 5m

        return {
          latitude,
          longitude,
          altitude: !isNaN(altitude) ? altitude : undefined,
          accuracy,
          fix_type: fixType,
          satellites,
          timestamp: Date.now(),
        };
      }

      // Parse RMC sentence (alternative with speed/heading)
      if (type === 'RMC') {
        // $GPRMC,123519,A,4807.038,N,01131.000,E,022.4,084.4,230394,003.1,W*6A
        const status = parts[2]; // A=active, V=void
        if (status !== 'A') return null;

        const latRaw = parseFloat(parts[3]);
        const latDir = parts[4];
        const lonRaw = parseFloat(parts[5]);
        const lonDir = parts[6];
        // parts[7] = speed in knots
        // parts[8] = heading in degrees

        if (isNaN(latRaw) || isNaN(lonRaw)) return null;

        const latDeg = Math.floor(latRaw / 100);
        const latMin = latRaw - (latDeg * 100);
        const latitude = (latDeg + latMin / 60) * (latDir === 'S' ? -1 : 1);

        const lonDeg = Math.floor(lonRaw / 100);
        const lonMin = lonRaw - (lonDeg * 100);
        const longitude = (lonDeg + lonMin / 60) * (lonDir === 'W' ? -1 : 1);

        return {
          latitude,
          longitude,
          accuracy: 10, // RMC doesn't provide accuracy
          fix_type: 'single',
          timestamp: Date.now(),
        };
      }

      return null;
    } catch (error) {
      console.error('NMEA parse error:', error);
      return null;
    }
  }, []);

  /**
   * Handle incoming data from Bluetooth characteristic
   */
  const handleCharacteristicValue = useCallback((event: any) => {
    const value = event.target.value;
    const decoder = new TextDecoder('utf-8');
    const chunk = decoder.decode(value);

    // Add to buffer
    nmeaBufferRef.current += chunk;

    // Process complete NMEA sentences (end with \r\n)
    const lines = nmeaBufferRef.current.split('\n');
    nmeaBufferRef.current = lines.pop() || ''; // Keep incomplete line in buffer

    for (const line of lines) {
      const sentence = line.trim();
      if (sentence.startsWith('$')) {
        const position = parseNMEA(sentence);
        if (position) {
          setLastPosition(position);
          options.onPosition?.(position);
        }
      }
    }
  }, [parseNMEA, options]);

  /**
   * Check if Bluetooth LE is available on this device
   */
  const checkBluetoothSupport = useCallback(async (): Promise<boolean> => {
    try {
      // Check if running on supported platform
      if (!isCapacitorApp() && !('bluetooth' in navigator)) {
        console.warn('ÔØî Bluetooth LE not supported: Not on native app and no Web Bluetooth');
        return false;
      }

      await BleClient.initialize({ androidNeverForLocation: false });

      // Check if Bluetooth is available
      const isAvailable = await BleClient.isEnabled();
      if (!isAvailable) {
        console.warn('ÔØî Bluetooth is disabled on this device');
        return false;
      }

      console.log('Ô£à Bluetooth LE is supported and enabled');
      return true;
    } catch (error: any) {
      console.error('ÔØî Bluetooth LE check failed:', error);
      return false;
    }
  }, []);

  /**
   * Connect to a Bluetooth GPS device using Bluetooth LE
   * Works on both Android (native) and Web (Chrome/Edge)
   * @param deviceAddress - Device ID from previous scan
   * @param deviceName - Device name for display
   */
  const connect = useCallback(async (deviceAddress?: string, deviceName?: string): Promise<BleDevice | null> => {
    setIsConnecting(true);

    // Use native GPS manager when available (Android app) for better Bluetooth support
    if (isCapacitorApp() && nativeGpsManager.isNative && deviceAddress) {
      console.log('­ƒô▒ Using native GPS manager for Bluetooth connection');
      console.log('­ƒöù Connecting to:', deviceAddress);

      usingNativeRef.current = true;

      const success = await nativeGpsManager.connectDevice({
        id: `bluetooth_${deviceAddress}`,
        name: deviceName || 'Bluetooth GPS Device',
        address: deviceAddress,
        connectionType: 'bluetooth' as const
      });

      if (success) {
        setDeviceName(deviceName || 'Bluetooth GPS Device');
        // Start streaming if connection successful
        await nativeGpsManager.startPositionStream();
        return { deviceId: deviceAddress, name: deviceName || 'Bluetooth GPS Device' };
      } else {
        usingNativeRef.current = false;
        setIsConnecting(false);
        return null;
      }
    }

    // Fallback to Web Bluetooth API
    usingNativeRef.current = false;
    console.log('­ƒîÉ Using Web Bluetooth API (legacy mode)');

    // Check Bluetooth support first
    const isSupported = await checkBluetoothSupport();
    if (!isSupported) {
      setIsConnecting(false);
      const errorMsg = isCapacitorApp() 
        ? 'Bluetooth LE not supported or disabled on this device. Please enable Bluetooth in device settings.'
        : 'Bluetooth LE not supported. Use a compatible browser (Chrome/Edge) or the native Android app.';
      options.onError?.(errorMsg);
      return null;
    }

    // Initialize Bluetooth LE client
    try {
      await BleClient.initialize({ androidNeverForLocation: false });
      console.log('Ô£à Bluetooth LE initialized and ready');
    } catch (e: any) {
      console.warn('Bluetooth LE initialization warning:', e.message);
      // Continue - might already be initialized
    }

    try {
      let device: BleDevice;

      // If we have a device address from previous scan, try to connect directly
      if (deviceAddress) {
        console.log('­ƒô▒ Connecting to saved device:', deviceAddress);

        // On Capacitor/Android, we can connect directly
        await BleClient.connect(deviceAddress, (disconnectedId) => {
          console.log('Device disconnected:', disconnectedId);
          setIsConnected(false);
          setDeviceName('');
          options.onDisconnect?.();
        });

        device = { deviceId: deviceAddress, name: deviceName || 'GPS Device' };
        setDeviceName(device.name);
      } else {
        // Scan and request device selection
        console.log('­ƒöì Requesting Bluetooth device...');

        device = await BleClient.requestDevice({
          optionalServices: NMEA_SERVICE_UUIDS,
        });

        console.log('­ƒô▒ Device selected:', device.name || device.deviceId);
        setDeviceName(device.name || 'GPS Device');

        // Connect to the device
        await BleClient.connect(device.deviceId, (disconnectedId) => {
          console.log('Device disconnected:', disconnectedId);
          setIsConnected(false);
          setDeviceName('');
          options.onDisconnect?.();
        });
      }

      console.log('Ô£à Connected to device:', device.deviceId);

      // Find NMEA service and characteristic
      const services = await BleClient.getServices(device.deviceId);
      console.log(`Found ${services.length} services on device`);

      let nmeaCharacteristic: { service: string; characteristic: string } | null = null;

      // Try each known service UUID
      for (const serviceUUID of NMEA_SERVICE_UUIDS) {
        const service = services.find(s => s.uuid.toLowerCase() === serviceUUID.toLowerCase());
        if (service) {
          console.log(`Found NMEA service: ${service.uuid}`);

          // Try each known RX characteristic UUID
          for (const charUUID of NMEA_RX_CHARACTERISTIC_UUIDS) {
            const char = service.characteristics.find(c => c.uuid.toLowerCase() === charUUID.toLowerCase());
            if (char && (char.properties.notify || char.properties.read)) {
              console.log(`Found NMEA characteristic: ${char.uuid}`);
              nmeaCharacteristic = { service: service.uuid, characteristic: char.uuid };
              break;
            }
          }

          // If not found, try any characteristic with notify
          if (!nmeaCharacteristic) {
            const notifyChar = service.characteristics.find(c => c.properties.notify);
            if (notifyChar) {
              console.log(`Using notify characteristic: ${notifyChar.uuid}`);
              nmeaCharacteristic = { service: service.uuid, characteristic: notifyChar.uuid };
            }
          }

          if (nmeaCharacteristic) break;
        }
      }

      if (!nmeaCharacteristic) {
        throw new Error('Could not find NMEA data characteristic. Ensure device is streaming NMEA data.');
      }

      // Start notifications on the NMEA characteristic
      await BleClient.startNotifications(
        device.deviceId,
        nmeaCharacteristic.service,
        nmeaCharacteristic.characteristic,
        (value) => {
          // Convert DataView to string
          const decoder = new TextDecoder('utf-8');
          const chunk = decoder.decode(value);

          // Add to buffer
          nmeaBufferRef.current += chunk;

          // Process complete NMEA sentences
          const lines = nmeaBufferRef.current.split('\n');
          nmeaBufferRef.current = lines.pop() || '';

          for (const line of lines) {
            const sentence = line.trim();
            if (sentence.startsWith('$')) {
              const position = parseNMEA(sentence);
              if (position) {
                setLastPosition(position);
                options.onPosition?.(position);

                // Add to validator
                validatorRef.current.addDataPoint(position, sentence);

                // Validate connection on first GPS data received
                if (!connectionValidatedRef.current && !isConnected) {
                  const validation = validatorRef.current.validateConnection();

                  if (validation.isValid) {
                    connectionValidatedRef.current = true;
                    setIsConnected(true);

                    // Clear validation timeout
                    if (dataTimeoutRef.current) {
                      clearTimeout(dataTimeoutRef.current);
                      dataTimeoutRef.current = null;
                    }

                    // Use debounced notification
                    notificationDebouncerRef.current.notify('connect', () => {
                      console.log(`­ƒÄ» GPS Connection Validated:`, validation);
                      options.onConnect?.();
                    }, 1000);
                  }
                }
              }
            }
          }
        }
      );

      deviceRef.current = device;
      setIsConnecting(false);

      // Don't call onConnect immediately - wait for GPS data validation
      connectionValidatedRef.current = false;

      // Set timeout to validate connection with actual GPS data
      dataTimeoutRef.current = setTimeout(() => {
        if (!connectionValidatedRef.current) {
          console.warn('ÔÜá´©Å No GPS data received within 30 seconds - connection may be invalid');
          options.onError?.('Connected but no GPS data received. Check device NMEA output settings.');
          disconnect();
        }
      }, 30000); // 30 second timeout

      console.log('Ô£à Bluetooth connected - waiting for GPS data validation...');
      return device;
    } catch (error: any) {
      console.error('ÔØî Bluetooth LE connection failed:', error);
      setIsConnecting(false);
      setIsConnected(false);

      let errorMsg = 'Bluetooth connection failed';

      if (error.message?.includes('User cancelled')) {
        errorMsg = 'Device selection cancelled';
      } else if (error.message?.includes('not available')) {
        errorMsg = 'Bluetooth not available. Enable Bluetooth in device settings.';
      } else if (error.message) {
        errorMsg = error.message;
      }

      options.onError?.(errorMsg);
      return null;
    }
  }, [parseNMEA, options]);

  /**
   * Disconnect from GPS device
   */
  const disconnect = useCallback(async () => {
    try {
      if (usingNativeRef.current && nativeGpsManager.isNative) {
        console.log('­ƒô▒ Disconnecting native Bluetooth GPS manager');
        await nativeGpsManager.disconnect();
        usingNativeRef.current = false;
        return;
      }

      // Legacy Web Bluetooth disconnect
      if (deviceRef.current) {
        const deviceId = typeof deviceRef.current === 'object' && 'deviceId' in deviceRef.current 
          ? deviceRef.current.deviceId 
          : deviceRef.current;

        await BleClient.disconnect(deviceId);
        console.log('Ô£à Bluetooth LE disconnected');
      }

      // Clear validation timers
      if (dataTimeoutRef.current) {
        clearTimeout(dataTimeoutRef.current);
        dataTimeoutRef.current = null;
      }
      if (notificationDebounceRef.current) {
        clearTimeout(notificationDebounceRef.current);
        notificationDebounceRef.current = null;
      }

      // Reset validation
      validatorRef.current.reset();
      notificationDebouncerRef.current.cancelAll();

      deviceRef.current = null;
      characteristicRef.current = null;
      nmeaBufferRef.current = '';
      connectionValidatedRef.current = false;

      setIsConnected(false);
      setDeviceName('');
      setLastPosition(null);
    } catch (error) {
      console.error('Disconnect error:', error);
    }
  }, [nativeGpsManager]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      disconnect();
    };
  }, [disconnect]);

  /**
   * Scan for nearby Bluetooth GPS devices
   */
  const scanDevices = useCallback(async (): Promise<BleDevice[]> => {
    try {
      // Check support first
      const isSupported = await checkBluetoothSupport();
      if (!isSupported) {
        throw new Error('Bluetooth LE not supported on this device');
      }

      console.log('­ƒöì Scanning for Bluetooth GPS devices...');

      // Request devices with GPS-related services
      const devices = await BleClient.requestLEScan({
        services: NMEA_SERVICE_UUIDS,
        allowDuplicates: false,
      }, (result) => {
        console.log('­ƒô▒ Found GPS device:', result.device.name || result.device.deviceId);
      });

      // Stop scan after 10 seconds
      setTimeout(async () => {
        await BleClient.stopLEScan();
        console.log('­ƒöì Scan completed');
      }, 10000);

      return [];
    } catch (error: any) {
      console.error('ÔØî Bluetooth scan failed:', error);
      throw error;
    }
  }, [checkBluetoothSupport]);

  /**
   * Get available/paired devices (Android only)
   */
  const getAvailableDevices = useCallback(async (): Promise<BleDevice[]> => {
    try {
      if (!isCapacitorApp()) {
        // Web: Use requestDevice for device selection
        const device = await BleClient.requestDevice({
          optionalServices: NMEA_SERVICE_UUIDS,
        });
        return [device];
      }

      // Android: Could implement getBondedDevices if needed
      return [];
    } catch (error) {
      console.error('ÔØî Failed to get available devices:', error);
      return [];
    }
  }, []);

  return {
    isConnected: usingNativeRef.current ? nativeGpsManager.isConnected : isConnected,
    isConnecting: usingNativeRef.current ? nativeGpsManager.isConnecting : isConnecting,
    lastPosition: usingNativeRef.current ? nativeGpsManager.lastPosition : lastPosition,
    deviceName: usingNativeRef.current ? nativeGpsManager.connectedDevice?.name || '' : deviceName,
    connect,
    disconnect,
    scanDevices,
    getAvailableDevices,
    checkBluetoothSupport,
    isUsingNative: usingNativeRef.current,
    nativeCapabilities: nativeGpsManager.isNative ? {
      canScanDevices: true,
      canAutoReconnect: true,
      betterPerformance: true,
      nativeBluetoothSupport: true
    } : null
  };
}

import { useEffect, useCallback, useState } from 'react';

function readStoredDark(): boolean {
  if (typeof window === 'undefined') return true;
  const raw = window.localStorage.getItem('darkMode');
  if (raw === null) return true; // default to dark if nothing stored
  try {
    if (raw === 'true' || raw === 'false') return raw === 'true';
    return Boolean(JSON.parse(raw));
  } catch (_) {
    return true;
  }
}

export function useDarkMode(): [boolean, () => void] {
  const [isDark, setIsDark] = useState<boolean>(() => readStoredDark());

  // Sync to <html> and localStorage when value changes
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const html = document.documentElement;
    if (isDark) {
      html.classList.add('dark');
    } else {
      html.classList.remove('dark');
    }
    window.localStorage.setItem('darkMode', JSON.stringify(isDark));
  }, [isDark]);

  // Listen for changes from other components/tabs
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleStorage = (event: StorageEvent) => {
      if (event.key !== 'darkMode' || event.newValue === null) return;
      try {
        const next = JSON.parse(event.newValue);
        if (typeof next === 'boolean') {
          setIsDark(next);
        }
      } catch (_) {
        // ignore parse errors
      }
    };

    const handleCustom = (event: Event) => {
      const detail = (event as CustomEvent).detail;
      if (detail && typeof detail.isDark === 'boolean') {
        setIsDark(detail.isDark);
      }
    };

    window.addEventListener('storage', handleStorage);
    window.addEventListener('dark-mode-changed', handleCustom as EventListener);

    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener('dark-mode-changed', handleCustom as EventListener);
    };
  }, []);

  // Toggle and broadcast to other listeners in this tab
  const toggleDarkMode = useCallback(() => {
    setIsDark(prev => {
      const next = !prev;
      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('dark-mode-changed', { detail: { isDark: next } }));
      }
      return next;
    });
  }, []);

  return [isDark, toggleDarkMode];
}

import { useState, useEffect } from 'react';
import { gpsAPI } from '../services/api';

interface DatabaseStatus {
  online: boolean;
  firebaseOnline: boolean;
  backendOnline: boolean;
  internetOnline: boolean;
  pendingSync: number;
  queuedItems: any[];
}

export function useDatabaseStatus() {
  const [status, setStatus] = useState<DatabaseStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const checkStatus = async () => {
    try {
      const response = await gpsAPI.getDatabaseStatus();
      setStatus(response as DatabaseStatus);
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Failed to check database status');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    checkStatus();

    // Check status every 30 seconds
    const interval = setInterval(checkStatus, 30000);

    return () => clearInterval(interval);
  }, []);

  const triggerSync = async () => {
    try {
      await gpsAPI.syncNow();
      await checkStatus(); // Refresh status
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message };
    }
  };

  return { status, loading, error, checkStatus, triggerSync };
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { GpsDevice, GpsPosition } from '../types';
import { useBluetoothGPS } from './useBluetoothGPS';
import { useTcpGPS } from './useTcpGPS';

interface DeviceStateOptions {
  onPositionUpdate?: (position: GpsPosition) => void;
  onConnectionStatusChange?: (isConnected: boolean, device?: GpsDevice) => void;
  onError?: (error: string) => void;
}

export function useDeviceState(options: DeviceStateOptions = {}) {
  const [connectedDevice, setConnectedDevice] = useState<GpsDevice | null>(null);
  const [externalGpsPosition, setExternalGpsPosition] = useState<GpsPosition | null>(null);
  const [isExternalGpsConnected, setIsExternalGpsConnected] = useState(false);
  const [lastTelemetryAt, setLastTelemetryAt] = useState<number | null>(null);
  const stalenessTimer = useRef<NodeJS.Timeout | null>(null);

  const handlePositionUpdate = useCallback((position: GpsPosition) => {
    setExternalGpsPosition(position);
    setLastTelemetryAt(position.timestamp || Date.now());
    setIsExternalGpsConnected(true);
    options.onPositionUpdate?.(position);
  }, [options.onPositionUpdate]);

  const handleConnect = useCallback((device?: GpsDevice) => {
    if (!isExternalGpsConnected) {
      setIsExternalGpsConnected(true);
      if (device) {
        setConnectedDevice(device);
      }
      options.onConnectionStatusChange?.(true, device);
    }
  }, [isExternalGpsConnected, options.onConnectionStatusChange]);

  const handleDisconnect = useCallback((device?: GpsDevice) => {
    setIsExternalGpsConnected(false);

    if (device && connectedDevice?.id === device.id) {
      setConnectedDevice(null);
      setExternalGpsPosition(null);
    }

    options.onConnectionStatusChange?.(false, device);
  }, [connectedDevice?.id, options.onConnectionStatusChange]);

  const handleError = useCallback((error: string) => {
    console.error('GPS Device Error:', error);
    setIsExternalGpsConnected(false);

    // Clear device connection state on critical errors
    if (error.includes('Failed to connect') || 
        error.includes('connection lost') || 
        error.includes('disconnected') ||
        error.includes('Cannot connect') ||
        error.includes('timeout')) {
      setConnectedDevice(null);
      setExternalGpsPosition(null);
    }

    options.onError?.(error);
  }, [options.onError]);

  // Bluetooth GPS hook
  const bluetoothGPS = useBluetoothGPS({
    onPosition: handlePositionUpdate,
    onConnect: () => handleConnect(),
    onDisconnect: () => handleDisconnect(),
    onError: handleError
  });

  // TCP/WiFi GPS hook
  const tcpGPS = useTcpGPS({
    onPosition: handlePositionUpdate,
    onConnect: () => handleConnect(),
    onDisconnect: () => handleDisconnect(),
    onError: handleError
  });

  // Guard against stale connections
  useEffect(() => {
    if (stalenessTimer.current) {
      clearTimeout(stalenessTimer.current);
    }

    if (!externalGpsPosition || !externalGpsPosition.timestamp) {
      setIsExternalGpsConnected(false);
      return;
    }

    const checkStaleness = () => {
      const ageMs = Date.now() - externalGpsPosition.timestamp;
      if (ageMs > 15000) {
        setIsExternalGpsConnected(false);
        if (ageMs > 45000) {
          setConnectedDevice(null);
          setExternalGpsPosition(null);
        }
      }
    };

    stalenessTimer.current = setTimeout(checkStaleness, 16000);

    return () => {
      if (stalenessTimer.current) {
        clearTimeout(stalenessTimer.current);
        stalenessTimer.current = null;
      }
    };
  }, [externalGpsPosition?.timestamp]);

  const connectDevice = useCallback(async (device: GpsDevice) => {
    try {
      if (device.connection_type === 'bluetooth') {
        await bluetoothGPS.connect(device.address, device.name);
      } else if (device.connection_type === 'wifi' || device.connection_type === 'tcp') {
        await tcpGPS.connect(device.address);
      }
      setConnectedDevice(device);
    } catch (error) {
      handleError(`Failed to connect to ${device.name}: ${error}`);
      throw error;
    }
  }, [bluetoothGPS, tcpGPS, handleError]);

  const disconnectDevice = useCallback(async () => {
    try {
      if (connectedDevice?.connection_type === 'bluetooth') {
        await bluetoothGPS.disconnect();
      } else if (connectedDevice?.connection_type === 'wifi' || connectedDevice?.connection_type === 'tcp') {
        await tcpGPS.disconnect();
      }
      setConnectedDevice(null);
      setExternalGpsPosition(null);
      setIsExternalGpsConnected(false);
    } catch (error) {
      handleError(`Failed to disconnect: ${error}`);
      throw error;
    }
  }, [connectedDevice?.connection_type, bluetoothGPS, tcpGPS, handleError]);

  const cleanup = useCallback(() => {
    if (stalenessTimer.current) {
      clearTimeout(stalenessTimer.current);
      stalenessTimer.current = null;
    }
  }, []);

  return {
    // State
    connectedDevice,
    externalGpsPosition,
    isExternalGpsConnected,
    lastTelemetryAt,

    // GPS Hooks (for advanced usage)
    bluetoothGPS,
    tcpGPS,

    // Actions
    connectDevice,
    disconnectDevice,
    cleanup
  };
}

/**
 * Enhanced GPS Manager Hook
 * Manages multiple GPS devices with auto-reconnection and persistence
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { GpsDevice, GpsPosition } from '../types';
import { gpsDevicePersistence } from '../services/gpsDevicePersistence';
import { useAuth } from '../context/AuthContext';
import { useBluetoothGPS } from './useBluetoothGPS';
import { useTcpGPS } from './useTcpGPS';
import { useLanguage } from './useLanguage';
import toast from 'react-hot-toast';

interface DeviceConnection {
  device: GpsDevice;
  position: GpsPosition | null;
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;
  reconnectAttempts: number;
  hook: any; // GPS hook instance
}

interface UseGpsManagerOptions {
  autoLoadDevices?: boolean;
  autoConnectFavorites?: boolean;
}

export function useGpsManager(options: UseGpsManagerOptions = {}) {
  const { autoLoadDevices = true, autoConnectFavorites = false } = options;
  const { user } = useAuth();
  const { t } = useLanguage();
  const [devices, setDevices] = useState<GpsDevice[]>([]);
  const [connections, setConnections] = useState<Map<string, DeviceConnection>>(new Map());
  const [activeDeviceId, setActiveDeviceId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const reconnectTimers = useRef<Map<string, NodeJS.Timeout>>(new Map());
  const uptimeIntervals = useRef<Map<string, NodeJS.Timeout>>(new Map());

  /**
   * Load all user devices from Firestore
   */
  const loadDevices = useCallback(async () => {
    if (!user?.uid) return;

    setIsLoading(true);
    try {
      const userDevices = await gpsDevicePersistence.getUserDevices(user.uid);
      setDevices(userDevices);

      // Auto-connect to favorites if enabled
      if (autoConnectFavorites) {
        const favorites = userDevices.filter(d => d.is_favorite);
        for (const device of favorites) {
          await connectToDevice(device);
        }
      }
    } catch (error) {
      console.error('[GPSManager] Error loading devices:', error);
      toast.error(t('common.failedToLoadGpsDevices'));
    } finally {
      setIsLoading(false);
    }
  }, [user?.uid, autoConnectFavorites]);

  /**
   * Save a new device
   */
  const saveDevice = useCallback(async (device: Partial<GpsDevice>) => {
    if (!user?.uid) return null;

    try {
      const deviceId = await gpsDevicePersistence.saveDevice(user.uid, device);
      await loadDevices();
      toast.success(t('common.deviceSavedSuccess', { name: device.name }));
      return deviceId;
    } catch (error) {
      console.error('[GPSManager] Error saving device:', error);
      toast.error(t('common.failedToSaveDevice'));
      return null;
    }
  }, [user?.uid, loadDevices]);

  /**
   * Update device
   */
  const updateDevice = useCallback(async (deviceId: string, updates: Partial<GpsDevice>) => {
    if (!user?.uid) return;

    try {
      await gpsDevicePersistence.updateDevice(user.uid, deviceId, updates);
      await loadDevices();
      toast.success(t('common.deviceUpdated'));
    } catch (error) {
      console.error('[GPSManager] Error updating device:', error);
      toast.error(t('common.failedToUpdateDevice'));
    }
  }, [user?.uid, loadDevices]);

  /**
   * Delete device
   */
  const deleteDevice = useCallback(async (deviceId: string) => {
    if (!user?.uid) return;

    // Disconnect first if connected
    if (connections.has(deviceId)) {
      await disconnectDevice(deviceId);
    }

    try {
      await gpsDevicePersistence.deleteDevice(user.uid, deviceId);
      await loadDevices();
      toast.success(t('common.deviceDeleted'));
    } catch (error) {
      console.error('[GPSManager] Error deleting device:', error);
      toast.error(t('common.failedToDeleteDevice'));
    }
  }, [user?.uid, connections, loadDevices]);

  /**
   * Connect to a GPS device
   */
  const connectToDevice = useCallback(async (device: GpsDevice) => {
    if (!user?.uid || !device.id) return;

    console.log('[GPSManager] Connecting to device:', device.name);

    // Update connection state
    setConnections(prev => {
      const newMap = new Map(prev);
      newMap.set(device.id as string, {
        device,
        position: null,
        isConnected: false,
        isConnecting: true,
        error: null,
        reconnectAttempts: 0,
        hook: null,
      });
      return newMap;
    });

    try {
      await gpsDevicePersistence.updateConnectionState(user.uid, device.id as string, 'connecting');

      // Create appropriate GPS hook based on connection type
      let hook: any;

      if (device.connection_type === 'bluetooth') {
        hook = useBluetoothGPS({
          onPosition: (position) => handleDevicePosition(device.id as string, position),
          onConnect: () => handleDeviceConnect(device.id as string),
          onDisconnect: () => handleDeviceDisconnect(device.id as string),
          onError: (error) => handleDeviceError(device.id as string, error),
        });
      } else if (device.connection_type === 'wifi' || device.connection_type === 'tcp') {
        hook = useTcpGPS({
          onPosition: (position) => handleDevicePosition(device.id as string, position),
          onConnect: () => handleDeviceConnect(device.id as string),
          onDisconnect: () => handleDeviceDisconnect(device.id as string),
          onError: (error) => handleDeviceError(device.id as string, error),
        });
      }

      // Attempt connection
      if (hook) {
        if (device.connection_type === 'bluetooth') {
          await hook.connect(device.address);
        } else {
          await hook.connect(device.address, device.config?.tcp_port || 9001);
        }

        // Start uptime tracking
        const interval = setInterval(() => {
          gpsDevicePersistence.incrementUptime(user.uid, device.id as string, 10);
        }, 10000); // Update every 10 seconds

        uptimeIntervals.current.set(device.id as string, interval);
      }
    } catch (error: any) {
      console.error('[GPSManager] Connection failed:', error);
      await handleDeviceError(device.id as string, error.message || 'Connection failed');
    }
  }, [user?.uid]);

  /**
   * Disconnect from a GPS device
   */
  const disconnectDevice = useCallback(async (deviceId: string) => {
    if (!user?.uid) return;

    const connection = connections.get(deviceId);
    if (!connection) return;

    console.log('[GPSManager] Disconnecting from device:', connection.device.name);

    // Clear reconnect timer
    const timer = reconnectTimers.current.get(deviceId);
    if (timer) {
      clearTimeout(timer);
      reconnectTimers.current.delete(deviceId);
    }

    // Clear uptime interval
    const interval = uptimeIntervals.current.get(deviceId);
    if (interval) {
      clearInterval(interval);
      uptimeIntervals.current.delete(deviceId);
    }

    // Disconnect hook
    if (connection.hook?.disconnect) {
      connection.hook.disconnect();
    }

    // Update state
    setConnections(prev => {
      const newMap = new Map(prev);
      newMap.delete(deviceId);
      return newMap;
    });

    await gpsDevicePersistence.updateConnectionState(user.uid, deviceId, 'disconnected');

    // Unset as active if it was active
    if (activeDeviceId === deviceId) {
      setActiveDeviceId(null);
    }
  }, [user?.uid, connections, activeDeviceId]);

  /**
   * Handle device position update
   */
  const handleDevicePosition = useCallback(async (deviceId: string, position: GpsPosition) => {
    if (!user?.uid) return;

    setConnections(prev => {
      const newMap = new Map(prev);
      const conn = newMap.get(deviceId);
      if (conn) {
        newMap.set(deviceId, { ...conn, position });
      }
      return newMap;
    });

    // Update position in Firestore (throttled)
    await gpsDevicePersistence.updateDevicePosition(user.uid, deviceId, position);
  }, [user?.uid]);

  /**
   * Handle device connected
   */
  const handleDeviceConnect = useCallback(async (deviceId: string) => {
    if (!user?.uid) return;

    console.log('[GPSManager] Device connected:', deviceId);

    setConnections(prev => {
      const newMap = new Map(prev);
      const conn = newMap.get(deviceId);
      if (conn) {
        newMap.set(deviceId, { 
          ...conn, 
          isConnected: true, 
          isConnecting: false,
          error: null,
          reconnectAttempts: 0,
        });
      }
      return newMap;
    });

    await gpsDevicePersistence.updateConnectionState(user.uid, deviceId, 'connected');

    // Set as active if no active device
    if (!activeDeviceId) {
      setActiveDeviceId(deviceId);
    }

    const device = devices.find(d => d.id === deviceId);
    if (device) {
      console.log(`[GPSManager] ${device.name} connected - notifications handled by GPSTracker`);
      // No toast here - GPSTracker handles all user notifications
    }
  }, [user?.uid, activeDeviceId, devices]);

  /**
   * Handle device disconnected
   */
  const handleDeviceDisconnect = useCallback(async (deviceId: string) => {
    if (!user?.uid) return;

    const connection = connections.get(deviceId);
    if (!connection) return;

    console.log('[GPSManager] Device disconnected:', connection.device.name);

    setConnections(prev => {
      const newMap = new Map(prev);
      const conn = newMap.get(deviceId);
      if (conn) {
        newMap.set(deviceId, { 
          ...conn, 
          isConnected: false, 
          isConnecting: false,
        });
      }
      return newMap;
    });

    await gpsDevicePersistence.updateConnectionState(user.uid, deviceId, 'disconnected');

    // Attempt auto-reconnect if enabled
    if (connection.device.auto_reconnect) {
      scheduleReconnect(deviceId, connection.device);
    }

    toast(`${connection.device.name} disconnected`, { icon: '­ƒô▒' });
  }, [user?.uid, connections]);

  /**
   * Handle device error
   */
  const handleDeviceError = useCallback(async (deviceId: string, errorMessage: string) => {
    if (!user?.uid) return;

    const connection = connections.get(deviceId);
    if (!connection) return;

    console.error('[GPSManager] Device error:', connection.device.name, errorMessage);

    const newReconnectAttempts = connection.reconnectAttempts + 1;

    setConnections(prev => {
      const newMap = new Map(prev);
      const conn = newMap.get(deviceId);
      if (conn) {
        newMap.set(deviceId, { 
          ...conn, 
          isConnected: false,
          isConnecting: false,
          error: errorMessage,
          reconnectAttempts: newReconnectAttempts,
        });
      }
      return newMap;
    });

    await gpsDevicePersistence.updateConnectionState(user.uid, deviceId, 'error', errorMessage);

    // Attempt auto-reconnect if enabled and under max attempts
    const maxAttempts = connection.device.max_reconnect_attempts || 5;
    if (connection.device.auto_reconnect && newReconnectAttempts < maxAttempts) {
      scheduleReconnect(deviceId, connection.device);
    } else if (newReconnectAttempts >= maxAttempts) {
      toast.error(t('common.maxReconnectAttempts', { name: connection.device.name }));
    }
  }, [user?.uid, connections, t]);

  /**
   * Schedule auto-reconnect
   */
  const scheduleReconnect = useCallback((deviceId: string, device: GpsDevice) => {
    // Clear existing timer
    const existingTimer = reconnectTimers.current.get(deviceId);
    if (existingTimer) {
      clearTimeout(existingTimer);
    }

    const delay = device.reconnect_delay_ms || 5000;
    console.log(`[GPSManager] Scheduling reconnect for ${device.name} in ${delay}ms`);

    const timer = setTimeout(() => {
      console.log(`[GPSManager] Auto-reconnecting to ${device.name}`);
      connectToDevice(device);
      reconnectTimers.current.delete(deviceId);
    }, delay);

    reconnectTimers.current.set(deviceId, timer);
  }, [connectToDevice]);

  /**
   * Get active device position
   */
  const getActivePosition = useCallback((): GpsPosition | null => {
    if (!activeDeviceId) return null;
    const conn = connections.get(activeDeviceId);
    return conn?.position || null;
  }, [activeDeviceId, connections]);

  /**
   * Get all connected positions (for multi-device mode)
   */
  const getAllPositions = useCallback((): Map<string, GpsPosition> => {
    const positions = new Map<string, GpsPosition>();
    connections.forEach((conn, deviceId) => {
      if (conn.position && conn.isConnected) {
        positions.set(deviceId, conn.position);
      }
    });
    return positions;
  }, [connections]);

  /**
   * Get best position (highest accuracy among connected devices)
   */
  const getBestPosition = useCallback((): GpsPosition | null => {
    let bestPosition: GpsPosition | null = null;
    let bestAccuracy = Infinity;

    connections.forEach(conn => {
      if (conn.position && conn.isConnected && conn.position.accuracy < bestAccuracy) {
        bestPosition = conn.position;
        bestAccuracy = conn.position.accuracy;
      }
    });

    return bestPosition;
  }, [connections]);

  // Load devices on mount
  useEffect(() => {
    if (autoLoadDevices && user?.uid) {
      loadDevices();
    }
  }, [autoLoadDevices, user?.uid, loadDevices]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Clear all timers and intervals
      reconnectTimers.current.forEach(timer => clearTimeout(timer));
      uptimeIntervals.current.forEach(interval => clearInterval(interval));
      reconnectTimers.current.clear();
      uptimeIntervals.current.clear();
    };
  }, []);

  return {
    // Device management
    devices,
    loadDevices,
    saveDevice,
    updateDevice,
    deleteDevice,
    isLoading,

    // Connection management
    connections: Array.from(connections.values()),
    connectToDevice,
    disconnectDevice,
    activeDeviceId,
    setActiveDeviceId,

    // Position access
    getActivePosition,
    getAllPositions,
    getBestPosition,

    // Utility
    isAnyDeviceConnected: connections.size > 0 && Array.from(connections.values()).some(c => c.isConnected),
    connectedCount: Array.from(connections.values()).filter(c => c.isConnected).length,
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { GpsPosition } from '../types';
import { isCapacitor, watchPosition, clearWatch, requestLocationPermission, getCurrentPosition } from '../utils/geolocation';
import { isWindowsTablet } from '../utils/deviceDetection';

export type GpsSourcePreference = 'internal' | 'external';
export type GpsSourcePolicy = 'preferred' | 'strict';

const normalizeTimestamp = (rawTimestamp: number | undefined): number => {
  if (!rawTimestamp || !Number.isFinite(rawTimestamp)) {
    return Date.now();
  }

  return rawTimestamp < 1_000_000_000_000 ? rawTimestamp * 1000 : rawTimestamp;
};

const toGpsPosition = (position: GeolocationPosition): GpsPosition => ({
  latitude: position.coords.latitude,
  longitude: position.coords.longitude,
  accuracy: position.coords.accuracy,
  altitude: position.coords.altitude || undefined,
  heading: position.coords.heading ?? undefined,
  speed: position.coords.speed ?? undefined,
  timestamp: position.timestamp,
  ...(((position as any).mocked === true) ? { mocked: true as any } : {}),
});

export function useHybridPosition(
  externalGpsSource?: GpsPosition | null,
  sourcePreference: GpsSourcePreference = 'internal',
  sourcePolicy: GpsSourcePolicy = 'preferred'
) {
  const EXTERNAL_GPS_STALE_MS = 15000;
  const [position, setPosition] = useState<GpsPosition | null>(() => {
    try {
      const saved = localStorage.getItem('lastKnownPosition');
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });
  const [error, setError] = useState<string | null>(null);
  const [isTracking, setIsTracking] = useState(false);
  const [permissionGranted, setPermissionGranted] = useState(false);
  const accuracyHistoryRef = useRef<number[]>([]);
  const [gpsPosition, setGpsPosition] = useState<GpsPosition | null>(null);
  const [networkPosition, setNetworkPosition] = useState<GpsPosition | null>(null);
  const [isMockLocation, setIsMockLocation] = useState(false);
  const [selectionTick, setSelectionTick] = useState(0);
  const [positionSource, setPositionSource] = useState<'internal' | 'external' | 'none'>('none');
  const [isExternalFallback, setIsExternalFallback] = useState(false);
  const [externalDataAgeMs, setExternalDataAgeMs] = useState<number | null>(null);
  const [refreshToken, setRefreshToken] = useState(0);

  useEffect(() => {
    if (position) {
      localStorage.setItem('lastKnownPosition', JSON.stringify(position));
    }
  }, [position]);

  useEffect(() => {
    if (sourcePreference !== 'external') {
      return;
    }

    const timer = window.setInterval(() => {
      setSelectionTick((tick) => tick + 1);
    }, 1000);

    return () => window.clearInterval(timer);
  }, [sourcePreference]);

  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

  useEffect(() => {
    const normalizedExternalGpsSource = externalGpsSource
      ? {
          ...externalGpsSource,
          timestamp: normalizeTimestamp(externalGpsSource.timestamp),
        }
      : null;

    const externalAge = normalizedExternalGpsSource
      ? Math.max(0, Date.now() - normalizedExternalGpsSource.timestamp)
      : null;
    setExternalDataAgeMs(externalAge);

    const hasFreshExternalSource = externalAge !== null && externalAge <= EXTERNAL_GPS_STALE_MS;

    let bestInternalSource: GpsPosition | null = null;
    if (!gpsPosition && networkPosition) {
      bestInternalSource = networkPosition;
    } else if (gpsPosition && !networkPosition) {
      bestInternalSource = gpsPosition;
    } else if (gpsPosition && networkPosition) {
      if (gpsPosition.accuracy < 20 || networkPosition.accuracy > 50) {
        bestInternalSource = gpsPosition;
      } else if (networkPosition.accuracy < gpsPosition.accuracy * 0.7) {
        bestInternalSource = networkPosition;
      } else {
        bestInternalSource = gpsPosition;
      }
    }

    // Handle manual source preference
    if (sourcePreference === 'external') {
      if (hasFreshExternalSource && normalizedExternalGpsSource) {
        if (!sessionStorage.getItem('external-gps-logged')) {
          console.log('­ƒø░´©Å Using external GPS source (manual selection)');
          sessionStorage.setItem('external-gps-logged', 'true');
        }
        setPosition(normalizedExternalGpsSource);
        setPositionSource('external');
        setIsExternalFallback(false);
        setError(null);
        return;
      }

      if (sourcePolicy === 'strict') {
        setPosition(null);
        setPositionSource('none');
        setIsExternalFallback(false);
        setError('External GPS selected but no fresh external data is available');
        return;
      }

      setIsExternalFallback(true);
      setError(null);
    }

    if (sourcePreference === 'internal' && gpsPosition) {
      if (!sessionStorage.getItem('internal-gps-forced')) {
        console.log('­ƒô▒ Using internal GPS (manual selection)');
        sessionStorage.setItem('internal-gps-forced', 'true');
      }
      setPosition(gpsPosition);
      setPositionSource('internal');
      setIsExternalFallback(false);
      setError(null);
      return;
    }

    if (bestInternalSource) {
      setPosition(bestInternalSource);
      setPositionSource('internal');
      return;
    }

    if (sourcePreference === 'external') {
      setError('External GPS selected but no fresh external data is available');
    } else {
      setError('No internal GPS position available');
    }
    setPosition(null);
    setPositionSource('none');
  }, [gpsPosition, networkPosition, externalGpsSource, sourcePreference, sourcePolicy, selectionTick]);

  useEffect(() => {
    let gpsId: string | number | null = null;
    let netId: string | number | null = null;
    let cancelled = false;
    const isOnWindowsTablet = isWindowsTablet();
    const isNativeCapacitor = isCapacitor() && !isOnWindowsTablet;

    const start = async () => {
      // For Windows tablets in web mode, use browser's geolocation API directly
      if (isOnWindowsTablet && !isCapacitor()) {
        console.log('­ƒ¬ƒ Windows tablet detected - using browser Geolocation API');

        if (!('geolocation' in navigator)) {
          setError('Geolocation not supported on this device');
          return;
        }

        const positionOptions: PositionOptions = {
          enableHighAccuracy: true,
          timeout: 60000,
          maximumAge: 0
        };

        // Watch position using browser API
        gpsId = navigator.geolocation.watchPosition(
          (pos) => {
            const gpsPos: GpsPosition = {
              latitude: pos.coords.latitude,
              longitude: pos.coords.longitude,
              accuracy: pos.coords.accuracy,
              altitude: pos.coords.altitude || undefined,
              altitudeAccuracy: pos.coords.altitudeAccuracy || undefined,
              heading: pos.coords.heading || undefined,
              speed: pos.coords.speed || undefined,
              timestamp: pos.timestamp
            };

            setGpsPosition(gpsPos);
            setPermissionGranted(true);
            setError(null);

            console.log('­ƒ¬ƒ Windows GPS position:', {
              lat: gpsPos.latitude.toFixed(6),
              lon: gpsPos.longitude.toFixed(6),
              accuracy: gpsPos.accuracy?.toFixed(1)
            });
          },
          (err) => {
            let errorMessage = 'Geolocation error';
            switch (err.code) {
              case err.PERMISSION_DENIED:
                errorMessage = 'Location permission denied';
                setPermissionGranted(false);
                break;
              case err.POSITION_UNAVAILABLE:
                errorMessage = 'Location unavailable';
                break;
              case err.TIMEOUT:
                errorMessage = 'Location request timed out';
                break;
            }
            console.warn('­ƒ¬ƒ Windows GPS error:', errorMessage);
            setError(errorMessage);
          },
          positionOptions
        );

        return;
      }

      // Standard Capacitor/web path
      const granted = await requestLocationPermission();
      if (!granted) {
        setError('Geolocation permission not granted');
        setPermissionGranted(false);
        return;
      }

      if (cancelled) return;

      const primeImmediatePosition = async () => {
        try {
          const quickNetworkPosition = await getCurrentPosition({
            enableHighAccuracy: false,
            timeout: 8000,
            maximumAge: 5000,
          });

          if (!cancelled && Number.isFinite(quickNetworkPosition.coords.accuracy)) {
            setNetworkPosition(toGpsPosition(quickNetworkPosition));
            setPermissionGranted(true);
          }
        } catch {
          // Best-effort warm start only.
        }

        try {
          const quickGpsPosition = await getCurrentPosition({
            enableHighAccuracy: true,
            timeout: 12000,
            maximumAge: 0,
          });

          if (!cancelled) {
            setGpsPosition(toGpsPosition(quickGpsPosition));
            setPermissionGranted(true);
            setError(null);
          }
        } catch {
          // Fall back to the live watch if the immediate fix is still not available.
        }
      };

      void primeImmediatePosition();

      gpsId = await watchPosition(
        (pos) => {
          const newAccuracy = pos.coords.accuracy;

          // Enhanced mock location detection
          const positionData = pos as any;

          // Debug: Log all position properties to see what's available
          if (!sessionStorage.getItem('position-logged')) {
            console.log('­ƒöì [Position Debug] Full position object:', {
              coords: pos.coords,
              timestamp: pos.timestamp,
              mocked: positionData.mocked,
              mockUsed: positionData.mockUsed,
              isMock: positionData.isMock,
              provider: positionData.provider,
              accuracy: newAccuracy
            });
            sessionStorage.setItem('position-logged', 'true');
          }

          // Detect mock location using multiple indicators:
          // 1. Explicit mock flags (Android)
          // 2. Very high accuracy (< 10m) combined with Capacitor platform
          // 3. Provider information if available
          const isMock = positionData.mocked === true || 
                        positionData.mockUsed === true ||
                        positionData.isMock === true ||
                        (isNativeCapacitor && newAccuracy < 10 && newAccuracy > 0) ||
                        (positionData.provider && positionData.provider.toLowerCase().includes('mock'));

          if (isMock !== (sessionStorage.getItem('is-mock') === 'true')) {
            console.log(isMock ? '­ƒø░´©Å Mock location DETECTED (Bluetooth GNSS or external GPS)' : '­ƒô▒ Using internal GPS');
            console.log('­ƒôì Accuracy:', newAccuracy, 'meters');
            console.log('­ƒöº Detection factors:', {
              mocked: positionData.mocked,
              mockUsed: positionData.mockUsed,
              isMock: positionData.isMock,
              provider: positionData.provider,
              accuracy: newAccuracy,
              isCapacitor: isNativeCapacitor
            });
            sessionStorage.setItem('is-mock', isMock.toString());
          }
          setIsMockLocation(isMock);

          if (isIOS) {
            const history = accuracyHistoryRef.current;
            const newHistory = [...history.slice(-4), newAccuracy];
            accuracyHistoryRef.current = newHistory;

            if (history.length >= 3) {
              const avgAccuracy = history.reduce((a, b) => a + b, 0) / history.length;
              if (newAccuracy > avgAccuracy * 3 && newAccuracy > 30) {
                return;
              }
            }
          }

          setGpsPosition({
            ...toGpsPosition(pos),
            accuracy: newAccuracy,
          });
          setPermissionGranted(true);
          setError(null);
        },
        (err) => {
          if (!isIOS || err.code === err.PERMISSION_DENIED) {
            console.warn('GPS position error:', err.message, 'Code:', err.code);
            setError(err.message);
          }
          if (err.code === err.PERMISSION_DENIED) {
            setPermissionGranted(false);
          }
        },
        {
          enableHighAccuracy: true,
          timeout: 60000, // 60 seconds for external GPS initialization
          maximumAge: 0,
          minimumUpdateInterval: 250,
        }
      );

      netId = await watchPosition(
        (pos) => {
          if (pos.coords.accuracy <= 100) {
            setNetworkPosition(toGpsPosition(pos));
            setPermissionGranted(true);
          }
        },
        () => {
          /* optional */
        },
        {
          enableHighAccuracy: false,
          timeout: 30000, // 30 seconds for network
          maximumAge: 5000,
          minimumUpdateInterval: 1000,
        }
      );
    };

    start();

    return () => {
      cancelled = true;
      // Handle both native and browser geolocation cleanup
      if (isWindowsTablet() && !isCapacitor() && typeof gpsId === 'number') {
        navigator.geolocation.clearWatch(gpsId);
      } else {
        void clearWatch(gpsId);
        void clearWatch(netId);
      }
    };
  }, [isIOS, refreshToken]);

  const refreshPosition = useCallback(() => {
    setError(null);
    setSelectionTick((tick) => tick + 1);
    setRefreshToken((token) => token + 1);
  }, []);

  const startTracking = () => {
    setIsTracking(true);
  };

  const stopTracking = () => {
    setIsTracking(false);
  };

  return {
    position,
    error,
    isTracking,
    startTracking,
    stopTracking,
    refreshPosition,
    permissionGranted,
    isCapacitor: isCapacitor(),
    isMockLocation,
    positionSource,
    isExternalFallback,
    externalDataAgeMs,
  } as const;
}

import { useState, useEffect, Dispatch, SetStateAction } from 'react';

/**
 * Custom hook that syncs state with localStorage
 * @param key - The localStorage key
 * @param initialValue - The initial value if no value exists in localStorage
 * @returns A stateful value and a function to update it
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, Dispatch<SetStateAction<T>>] {
  // State to store our value
  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === 'undefined') {
      return initialValue;
    }

    try {
      // Get from local storage by key
      const item = window.localStorage.getItem(key);
      if (!item) return initialValue;

      // Try to parse as JSON, if that fails treat as plain string
      try {
        return JSON.parse(item);
      } catch {
        // If it's a string type and looks like a plain string, return it
        if (typeof initialValue === 'string') {
          return item as T;
        }
        return initialValue;
      }
    } catch (error) {
      console.error(`Error loading ${key} from localStorage:`, error);
      return initialValue;
    }
  });

  // Return a wrapped version of useState's setter function that persists to localStorage
  const setValue: Dispatch<SetStateAction<T>> = (value) => {
    try {
      // Allow value to be a function so we have same API as useState
      const valueToStore = value instanceof Function ? value(storedValue) : value;

      // Save state
      setStoredValue(valueToStore);

      // Save to local storage
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      }
    } catch (error) {
      console.error(`Error saving ${key} to localStorage:`, error);
    }
  };

  return [storedValue, setValue];
}

import { useState, useCallback, useRef, useEffect } from 'react';
import GpsDeviceManager from '../plugins/GpsDeviceManager/index';
import { isCapacitorApp } from '../utils/platform';
import type { GpsPositionUpdate } from '../types';

interface NativeGpsManagerOptions {
  onPosition?: (position: GpsPositionUpdate) => void;
  onError?: (error: string) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
}

interface NativeGpsDevice {
  id: string;
  name: string;
  address: string;
  connectionType: 'bluetooth' | 'wifi' | 'serial';
  manufacturer?: string;
  model?: string;
  isConnected: boolean;
}

/**
 * Hook for native GPS device management (Android only)
 * Uses the comprehensive GPS Device Manager plugin
 * Handles Bluetooth, WiFi/TCP, and Serial/USB GPS devices
 */
export function useNativeGpsManager(options: NativeGpsManagerOptions = {}) {
  const [isConnected, setIsConnected] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [lastPosition, setLastPosition] = useState<GpsPositionUpdate | null>(null);
  const [connectedDevice, setConnectedDevice] = useState<NativeGpsDevice | null>(null);
  const [discoveredDevices, setDiscoveredDevices] = useState<NativeGpsDevice[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);

  const isNative = isCapacitorApp();
  const listenerRefs = useRef<any[]>([]);
  const callbacksRef = useRef<NativeGpsManagerOptions>(options);

  useEffect(() => {
    callbacksRef.current = options;
  }, [options]);

  // Setup event listeners
  useEffect(() => {
    if (!isNative) return;

    const setupListeners = async () => {
      try {
        // Device connection events
        const deviceConnectedListener = await GpsDeviceManager.addListener('deviceConnected', (data: any) => {
          console.log('­ƒô▒ Native GPS device connected:', data);
          setIsConnected(true);
          setIsConnecting(false);
          setConnectedDevice(data?.device || data);
          callbacksRef.current.onConnect?.();
        });

        const deviceDisconnectedListener = await GpsDeviceManager.addListener('deviceDisconnected', (data: any) => {
          console.log('­ƒô▒ Native GPS device disconnected:', data);
          setIsConnected(false);
          setIsConnecting(false);
          setConnectedDevice(null);
          setLastPosition(null);
          setIsStreaming(false);
          callbacksRef.current.onDisconnect?.();
        });

        // Position updates
        const positionUpdateListener = await GpsDeviceManager.addListener('positionUpdate', (data: any) => {
          const position: GpsPositionUpdate = {
            latitude: data.position.latitude,
            longitude: data.position.longitude,
            altitude: data.position.altitude,
            accuracy: data.position.accuracy,
            timestamp: data.position.timestamp,
            heading: data.position.heading,
            speed: data.position.speed,
            hdop: data.position.hdop,
            satellites: data.position.satellites,
            fix_type: data.position.fixType
          };

          setLastPosition(position);
          callbacksRef.current.onPosition?.(position);
        });

        // Error events
        const errorListener = await GpsDeviceManager.addListener('error', (data: any) => {
          console.error('­ƒô▒ Native GPS error:', data.error);
          callbacksRef.current.onError?.(data.error);
        });

        // Device discovery events
        const deviceFoundListener = await GpsDeviceManager.addListener('deviceFound', (data: any) => {
          console.log('­ƒô▒ GPS device found:', data);
          setDiscoveredDevices(prev => {
            // Avoid duplicates
            const device = data?.device || data;
            const exists = prev.some(d => d.id === device.id);
            return exists ? prev : [...prev, device];
          });
        });

        listenerRefs.current = [
          deviceConnectedListener,
          deviceDisconnectedListener,
          positionUpdateListener,
          errorListener,
          deviceFoundListener
        ];

      } catch (error) {
        console.error('Failed to setup native GPS listeners:', error);
      }
    };

    setupListeners();

    return () => {
      // Cleanup listeners
      listenerRefs.current.forEach(listener => {
        if (listener && listener.remove) {
          listener.remove();
        }
      });
      listenerRefs.current = [];
    };
  }, [isNative]);

  /**
   * Request runtime permissions (Bluetooth, Location)
   */
  const requestPermissions = useCallback(async (): Promise<boolean> => {
    if (!isNative) {
      console.log('Permissions not needed on web platform');
      return true;
    }

    try {
      console.log('Requesting GPS device permissions...');

      // Check current permissions first
      const currentPerms = await GpsDeviceManager.checkPermissions();
      if (currentPerms.granted) {
        console.log('Permissions already granted');
        return true;
      }

      // Request permissions
      const result = await GpsDeviceManager.requestPermissions();

      if (result.granted) {
        console.log('Ô£à Permissions granted');
        return true;
      } else {
        console.error('ÔØî Permissions denied:', result);
        callbacksRef.current.onError?.('GPS device permissions denied. Please enable Bluetooth and Location in Settings.');
        return false;
      }
    } catch (error) {
      console.error('Failed to request permissions:', error);
      callbacksRef.current.onError?.('Failed to request permissions: ' + error);
      return false;
    }
  }, [isNative]);

  /**
   * Scan for GPS devices
   */
  const scanDevices = useCallback(async (connectionTypes?: ('bluetooth' | 'wifi' | 'serial')[]) => {
    if (!isNative) {
      callbacksRef.current.onError?.('GPS device scanning requires native Android app');
      return [];
    }

    // Check/request permissions before scanning
    const hasPermissions = await requestPermissions();
    if (!hasPermissions) {
      return [];
    }

    setIsScanning(true);
    setDiscoveredDevices([]);

    try {
      console.log('­ƒôí Scanning for GPS devices...', connectionTypes);

      const result = await GpsDeviceManager.scanDevices({
        connectionTypes: connectionTypes || ['bluetooth', 'wifi', 'serial'],
        timeout: 10000
      });

      console.log('­ƒô▒ Scan completed, found devices:', result.devices);
      setDiscoveredDevices(result.devices);
      setIsScanning(false);

      return result.devices;

    } catch (error) {
      console.error('GPS device scan failed:', error);
      setIsScanning(false);
      callbacksRef.current.onError?.(`Device scan failed: ${error}`);
      return [];
    }
  }, [isNative, requestPermissions]);

  /**
   * Connect to a GPS device
   */
  const connectDevice = useCallback(async (device: Partial<NativeGpsDevice>) => {
    if (!isNative) {
      const message = 'GPS device connection requires native Android app. Use browser geolocation instead.';
      callbacksRef.current.onError?.(message);
      return false;
    }

    if (!device.address || !device.connectionType) {
      callbacksRef.current.onError?.('Device address and connection type are required');
      return false;
    }

    setIsConnecting(true);

    try {
      console.log('­ƒöî Connecting to GPS device:', device);

      const result = await GpsDeviceManager.connectDevice({
        deviceId: device.id,
        address: device.address,
        connectionType: device.connectionType,
        port: (device as any).port || 9001,
        name: device.name || 'GPS Device'
      });

      console.log('Ô£à GPS device connected successfully:', result.device);
      return true;

    } catch (error) {
      console.error('GPS device connection failed:', error);
      setIsConnecting(false);

      // Provide user-friendly error messages
      const errorMessage = error instanceof Error ? error.message : String(error);
      let friendlyMessage = `Connection failed: ${errorMessage}`;

      if (errorMessage.includes('not implemented') || errorMessage.includes('plugin')) {
        friendlyMessage = 'GPS Manager plugin is not available. Please restart the app.';
      } else if (errorMessage.includes('permission')) {
        friendlyMessage = 'Location permissions are required. Please enable location access.';
      } else if (errorMessage.includes('timeout') || errorMessage.includes('unreachable')) {
        friendlyMessage = 'Cannot reach GPS device. Check device IP address and network connection.';
      } else if (errorMessage.includes('Bluetooth')) {
        friendlyMessage = 'Bluetooth connection failed. Make sure device is paired and in range.';
      }

      callbacksRef.current.onError?.(friendlyMessage);
      return false;
    }
  }, [isNative]);

  /**
   * Disconnect from current GPS device
   */
  const disconnect = useCallback(async () => {
    if (!isNative) {
      return;
    }

    try {
      await GpsDeviceManager.disconnectDevice();
      console.log('­ƒô▒ GPS device disconnected');
    } catch (error) {
      console.error('GPS disconnect failed:', error);
    }
  }, [isNative]);

  /**
   * Start GPS position streaming
   */
  const startPositionStream = useCallback(async () => {
    if (!isNative || !isConnected) {
      return false;
    }

    try {
      await GpsDeviceManager.startPositionStream();
      setIsStreaming(true);
      console.log('­ƒôí GPS position streaming started');
      return true;
    } catch (error) {
      console.error('Failed to start GPS streaming:', error);
      callbacksRef.current.onError?.(`Failed to start streaming: ${error}`);
      return false;
    }
  }, [isNative, isConnected]);

  /**
   * Stop GPS position streaming
   */
  const stopPositionStream = useCallback(async () => {
    if (!isNative) {
      return;
    }

    try {
      await GpsDeviceManager.stopPositionStream();
      setIsStreaming(false);
      console.log('­ƒôí GPS position streaming stopped');
    } catch (error) {
      console.error('Failed to stop GPS streaming:', error);
    }
  }, [isNative]);

  /**
   * Get current GPS device status
   */
  const getStatus = useCallback(async () => {
    if (!isNative) {
      return { isConnected: false, isStreaming: false };
    }

    try {
      return await GpsDeviceManager.getStatus();
    } catch (error) {
      console.error('Failed to get GPS status:', error);
      return { isConnected: false, isStreaming: false };
    }
  }, [isNative]);

  /**
   * Quick connect to known device (Emlid Reach RS3)
   */
  const connectToReachRS3 = useCallback(async (connectionType: 'bluetooth' | 'wifi' = 'wifi') => {
    const device: Partial<NativeGpsDevice> = {
      id: 'reach_rs3',
      name: 'Emlid Reach RS3',
      address: connectionType === 'wifi' ? '192.168.42.1' : '', // Bluetooth address would be provided by user
      connectionType,
      manufacturer: 'Emlid',
      model: 'Reach RS3'
    };

    return await connectDevice(device);
  }, [connectDevice]);

  return {
    // State
    isConnected,
    isConnecting,
    isScanning,
    isStreaming,
    lastPosition,
    connectedDevice,
    discoveredDevices,
    isNative,

    // Methods
    scanDevices,
    connectDevice,
    disconnect,
    startPositionStream,
    stopPositionStream,
    getStatus,
    connectToReachRS3,
    requestPermissions
  };
}

import { useState, useCallback, useRef } from 'react';
import { GpsProject } from '../types';
import { hybridDB } from '../services/hybridDatabase';
import { useAuth } from '../context/AuthContext';

export function useProjectState() {
  const { user } = useAuth();
  const [projects, setProjects] = useState<GpsProject[]>([]);
  const [selectedProject, setSelectedProject] = useState<GpsProject | null>(null);
  const [isLoadingProjects, setIsLoadingProjects] = useState(false);
  const loadProjectsAbortController = useRef<AbortController | null>(null);

  const loadProjects = useCallback(async () => {
    // Abort any existing loading operation
    if (loadProjectsAbortController.current) {
      loadProjectsAbortController.current.abort();
    }

    // Create new abort controller for this operation
    loadProjectsAbortController.current = new AbortController();
    const { signal } = loadProjectsAbortController.current;

    if (isLoadingProjects) {
      return;
    }

    try {
      setIsLoadingProjects(true);

      if (signal.aborted) return;

      const isOffline = !navigator.onLine;

      // Ensure user ID is set
      if (user?.uid) {
        await hybridDB.setUserId(user.uid);
      } else {
        console.warn('No user UID available');
        return;
      }

      if (signal.aborted) return;

      let projectList = await hybridDB.getProjects() as GpsProject[];

      // Filter valid projects
      projectList = projectList.filter(p => p && (p.id || p.name) && typeof p === 'object');

      if (projectList.length === 0 && !isOffline) {
        // Wait for potential sync
        await new Promise(resolve => setTimeout(resolve, 2000));
        const recheckProjects = await hybridDB.getProjects() as GpsProject[];

        if (recheckProjects.length > 0 && !signal.aborted) {
          const validProjects = recheckProjects.filter(p => p && (p.id || p.name));
          setProjects(validProjects);
          const mostRecentProject = validProjects.reduce((latest: GpsProject, current: GpsProject) => {
            const latestTime = new Date(latest.updated_at || latest.created_at).getTime();
            const currentTime = new Date(current.updated_at || current.created_at).getTime();
            return currentTime > latestTime ? current : latest;
          }, validProjects[0]);
          setSelectedProject(mostRecentProject);
          return;
        }
      }

      if (signal.aborted) return;

      setProjects(projectList);

      if (projectList.length > 0) {
        const mostRecentProject = projectList.reduce((latest: GpsProject, current: GpsProject) => {
          if (!latest || !current) return latest || current;
          const latestTime = new Date(latest.updated_at || latest.created_at || 0).getTime();
          const currentTime = new Date(current.updated_at || current.created_at || 0).getTime();
          return currentTime > latestTime ? current : latest;
        }, projectList[0]);

        if (mostRecentProject?.id && !signal.aborted) {
          setSelectedProject(mostRecentProject);
        }
      } else {
        setSelectedProject(null);
      }

    } catch (error) {
      console.error('Error loading projects:', error);
      setProjects([]);
      setSelectedProject(null);
    } finally {
      setIsLoadingProjects(false);
    }
  }, [user?.uid]); // Remove isLoadingProjects from deps to prevent loops

  // Note: Removed sync-complete event listener to prevent infinite loops
  // Background sync now runs silently and UI updates on next manual refresh

  const createProject = useCallback(async (name: string, description: string = '') => {
    if (!name.trim()) {
      throw new Error('Project name is required');
    }

    const newProject = await hybridDB.createProject(name, description);
    setProjects(prev => [...prev, newProject]);
    setSelectedProject(newProject);
    return newProject;
  }, []);

  const deleteProject = useCallback(async (projectId: string | number) => {
    await hybridDB.deleteProject(projectId.toString());
    await loadProjects(); // Reload to ensure sync
  }, [loadProjects]);

  const updateProject = useCallback(async (projectId: string | number, name: string, description: string = '') => {
    await hybridDB.updateProject(projectId.toString(), name, description);

    // Update local state
    const updatedProjects = projects.map(p => 
      p.id === projectId 
        ? { ...p, name, description }
        : p
    );
    setProjects(updatedProjects);

    if (selectedProject?.id === projectId) {
      setSelectedProject({ ...selectedProject, name, description });
    }
  }, [projects, selectedProject]);

  const cleanup = useCallback(() => {
    if (loadProjectsAbortController.current) {
      loadProjectsAbortController.current.abort();
    }
  }, []);

  return {
    projects,
    selectedProject,
    setSelectedProject,
    isLoadingProjects,
    loadProjects,
    createProject,
    deleteProject,
    updateProject,
    cleanup
  };
}

/**
 * USB Serial GPS Hook
 * Connects to USB GPS devices using Web Serial API
 * Supports NMEA 0183 protocol over USB serial
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { GpsPositionUpdate } from '../types';

interface UseSerialGPSOptions {
  onPosition?: (position: GpsPositionUpdate) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
  onError?: (error: Error) => void;
}

interface SerialGPSState {
  isConnected: boolean;
  isConnecting: boolean;
  deviceInfo: { name: string; vendorId?: number; productId?: number } | null;
  lastPosition: GpsPositionUpdate | null;
  error: string | null;
}

export function useSerialGPS(options: UseSerialGPSOptions = {}) {
  const [state, setState] = useState<SerialGPSState>({
    isConnected: false,
    isConnecting: false,
    deviceInfo: null,
    lastPosition: null,
    error: null,
  });

  const portRef = useRef<SerialPort | null>(null);
  const readerRef = useRef<ReadableStreamDefaultReader<Uint8Array> | null>(null);
  const nmeaBufferRef = useRef<string>('');

  // Use refs for callbacks to avoid dependency issues
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  // Check if Web Serial API is supported
  const isSupported = useCallback(() => {
    return 'serial' in navigator;
  }, []);

  // Parse NMEA sentence
  const parseNMEA = useCallback((sentence: string): GpsPositionUpdate | null => {
    const parts = sentence.split(',');

    // Handle GGA (Fix data)
    if (parts[0] === '$GPGGA' || parts[0] === '$GNGGA') {
      const lat = parseFloat(parts[2]);
      const latDir = parts[3];
      const lon = parseFloat(parts[4]);
      const lonDir = parts[5];
      const quality = parseInt(parts[6]);
      const satellites = parseInt(parts[7]);
      const hdop = parseFloat(parts[8]);
      const altitude = parseFloat(parts[9]);

      if (isNaN(lat) || isNaN(lon)) return null;

      // Convert NMEA coordinates to decimal degrees
      const latitude = (Math.floor(lat / 100) + (lat % 100) / 60) * (latDir === 'S' ? -1 : 1);
      const longitude = (Math.floor(lon / 100) + (lon % 100) / 60) * (lonDir === 'W' ? -1 : 1);

      return {
        latitude,
        longitude,
        altitude: altitude || 0,
        accuracy: hdop * 5 || 10, // Rough accuracy estimate from HDOP
        heading: 0,
        speed: 0,
        timestamp: Date.now(),
        source: 'usb-serial',
        satellites: satellites || 0,
        fix_quality: quality,
      };
    }

    // Handle RMC (Recommended Minimum)
    if (parts[0] === '$GPRMC' || parts[0] === '$GNRMC') {
      const status = parts[2];
      if (status !== 'A') return null; // A = valid, V = invalid

      const lat = parseFloat(parts[3]);
      const latDir = parts[4];
      const lon = parseFloat(parts[5]);
      const lonDir = parts[6];
      const speed = parseFloat(parts[7]); // knots
      const heading = parseFloat(parts[8]);

      if (isNaN(lat) || isNaN(lon)) return null;

      const latitude = (Math.floor(lat / 100) + (lat % 100) / 60) * (latDir === 'S' ? -1 : 1);
      const longitude = (Math.floor(lon / 100) + (lon % 100) / 60) * (lonDir === 'W' ? -1 : 1);

      return {
        latitude,
        longitude,
        altitude: 0,
        accuracy: 10,
        heading: heading || 0,
        speed: (speed || 0) * 0.514444, // Convert knots to m/s
        timestamp: Date.now(),
        source: 'usb-serial',
      };
    }

    return null;
  }, []);

  // Process incoming NMEA data
  const processData = useCallback((data: string) => {
    // Only log data in debug mode or when explicitly needed
    // console.log('[SerialGPS] Received data:', data.substring(0, 100));
    nmeaBufferRef.current += data;
    const sentences = nmeaBufferRef.current.split(/\r?\n/);
    nmeaBufferRef.current = sentences.pop() || ''; // Keep incomplete sentence

    for (const sentence of sentences) {
      const trimmed = sentence.trim();
      if (!trimmed.startsWith('$')) continue;

      // Only log if it's a position sentence (GGA, RMC) or important status
      const isPositionSentence = trimmed.startsWith('$GPGGA') || trimmed.startsWith('$GNGGA') ||
                                 trimmed.startsWith('$GPRMC') || trimmed.startsWith('$GNRMC');

      const position = parseNMEA(trimmed);
      if (position) {
        console.log('[SerialGPS] Ô£ô Valid GPS fix received:', {
          lat: position.latitude.toFixed(6),
          lon: position.longitude.toFixed(6),
          satellites: position.satellites,
          accuracy: position.accuracy?.toFixed(1)
        });
        setState(prev => ({ ...prev, lastPosition: position }));
        optionsRef.current.onPosition?.(position);
      } else if (isPositionSentence) {
        // Only log position sentences that failed to parse (indicates waiting for fix)
        // But only occasionally to avoid spam
        if (Math.random() < 0.01) { // Log ~1% of failed attempts
          console.log('[SerialGPS] ÔÅ│ Waiting for GPS fix...');
        }
      }
    }
  }, [parseNMEA]);

  // Read from serial port
  const startReading = useCallback(async (port: SerialPort) => {
    try {
      console.log('[SerialGPS] Starting to read from serial port');
      const reader = port.readable?.getReader();
      if (!reader) throw new Error('Could not get reader from port');

      readerRef.current = reader;
      const decoder = new TextDecoder();

      console.log('[SerialGPS] Reader obtained, beginning read loop');
      while (true) {
        const { value, done } = await reader.read();
        if (done) {
          console.log('[SerialGPS] Read completed (done=true)');
          break;
        }

        const text = decoder.decode(value);
        processData(text);
      }
    } catch (error: any) {
      if (error.name !== 'NetworkError') {
        console.error('Serial read error:', error);
        setState(prev => ({ ...prev, error: error.message }));
        optionsRef.current.onError?.(error);
      }
    }
  }, [processData]);

  // Connect to a serial port
  const connect = useCallback(async (port?: SerialPort) => {
    if (!isSupported()) {
      const error = new Error('Web Serial API not supported in this browser');
      setState(prev => ({ ...prev, error: error.message }));
      optionsRef.current.onError?.(error);
      return;
    }

    // If already connected to the same port, don't reconnect
    if (portRef.current && state.isConnected) {
      console.log('Already connected to a port');
      // If trying to connect to the same port, just return
      if (!port || port === portRef.current) {
        return;
      }
    }

    setState(prev => ({ ...prev, isConnecting: true, error: null }));

    try {
      // If no port provided, request one from user
      const selectedPort = port || await navigator.serial.requestPort();

      // Check if port is already open
      if (!selectedPort.readable || !selectedPort.writable) {
        // Try common GPS baud rates in order of popularity
        const baudRates = [9600, 4800, 38400, 19200];
        let opened = false;

        for (const baudRate of baudRates) {
          try {
            console.log(`[SerialGPS] Attempting to open port at ${baudRate} baud`);
            await selectedPort.open({ 
              baudRate,
              dataBits: 8,
              stopBits: 1,
              parity: 'none',
              flowControl: 'none'
            });
            console.log(`[SerialGPS] Successfully opened port at ${baudRate} baud`);
            opened = true;
            break;
          } catch (err: any) {
            console.warn(`[SerialGPS] Failed to open at ${baudRate} baud:`, err.message);
            // If already open at different baud rate, that's OK
            if (err.message?.includes('already open')) {
              opened = true;
              break;
            }
          }
        }

        if (!opened) {
          throw new Error('Failed to open serial port at any supported baud rate');
        }
      } else {
        console.log('[SerialGPS] Port already open, reusing connection');
      }

      const info = selectedPort.getInfo();
      portRef.current = selectedPort;

      setState(prev => ({
        ...prev,
        isConnected: true,
        isConnecting: false,
        deviceInfo: {
          name: 'USB GPS Device',
          vendorId: info.usbVendorId,
          productId: info.usbProductId,
        },
      }));

      optionsRef.current.onConnect?.();

      // Start reading data
      startReading(selectedPort);

    } catch (error: any) {
      console.error('Serial connection error:', error);
      setState(prev => ({
        ...prev,
        isConnecting: false,
        isConnected: false,
        error: error.message,
      }));
      optionsRef.current.onError?.(error);
    }
  }, [isSupported, startReading, state.isConnected]);

  // Auto-detect and connect to saved USB device
  const autoConnect = useCallback(async () => {
    if (!isSupported()) return;

    try {
      const ports = await navigator.serial.getPorts();
      if (ports.length > 0) {
        console.log(`Found ${ports.length} saved USB serial device(s), connecting to first...`);
        await connect(ports[0]);
      }
    } catch (error) {
      console.warn('Auto-connect failed:', error);
    }
  }, [isSupported, connect]);

  // Get list of previously authorized ports
  const getAuthorizedPorts = useCallback(async () => {
    if (!isSupported()) return [];

    try {
      const ports = await navigator.serial.getPorts();
      return ports.map((port, index) => {
        const info = port.getInfo();
        return {
          port,
          name: `USB GPS Device ${index + 1}`,
          vendorId: info.usbVendorId,
          productId: info.usbProductId,
        };
      });
    } catch (error) {
      console.error('Error getting authorized ports:', error);
      return [];
    }
  }, [isSupported]);

  // Disconnect
  const disconnect = useCallback(async () => {
    try {
      if (readerRef.current) {
        await readerRef.current.cancel();
        readerRef.current.releaseLock();
        readerRef.current = null;
      }

      if (portRef.current) {
        await portRef.current.close();
        portRef.current = null;
      }

      setState({
        isConnected: false,
        isConnecting: false,
        deviceInfo: null,
        lastPosition: null,
        error: null,
      });

      optionsRef.current.onDisconnect?.();
    } catch (error) {
      console.error('Disconnect error:', error);
    }
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      disconnect();
    };
  }, [disconnect]);

  return {
    ...state,
    isSupported: isSupported(),
    connect,
    autoConnect,
    disconnect,
    getAuthorizedPorts,
  };
}

import { useState, useCallback, useRef } from 'react';
import { GpsTrack, GpsPosition } from '../types';
import { hybridDB } from '../services/hybridDatabase';
import { useTracks } from './useTracks';

interface TrackingStateOptions {
  onTrackingStarted?: (track: GpsTrack) => void;
  onTrackingStopped?: () => void;
  onSampleAdded?: (sampleNumber: number) => void;
  onError?: (error: string) => void;
}

export function useTrackingState(options: TrackingStateOptions = {}) {
  const [isStartingTracking, setIsStartingTracking] = useState(false);
  const [isAddingSample, setIsAddingSample] = useState(false);
  const [sampleCount, setSampleCount] = useState(0);
  const [currentTrack, setCurrentTrack] = useState<GpsTrack | null>(null);
  const lastSavedPosition = useRef<GpsPosition | null>(null);

  const { tracks, setTracks, loadTracks } = useTracks();

  // Helper to calculate distance between two points (Haversine formula)
  const calculateDistance = useCallback((lat1: number, lon1: number, lat2: number, lon2: number): number => {
    const R = 6371e3; // Earth's radius in meters
    const ¤å1 = lat1 * Math.PI / 180;
    const ¤å2 = lat2 * Math.PI / 180;
    const ╬ö¤å = (lat2 - lat1) * Math.PI / 180;
    const ╬ö╬╗ = (lon2 - lon1) * Math.PI / 180;

    const a = Math.sin(╬ö¤å/2) * Math.sin(╬ö¤å/2) +
              Math.cos(¤å1) * Math.cos(¤å2) *
              Math.sin(╬ö╬╗/2) * Math.sin(╬ö╬╗/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

    return R * c;
  }, []);

  const saveGpsPoint = useCallback(async (position: GpsPosition) => {
    if (!position || !currentTrack) {
      return;
    }

    // Throttling: Check if moved at least 2 meters or if it's the first point
    if (lastSavedPosition.current) {
      const dist = calculateDistance(
        lastSavedPosition.current.latitude,
        lastSavedPosition.current.longitude,
        position.latitude,
        position.longitude
      );
      if (dist < 2) {
        return;
      }
    }

    try {
      await hybridDB.addGpsPoint(
        currentTrack.id.toString(),
        position.latitude,
        position.longitude,
        position.altitude,
        position.accuracy
      );

      lastSavedPosition.current = position;

      // Update tracks state directly without database refresh
      const newPoint = {
        id: Date.now(),
        track_id: currentTrack.id,
        latitude: position.latitude,
        longitude: position.longitude,
        altitude: position.altitude,
        accuracy: position.accuracy,
        timestamp: new Date().toISOString()
      };

      setTracks(prev => prev.map(t => 
        t.id === currentTrack.id 
          ? { ...t, gps_points: [...(t.gps_points || []), newPoint] }
          : t
      ));
    } catch (error) {
      console.error('Error saving GPS point:', error);
      options.onError?.('Failed to save GPS point');
    }
  }, [currentTrack, calculateDistance, setTracks, options.onError]);

  const startTracking = useCallback(async (
    projectId: string | number,
    trackName?: string,
    fieldBoundaryId?: number
  ) => {
    setIsStartingTracking(true);

    try {
      // Use sequential number instead of timestamp for default name
      const name = trackName || `Track ${tracks.length + 1}`;
      const newTrack = await hybridDB.createTrack(
        projectId.toString(), 
        name, 
        fieldBoundaryId?.toString()
      );

      setCurrentTrack(newTrack);
      setSampleCount(0);
      lastSavedPosition.current = null;

      // Add the new track to the tracks list with empty points
      const trackDetail = { ...newTrack, gps_points: [], samples: [] };
      setTracks(prev => [...prev, trackDetail]);

      options.onTrackingStarted?.(newTrack);
      return newTrack;
    } catch (error) {
      console.error('Error starting track:', error);
      options.onError?.('Failed to start tracking');
      throw error;
    } finally {
      setIsStartingTracking(false);
    }
  }, [setTracks, options.onTrackingStarted, options.onError]);

  const stopTracking = useCallback(async (projectId?: string | number) => {
    if (!currentTrack) return;

    try {
      setCurrentTrack(null);
      lastSavedPosition.current = null;
      setSampleCount(0);

      if (projectId) {
        await loadTracks(projectId.toString());
      }

      options.onTrackingStopped?.();
    } catch (error) {
      console.error('Error stopping track:', error);
      options.onError?.('Failed to stop tracking');
    }
  }, [currentTrack, loadTracks, options.onTrackingStopped, options.onError]);

  const addSample = useCallback(async (position: GpsPosition, sampleName?: string) => {
    if (!currentTrack || !position) return;

    const newSampleNumber = sampleCount + 1;
    setIsAddingSample(true);

    try {
      const name = sampleName || `Sample #${newSampleNumber}`;

      await hybridDB.addSample(
        currentTrack.id.toString(),
        position.latitude,
        position.longitude,
        name
      );

      setSampleCount(newSampleNumber);

      // Update tracks state directly
      const newSample = {
        id: Date.now(),
        track_id: currentTrack.id.toString(),
        latitude: position.latitude,
        longitude: position.longitude,
        name,
        sample_number: newSampleNumber,
        timestamp: new Date().toISOString(),
        created_at: new Date().toISOString()
      };

      setTracks(prev => prev.map(t => 
        t.id === currentTrack.id 
          ? { ...t, samples: [...(t.samples || []), newSample] }
          : t
      ));

      options.onSampleAdded?.(newSampleNumber);
      return newSample;
    } catch (error) {
      console.error('Error adding sample:', error);
      options.onError?.('Failed to add sample');
      throw error;
    } finally {
      setIsAddingSample(false);
    }
  }, [currentTrack, sampleCount, setTracks, options.onSampleAdded, options.onError]);

  const deleteTrack = useCallback(async (trackId: number) => {
    try {
      await hybridDB.deleteTrack(trackId.toString());
      setTracks(prev => prev.filter(t => t !== null && t.id !== trackId));
    } catch (error) {
      console.error('Error deleting track:', error);
      options.onError?.('Failed to delete track');
      throw error;
    }
  }, [setTracks, options.onError]);

  const assignTrack = useCallback(async (trackId: number, fieldBoundaryId: number | null) => {
    try {
      await hybridDB.updateTrack(trackId.toString(), { 
        field_boundary_id: fieldBoundaryId ? fieldBoundaryId.toString() : null 
      });

      // Update local track state
      setTracks(prev => prev.map(t => 
        t.id === trackId 
          ? { ...t, field_boundary_id: fieldBoundaryId?.toString() || null }
          : t
      ));
    } catch (error) {
      console.error('Error assigning track:', error);
      options.onError?.('Failed to assign track');
      throw error;
    }
  }, [setTracks, options.onError]);

  return {
    // State
    tracks,
    currentTrack,
    sampleCount,
    isStartingTracking,
    isAddingSample,

    // Actions
    startTracking,
    stopTracking,
    addSample,
    saveGpsPoint,
    deleteTrack,
    assignTrack,
    loadTracks,

    // Utils
    calculateDistance
  };
}

import { useCallback, useState } from 'react';
import { hybridDB } from '../services/hybridDatabase';
import type { GpsTrack, GpsTrackDetail } from '../types';

export function useTracks() {
  const [tracks, setTracks] = useState<GpsTrackDetail[]>([]);
  const [currentTrack, setCurrentTrack] = useState<GpsTrack | null>(null);
  const [sampleCount, setSampleCount] = useState(0);

  const loadTracks = useCallback(async (projectId?: string | number | null) => {
    if (!projectId) {
      setTracks([]);
      setCurrentTrack(null);
      setSampleCount(0);
      return [] as GpsTrackDetail[];
    }

    const list = await hybridDB.getTracks(projectId.toString());
    const tracksList = Array.isArray(list) ? list : [];

    const alreadyDetailed = tracksList.every((track: any) => (
      Array.isArray(track?.gps_points) && Array.isArray(track?.samples)
    ));

    let valid: GpsTrackDetail[];
    if (alreadyDetailed) {
      valid = tracksList.filter(Boolean) as GpsTrackDetail[];
    } else {
      const details: Array<GpsTrackDetail | null> = [];
      const batchSize = 6;

      for (let index = 0; index < tracksList.length; index += batchSize) {
        const batch = tracksList.slice(index, index + batchSize);
        const batchDetails = await Promise.all(
          batch.map(async (track: any) => {
            try {
              return await hybridDB.getTrack(track.id);
            } catch {
              return null;
            }
          })
        );
        details.push(...(batchDetails as Array<GpsTrackDetail | null>));
      }

      valid = details.filter(Boolean) as GpsTrackDetail[];
    }

    setTracks(valid);

    const active = (valid.find(t => (t as any)?.is_active) || valid[0]) as GpsTrack | undefined;
    setCurrentTrack(active || null);
    const activeSampleCount = active && (active as any).samples ? (active as any).samples.length : 0;
    setSampleCount(activeSampleCount);
    return valid;
  }, []);

  const refreshTrack = useCallback(async (trackId: string | number) => {
    try {
      const detail = await hybridDB.getTrack(trackId as string);
      if (detail) {
        setTracks(prev => prev.map(t => (t && t.id === trackId ? detail : t)).filter(Boolean) as GpsTrackDetail[]);
        // Also update currentTrack if it's the same track to show samples on map
        setCurrentTrack(prev => (prev && prev.id === trackId ? detail : prev));
        // Update sample count for sidebar
        if (detail.id === trackId) {
          setSampleCount(detail.samples?.length ?? 0);
        }
      }
      return detail as GpsTrackDetail | null;
    } catch (error) {
      console.error('[useTracks] Error refreshing track:', error);
      return null;
    }
  }, []);

  return {
    tracks,
    setTracks,
    currentTrack,
    setCurrentTrack,
    sampleCount,
    setSampleCount,
    loadTracks,
    refreshTrack,
  } as const;
}

/**
 * Windows Geolocation Hook
 * Uses the browser's Geolocation API for Windows tablets and desktop browsers
 * Provides a consistent interface similar to Capacitor's geolocation
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { GpsPosition } from '../types';
import { logger } from './logger';

interface UseWindowsGeolocationOptions {
  enableHighAccuracy?: boolean;
  timeout?: number;
  maximumAge?: number;
  onPosition?: (position: GpsPosition) => void;
  onError?: (error: string) => void;
}

interface WindowsGeolocationState {
  position: GpsPosition | null;
  error: string | null;
  isTracking: boolean;
  isAvailable: boolean;
}

export function useWindowsGeolocation(options: UseWindowsGeolocationOptions = {}) {
  const {
    enableHighAccuracy = true,
    timeout = 10000,
    maximumAge = 0,
    onPosition,
    onError
  } = options;

  const [state, setState] = useState<WindowsGeolocationState>({
    position: null,
    error: null,
    isTracking: false,
    isAvailable: 'geolocation' in navigator
  });

  const watchIdRef = useRef<number | null>(null);
  const optionsRef = useRef(options);

  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  // Convert browser GeolocationPosition to our GpsPosition format
  const convertPosition = useCallback((pos: GeolocationPosition): GpsPosition => {
    return {
      latitude: pos.coords.latitude,
      longitude: pos.coords.longitude,
      accuracy: pos.coords.accuracy,
      altitude: pos.coords.altitude || undefined,
      altitudeAccuracy: pos.coords.altitudeAccuracy || undefined,
      heading: pos.coords.heading || undefined,
      speed: pos.coords.speed || undefined,
      timestamp: pos.timestamp
    };
  }, []);

  // Start tracking position
  const startTracking = useCallback(() => {
    if (!('geolocation' in navigator)) {
      const error = 'Geolocation is not supported by this browser';
      setState(prev => ({ ...prev, error, isTracking: false }));
      optionsRef.current.onError?.(error);
      logger.error('Geolocation not supported', null, { component: 'WindowsGeolocation' });
      return;
    }

    if (watchIdRef.current !== null) {
      logger.warn('Already tracking location', { component: 'WindowsGeolocation' });
      return;
    }

    logger.info('Starting Windows geolocation tracking', { 
      enableHighAccuracy, 
      timeout, 
      maximumAge 
    });

    setState(prev => ({ ...prev, isTracking: true, error: null }));

    const positionOptions: PositionOptions = {
      enableHighAccuracy,
      timeout,
      maximumAge
    };

    // Start watching position
    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => {
        const gpsPosition = convertPosition(pos);

        logger.debug('Windows GPS position received', {
          lat: gpsPosition.latitude,
          lon: gpsPosition.longitude,
          accuracy: gpsPosition.accuracy
        });

        setState(prev => ({ 
          ...prev, 
          position: gpsPosition, 
          error: null 
        }));

        optionsRef.current.onPosition?.(gpsPosition);
      },
      (error) => {
        let errorMessage = 'Unknown geolocation error';

        switch (error.code) {
          case error.PERMISSION_DENIED:
            errorMessage = 'Location permission denied. Please enable location access in your browser settings.';
            break;
          case error.POSITION_UNAVAILABLE:
            errorMessage = 'Location information is unavailable. Make sure location services are enabled.';
            break;
          case error.TIMEOUT:
            errorMessage = 'Location request timed out. Please try again.';
            break;
        }

        logger.error('Windows geolocation error', error, { 
          component: 'WindowsGeolocation',
          code: error.code,
          message: error.message
        });

        setState(prev => ({ 
          ...prev, 
          error: errorMessage 
        }));

        optionsRef.current.onError?.(errorMessage);
      },
      positionOptions
    );

    logger.info('Windows geolocation watch started', { watchId: watchIdRef.current });
  }, [enableHighAccuracy, timeout, maximumAge, convertPosition]);

  // Stop tracking position
  const stopTracking = useCallback(() => {
    if (watchIdRef.current !== null) {
      logger.info('Stopping Windows geolocation tracking', { watchId: watchIdRef.current });
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
      setState(prev => ({ ...prev, isTracking: false }));
    }
  }, []);

  // Get current position once (not continuous tracking)
  const getCurrentPosition = useCallback((): Promise<GpsPosition> => {
    return new Promise((resolve, reject) => {
      if (!('geolocation' in navigator)) {
        reject(new Error('Geolocation not supported'));
        return;
      }

      const positionOptions: PositionOptions = {
        enableHighAccuracy,
        timeout,
        maximumAge
      };

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const gpsPosition = convertPosition(pos);
          resolve(gpsPosition);
        },
        (error) => {
          let errorMessage = 'Failed to get current position';

          switch (error.code) {
            case error.PERMISSION_DENIED:
              errorMessage = 'Location permission denied';
              break;
            case error.POSITION_UNAVAILABLE:
              errorMessage = 'Location unavailable';
              break;
            case error.TIMEOUT:
              errorMessage = 'Location request timed out';
              break;
          }

          reject(new Error(errorMessage));
        },
        positionOptions
      );
    });
  }, [enableHighAccuracy, timeout, maximumAge, convertPosition]);

  // Request permission (browsers handle this automatically on first access)
  const requestPermission = useCallback(async (): Promise<boolean> => {
    try {
      // Try to get position - this will trigger permission prompt if needed
      await getCurrentPosition();
      return true;
    } catch (error) {
      logger.error('Permission request failed', error, { component: 'WindowsGeolocation' });
      return false;
    }
  }, [getCurrentPosition]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (watchIdRef.current !== null) {
        navigator.geolocation.clearWatch(watchIdRef.current);
        watchIdRef.current = null;
      }
    };
  }, []);

  return {
    ...state,
    startTracking,
    stopTracking,
    getCurrentPosition,
    requestPermission
  };
}

