type ProviderSheetContent = {
  name: string;
  rows?: Array<Record<string, unknown>>;
  aoa?: Array<Array<string | number>>;
};

const buildProviderSheet = (
  compiledFields: CompiledFieldRow[],
  options: CompletedProjectWorkbookOptions,
): ProviderSheetContent => {
  const labProvider = options.labProvider || options.projectData?.labProvider || 'agrolab';
  const labels = getWorkbookLabels(options.language);

  if (labProvider === 'lufa_nrw') {
    return {
      name: labels.sheets.lufa,
      aoa: buildLufaBegleitscheinAoa(compiledFields, options),
    };
  }

  if (labProvider === 'pbs') {
    return {
      name: labels.sheets.pbs,
      aoa: generatePbsCsv(buildExportDraft(options, compiledFields))
        .trimEnd()
        .split(/\r?\n/)
        .map((line) => line.split(';').map((cell) => translateAgrolabCellValue(cell, options.language))),
    };
  }

  if (labProvider === 'documentation_only') {
    return {
      name: labels.sheets.documentation,
      aoa: buildDocumentationSheetAoa(compiledFields, options),
    };
  }

  return {
    name: labels.sheets.agrolab,
    aoa: buildAgrolabSheetAoa(compiledFields, options),
  };
};

const autosizeColumns = (sheet: XLSX.WorkSheet, rows: Array<Record<string, unknown>>) => {
  const headers = rows.length > 0 ? Object.keys(rows[0]) : [];
  sheet['!cols'] = headers.map((header) => {
    const widestValue = rows.reduce((max, row) => {
      const valueLength = toStringValue(row[header]).length;
      return Math.max(max, valueLength);
    }, header.length);

    return { wch: Math.min(Math.max(widestValue + 2, 12), 36) };
  });
};

const autosizeAoaColumns = (sheet: XLSX.WorkSheet, aoa: Array<Array<string | number>>) => {
  const maxColumns = aoa.reduce((max, row) => Math.max(max, row.length), 0);
  sheet['!cols'] = Array.from({ length: maxColumns }, (_, columnIndex) => {
    const widestValue = aoa.reduce((max, row) => {
      const valueLength = toStringValue(row[columnIndex]).length;
      return Math.max(max, valueLength);
    }, 10);

    return { wch: Math.min(Math.max(widestValue + 2, 10), 40) };
  });
};

const appendJsonSheet = (workbook: XLSX.WorkBook, name: string, rows: Array<Record<string, unknown>>) => {
  const normalizedRows = rows.length > 0 ? rows : [{ Message: 'No rows available' }];
  const sheet = XLSX.utils.json_to_sheet(normalizedRows);
  autosizeColumns(sheet, normalizedRows);
  XLSX.utils.book_append_sheet(workbook, sheet, name.slice(0, 31));
};

const appendAoaSheet = (workbook: XLSX.WorkBook, name: string, aoa: Array<Array<string | number>>) => {
  const normalizedRows = aoa.length > 0 ? aoa : [['No rows available']];
  const sheet = XLSX.utils.aoa_to_sheet(normalizedRows);
  autosizeAoaColumns(sheet, normalizedRows);
  XLSX.utils.book_append_sheet(workbook, sheet, name.slice(0, 31));
};

export const downloadCompletedProjectWorkbook = (options: CompletedProjectWorkbookOptions): string => {
  const workbook = XLSX.utils.book_new();
  const compiledFields = compileProjectFields(options);
  const overviewRows = buildOverviewSheetRows(options, compiledFields);
  const fieldRows = buildFieldSheetRows(compiledFields, options.language);
  const providerSheet = buildProviderSheet(compiledFields, options);
  const lufaResultRows = buildLufaResultSheetRows(options);
  const labels = getWorkbookLabels(options.language);

  if (providerSheet.aoa) {
    appendAoaSheet(workbook, providerSheet.name, providerSheet.aoa);
  } else {
    appendJsonSheet(workbook, providerSheet.name, providerSheet.rows || []);
  }
  if (lufaResultRows.length > 0) {
    appendJsonSheet(workbook, labels.sheets.lufaResults, lufaResultRows);
  }
  appendJsonSheet(workbook, labels.sheets.overview, overviewRows);
  appendJsonSheet(workbook, labels.sheets.fields, fieldRows);

  const fileDate = new Date().toISOString().slice(0, 10);
  const providerLabel = formatProviderLabel(options.labProvider || options.projectData?.labProvider, options.language).toLowerCase().replace(/\s+/g, '_');
  const fileName = `${sanitizeFileName(options.contractName) || 'project'}_${providerLabel}_${fileDate}.xlsx`;
  const output = XLSX.write(workbook, {
    type: 'array',
    bookType: 'xlsx',
  });
  const blob = new Blob([output], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });

  return downloadBlob(blob, fileName);
};

export const downloadCompletedProjectShapes = async (options: CompletedProjectWorkbookOptions): Promise<string> => {
  const featureCollection = buildShapeExportFeatureCollection(options);
  if (featureCollection.features.length === 0) {
    throw new Error('No polygon boundaries available for shapes export');
  }

  const fileDate = new Date().toISOString().slice(0, 10);
  const providerLabel = formatProviderLabel(options.labProvider || options.projectData?.labProvider, options.language).toLowerCase().replace(/\s+/g, '_');
  const fileRoot = `${sanitizeFileName(options.contractName) || 'project'}_${providerLabel}_${fileDate}`;
  const zipOutput = await shpwrite.zip(featureCollection, {
    folder: fileRoot,
    filename: fileRoot,
    outputType: 'blob',
    compression: 'STORE',
    prj: WGS84_PRJ,
    types: {
      polygon: 'fields',
    },
  });

  const blob = zipOutput instanceof Blob
    ? zipOutput
    : new Blob([toZipBlobPart(zipOutput)], { type: 'application/zip' });

  return downloadBlob(blob, `${fileRoot}.zip`);
};

/**
 * Conflict Resolution Strategy for Hybrid Database
 * Handles conflicts between offline edits and server changes
 */

export type ConflictResolution = 'client-wins' | 'server-wins' | 'merge' | 'prompt-user';

export interface DataVersion {
  version: number;
  timestamp: number;
  checksum: string;
}

export interface ConflictData<T = any> {
  id: string;
  clientVersion: T & DataVersion;
  serverVersion: T & DataVersion;
  baseVersion?: T & DataVersion; // Last known common version
}

export interface ConflictResolutionResult<T = any> {
  resolved: T;
  strategy: ConflictResolution;
  metadata?: {
    mergedFields?: string[];
    conflicts?: string[];
  };
}

/**
 * Conflict resolver for hybrid database operations
 * Uses Last-Write-Wins (LWW) strategy with optional manual resolution
 */
export class ConflictResolver {
  private strategy: ConflictResolution;

  constructor(defaultStrategy: ConflictResolution = 'server-wins') {
    this.strategy = defaultStrategy;
  }

  /**
   * Resolve conflict between client and server versions
   */
  resolve<T extends Record<string, any>>(
    conflict: ConflictData<T>,
    customStrategy?: ConflictResolution
  ): ConflictResolutionResult<T> {
    const strategy = customStrategy || this.strategy;

    switch (strategy) {
      case 'client-wins':
        return this.resolveClientWins(conflict);

      case 'server-wins':
        return this.resolveServerWins(conflict);

      case 'merge':
        return this.resolveMerge(conflict);

      case 'prompt-user':
        // This should be handled by UI layer
        throw new Error('User prompt required - handle in UI');

      default:
        // Fallback to server-wins
        return this.resolveServerWins(conflict);
    }
  }

  /**
   * Client version takes precedence
   */
  private resolveClientWins<T>(conflict: ConflictData<T>): ConflictResolutionResult<T> {
    return {
      resolved: conflict.clientVersion,
      strategy: 'client-wins'
    };
  }

  /**
   * Server version takes precedence (safest default)
   */
  private resolveServerWins<T>(conflict: ConflictData<T>): ConflictResolutionResult<T> {
    return {
      resolved: conflict.serverVersion,
      strategy: 'server-wins'
    };
  }

  /**
   * Attempt to merge both versions
   * Uses Last-Write-Wins for each field
   */
  private resolveMerge<T extends Record<string, any>>(
    conflict: ConflictData<T>
  ): ConflictResolutionResult<T> {
    const { clientVersion, serverVersion, baseVersion } = conflict;
    const merged: any = { ...serverVersion }; // Start with server
    const mergedFields: string[] = [];
    const conflicts: string[] = [];

    // For each field in client version
    for (const key in clientVersion) {
      if (key === 'version' || key === 'timestamp' || key === 'checksum') {
        continue; // Skip metadata fields
      }

      const clientValue = clientVersion[key];
      const serverValue = serverVersion[key];
      const baseValue = baseVersion?.[key];

      // Client changed but server didn't - use client
      if (clientValue !== baseValue && serverValue === baseValue) {
        merged[key] = clientValue;
        mergedFields.push(key);
      }
      // Both changed differently - use timestamp to decide
      else if (clientValue !== serverValue && clientValue !== baseValue && serverValue !== baseValue) {
        // Last-Write-Wins: compare timestamps
        if (clientVersion.timestamp > serverVersion.timestamp) {
          merged[key] = clientValue;
          mergedFields.push(key);
        }
        conflicts.push(key);
      }
      // Server changed but client didn't - already in merged (server base)
    }

    // Update metadata
    merged.version = Math.max(clientVersion.version, serverVersion.version) + 1;
    merged.timestamp = Date.now();
    merged.checksum = this.calculateChecksum(merged);

    return {
      resolved: merged,
      strategy: 'merge',
      metadata: {
        mergedFields,
        conflicts
      }
    };
  }

  /**
   * Check if two versions conflict
   */
  hasConflict<T extends Record<string, any>>(
    clientVersion: T & DataVersion,
    serverVersion: T & DataVersion
  ): boolean {
    // No conflict if versions match
    if (clientVersion.version === serverVersion.version) {
      return false;
    }

    // No conflict if checksums match (same data)
    if (clientVersion.checksum === serverVersion.checksum) {
      return false;
    }

    // Check if any fields actually differ
    for (const key in clientVersion) {
      if (key === 'version' || key === 'timestamp' || key === 'checksum') {
        continue;
      }

      if (clientVersion[key] !== serverVersion[key]) {
        return true; // Found a difference
      }
    }

    return false;
  }

  /**
   * Calculate checksum for data consistency check
   */
  private calculateChecksum(data: any): string {
    const str = JSON.stringify(data, Object.keys(data).sort());
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash).toString(36);
  }

  /**
   * Add version metadata to data
   */
  static addVersionMetadata<T extends Record<string, any>>(
    data: T,
    version: number = 1
  ): T & DataVersion {
    const resolver = new ConflictResolver();
    return {
      ...data,
      version,
      timestamp: Date.now(),
      checksum: resolver.calculateChecksum(data)
    };
  }

  /**
   * Check if data has version metadata
   */
  static hasVersionMetadata(data: any): data is any & DataVersion {
    return (
      typeof data === 'object' &&
      data !== null &&
      'version' in data &&
      'timestamp' in data &&
      'checksum' in data
    );
  }
}

/**
 * Default conflict resolver instance
 * Uses server-wins strategy as safest default
 */
export const conflictResolver = new ConflictResolver('server-wins');

/**
 * Database Migration System
 * Handles schema upgrades for local SQLite database
 * 
 * Improvements:
 * - Migration history tracking with metadata
 * - Rollback support for failed migrations
 * - Migration validation
 * - Better error handling
 */

import { SQLiteDBConnection } from '@capacitor-community/sqlite';
import { logger } from './logger';

export const CURRENT_SCHEMA_VERSION = 4;

interface Migration {
  version: number;
  description: string;
  up: (db: SQLiteDBConnection) => Promise<void>;
  down?: (db: SQLiteDBConnection) => Promise<void>; // Rollback support
}

interface MigrationRecord {
  version: number;
  description: string;
  applied_at: string;
  duration_ms: number;
  success: boolean;
  error_message?: string;
}

const migrations: Migration[] = [
  {
    version: 4,
    description: 'Convert numeric timestamps to ISO strings for consistency',
    up: async (db: SQLiteDBConnection) => {
      console.log('[Migration v4] Converting timestamps to ISO strings...');

      // Helper to check if column exists before querying
      const columnExists = async (table: string, column: string): Promise<boolean> => {
        try {
          const result = await db.query(`PRAGMA table_info(${table});`);
          if (result.values) {
            return result.values.some((col: any) => col.name === column);
          }
          return false;
        } catch {
          return false;
        }
      };

      // Helper to update a table's timestamp columns
      const updateTableTimestamps = async (table: string, columns: string[]) => {
        try {
          // Check if table exists first
          const tableCheck = await db.query(
            `SELECT name FROM sqlite_master WHERE type='table' AND name='${table}';`
          );
          if (!tableCheck.values || tableCheck.values.length === 0) {
            console.log(`[Migration v4] Table ${table} does not exist, skipping`);
            return;
          }

          // Filter columns to only those that exist
          const existingColumns: string[] = [];
          for (const col of columns) {
            if (await columnExists(table, col)) {
              existingColumns.push(col);
            }
          }

          if (existingColumns.length === 0) {
            console.log(`[Migration v4] No timestamp columns found in ${table}, skipping`);
            return;
          }

          const result = await db.query(`SELECT id, ${existingColumns.join(', ')} FROM ${table}`);
          if (!result.values || result.values.length === 0) return;

          for (const row of result.values) {
            const updates: string[] = [];
            const params: any[] = [];
            let needsUpdate = false;

            for (const col of existingColumns) {
              const val = row[col];
              // Check if value is a number (milliseconds)
              if (typeof val === 'number' && val > 1000000000) {
                updates.push(`${col} = ?`);
                params.push(new Date(val).toISOString());
                needsUpdate = true;
              }
            }

            if (needsUpdate) {
              params.push(row.id);
              await db.run(
                `UPDATE ${table} SET ${updates.join(', ')} WHERE id = ?`,
                params
              );
            }
          }
        } catch (e) {
          console.warn(`[Migration v4] Failed to update ${table}:`, e);
        }
      };

      await updateTableTimestamps('projects', ['created_at', 'updated_at']);
      await updateTableTimestamps('tracks', ['started_at', 'stopped_at', 'created_at']);
      await updateTableTimestamps('gps_points', ['timestamp', 'synced_at']);
      await updateTableTimestamps('samples', ['timestamp', 'created_at', 'lab_exported_at']);
      await updateTableTimestamps('field_boundaries', ['created_at']);
      await updateTableTimestamps('devices', ['last_connected', 'created_at', 'updated_at']);

      console.log('[Migration v4] Timestamp conversion complete');
    }
  },
  {
    version: 2,
    description: 'Add missing fields to tracks, samples, gps_points, and devices tables',
    up: async (db: SQLiteDBConnection) => {
      console.log('[Migration v2] Starting migration...');

      try {
        // Helper to check if column exists
        const columnExists = async (table: string, column: string): Promise<boolean> => {
          try {
            const result = await db.query(`PRAGMA table_info(${table});`);
            if (result.values) {
              return result.values.some((col: any) => col.name === column);
            }
            return false;
          } catch {
            return false;
          }
        };

        // Add field_boundary_id to tracks if not exists
        if (!(await columnExists('tracks', 'field_boundary_id'))) {
          await db.execute(`ALTER TABLE tracks ADD COLUMN field_boundary_id TEXT;`);
          console.log('[Migration v2] Added field_boundary_id to tracks');
