import axios from 'axios';

/**
 * OSRM Service for route calculation
 * Uses Open Source Routing Machine for navigation
 */

// OSRM server endpoints (prioritized list)
const OSRM_SERVERS = [
  'https://router.project-osrm.org',  // Official OSRM demo server
  'https://routing.openstreetmap.de', // OSM Germany routing
];

interface OSRMRoute {
  distance: number; // meters
  duration: number; // seconds
  geometry: {
    type: 'LineString';
    coordinates: number[][]; // [lon, lat] format
  };
  steps: OSRMStep[];
}

interface OSRMStep {
  distance: number;
  duration: number;
  instruction: string;
  name: string;
  maneuver?: {
    type: string;
    modifier?: string;
    location: [number, number];
  };
}

interface OSRMResponse {
  code: string;
  routes: OSRMRoute[];
  waypoints?: any[];
}

interface RouteOptions {
  alternatives?: boolean;
  profile?: 'driving' | 'walking' | 'cycling';
}

class OSRMService {
  private baseUrl: string = OSRM_SERVERS[0];

  /**
   * Calculate route between two points
   * @param start - Starting coordinate as [lat, lon]
   * @param end - Ending coordinate as [lat, lon]
   * @param options - Route calculation options
   */
  async calculateRoute(
    start: [number, number],
    end: [number, number],
    options: RouteOptions = {}
  ): Promise<OSRMResponse> {
    const { alternatives = true, profile = 'driving' } = options;

    try {
      // OSRM uses lon,lat format (not lat,lon), so we need to swap
      const coordinates = `${start[1]},${start[0]};${end[1]},${end[0]}`;
      const alternativesParam = alternatives ? '&alternatives=true' : '';
      const url = `${this.baseUrl}/route/v1/${profile}/${coordinates}?overview=full&steps=true&geometries=geojson${alternativesParam}`;

      console.log('­ƒîÉ OSRM Request:', {
        server: this.baseUrl,
        profile,
        from: `${start[0]},${start[1]}`,
        to: `${end[0]},${end[1]}`,
        url
      });

      const response = await axios.get(url, { timeout: 10000 });

      console.log('­ƒôí OSRM Response:', {
        code: response.data.code,
        numRoutes: response.data.routes?.length,
        waypoints: response.data.waypoints?.length
      });

      if (response.data.code !== 'Ok' || !response.data.routes?.[0]) {
        throw new Error(`OSRM returned: ${response.data.code || 'No route found'}`);
      }

      // Return the routes with geometry in GeoJSON format
      return {
        code: response.data.code,
        routes: response.data.routes.map((route: any) => ({
          distance: route.distance,
          duration: route.duration,
          geometry: route.geometry, // Already in GeoJSON format
          steps: route.legs[0]?.steps.map((step: any) => ({
            distance: step.distance,
            duration: step.duration,
            instruction: this.getManeuverInstruction(step.maneuver),
            name: step.name || 'Unnamed road',
            maneuver: step.maneuver ? {
              type: step.maneuver.type,
              modifier: step.maneuver.modifier,
              location: step.maneuver.location
            } : undefined
          })) || []
        })),
        waypoints: response.data.waypoints
      };
    } catch (error) {
      console.error('ÔØî OSRM routing error:', error);
      if (axios.isAxiosError(error)) {
        console.error('Response data:', error.response?.data);
        console.error('Response status:', error.response?.status);
      }
      throw new Error(`Failed to calculate route: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Generate human-readable instruction from maneuver
   */
  private getManeuverInstruction(maneuver: any): string {
    if (!maneuver) return 'Continue';

    const type = maneuver.type;
    const modifier = maneuver.modifier;

    const instructions: Record<string, string> = {
      'turn': modifier ? `Turn ${modifier}` : 'Turn',
      'new name': 'Continue',
      'depart': 'Depart',
      'arrive': 'Arrive at destination',
      'merge': modifier ? `Merge ${modifier}` : 'Merge',
      'on ramp': 'Take the ramp',
      'off ramp': 'Take the exit',
      'fork': modifier ? `Keep ${modifier} at the fork` : 'Keep at the fork',
      'end of road': modifier ? `Turn ${modifier} at the end of the road` : 'Turn at the end of the road',
      'continue': 'Continue straight',
      'roundabout': 'Enter the roundabout',
      'rotary': 'Enter the rotary',
      'roundabout turn': modifier ? `At the roundabout, take the ${modifier} exit` : 'Exit the roundabout',
    };

    return instructions[type] || 'Continue';
  }

  /**
   * Try alternative OSRM server if primary fails
   */
  async tryAlternativeServer(): Promise<void> {
    const currentIndex = OSRM_SERVERS.indexOf(this.baseUrl);
    const nextIndex = (currentIndex + 1) % OSRM_SERVERS.length;
    this.baseUrl = OSRM_SERVERS[nextIndex];
    console.log(`Switched to alternative OSRM server: ${this.baseUrl}`);
  }
}

export const osrmService = new OSRMService();

/**
 * Role-Based Access Control (RBAC) Service
 * Manages user roles and permissions for the soil sampling platform
 */

import type { UserRole } from '../types';
import { auth } from '../firebase';
import { firebaseGPS } from './firebaseSync';

export interface UserWithRole {
  uid: string;
  email: string;
  role: UserRole;
  organization_id?: string;
  displayName?: string;
  created_at: string;
  lastActive: string;
}

export interface Permission {
  resource: string;
  action: 'create' | 'read' | 'update' | 'delete' | 'export';
  granted: boolean;
}

/**
 * Role permissions matrix
 * Defines what each role can do
 */
const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  admin: [
    'users:*',
    'projects:*',
    'samples:*',
    'exports:*',
    'organizations:*',
    'settings:*'
  ],
  consultant: [
    'projects:read',
    'projects:create',
    'projects:update',
    'samples:read',
    'samples:create',
    'samples:update',
    'exports:create',
    'exports:read',
    'users:read' // Can view users in their organization
  ],
  client: [
    'projects:read',
    'samples:read',
    'exports:read'
  ],
  lab_manager: [
    'exports:read',
    'exports:create',
    'samples:read',
    'samples:update', // Can update lab-related fields only
    'projects:read'
  ],
  technician: [
    'projects:read',
    'samples:create',
    'samples:read',
    'samples:update'
  ]
};

/**
 * Check if a role has a specific permission
 */
export function hasPermission(role: UserRole, resource: string, action: string): boolean {
  const permissions = ROLE_PERMISSIONS[role] || [];

  // Check for exact match
  const permissionKey = `${resource}:${action}`;
  if (permissions.includes(permissionKey)) {
    return true;
  }

  // Check for wildcard match
  const wildcardKey = `${resource}:*`;
  if (permissions.includes(wildcardKey)) {
    return true;
  }

  return false;
}

/**
 * Get user role from Firestore
 */
export async function getUserRole(uid: string): Promise<UserRole | null> {
  try {
    const userDoc = await firebaseGPS.getUserDocument(uid);
    return (userDoc?.role as UserRole) || null;
  } catch (error) {
    console.error('Error fetching user role:', error);
    return null;
  }
}

/**
 * Get current user's role
 */
export async function getCurrentUserRole(): Promise<UserRole | null> {
  const user = auth.currentUser;
  if (!user) return null;

  return getUserRole(user.uid);
}

/**
 * Check if current user has permission
 */
export async function currentUserCan(resource: string, action: string): Promise<boolean> {
  const role = await getCurrentUserRole();
  if (!role) return false;

  return hasPermission(role, resource, action);
}

/**
 * Update user role (admin only)
 */
export async function updateUserRole(uid: string, role: UserRole): Promise<void> {
  // Check if current user is admin
  const currentRole = await getCurrentUserRole();
  if (currentRole !== 'admin') {
    throw new Error('Only administrators can update user roles');
  }

  try {
    await firebaseGPS.updateUserRole(uid, role);
  } catch (error: any) {
    console.error('Error updating user role:', error);
    throw new Error(`Failed to update user role: ${error.message}`);
  }
}

/**
 * Get human-readable role name
 */
export function getRoleName(role: UserRole): string {
  const roleNames: Record<UserRole, string> = {
    admin: 'Administrator',
    client: 'Client',
    consultant: 'Consultant',
    lab_manager: 'Lab Manager',
    technician: 'Technician'
  };
  return roleNames[role] || role;
}

/**
 * Get role description
 */
export function getRoleDescription(role: UserRole): string {
  const descriptions: Record<UserRole, string> = {
    admin: 'Full system access, can manage users and organizations',
    client: 'View projects and samples, download exports',
    consultant: 'Create and manage projects, perform sampling, export data',
    lab_manager: 'Manage laboratory exports and sample analysis data',
    technician: 'Perform field sampling and data entry'
  };
  return descriptions[role] || '';
}

/**
 * Get all available roles
 */
export function getAllRoles(): UserRole[] {
  return ['admin', 'consultant', 'lab_manager', 'technician', 'client'];
}

/**
 * Validate if a user can access another user's data
 */
export async function canAccessUserData(
  currentUserId: string,
  targetUserId: string
): Promise<boolean> {
  // User can always access their own data
  if (currentUserId === targetUserId) {
    return true;
  }

  const currentRole = await getUserRole(currentUserId);

  // Admins can access anyone's data
  if (currentRole === 'admin') {
    return true;
  }

  // Check if users are in the same organization
  const currentUser = await firebaseGPS.getUserDocument(currentUserId);
  const targetUser = await firebaseGPS.getUserDocument(targetUserId);

  if (
    currentUser?.organization_id &&
    targetUser?.organization_id &&
    currentUser.organization_id === targetUser.organization_id
  ) {
    // Consultants can access data from their organization
    if (currentRole === 'consultant') {
      return true;
    }
  }

  return false;
}

/**
 * Check if user can export samples
 */
export async function canExportSamples(): Promise<boolean> {
  return await currentUserCan('exports', 'create');
}

/**
 * Check if user can manage users
 */
export async function canManageUsers(): Promise<boolean> {
  const role = await getCurrentUserRole();
  return role === 'admin';
}

/**
 * Check if user can create projects
 */
export async function canCreateProjects(): Promise<boolean> {
  return await currentUserCan('projects', 'create');
}

/**
 * Get permissions for a role
 */
export function getRolePermissions(role: UserRole): Permission[] {
  const permissions: Permission[] = [];
  const rolePerms = ROLE_PERMISSIONS[role] || [];

  // Parse permissions into structured format
  const resources = ['users', 'projects', 'samples', 'exports', 'organizations', 'settings'];
  const actions: Array<'create' | 'read' | 'update' | 'delete' | 'export'> = [
    'create',
    'read',
    'update',
    'delete',
    'export'
  ];

  for (const resource of resources) {
    for (const action of actions) {
      permissions.push({
        resource,
        action,
        granted: hasPermission(role, resource, action)
      });
    }
  }

  return permissions;
}

/**
