 */

import type { SQLiteDBConnection } from '@capacitor-community/sqlite';

export interface SchemaValidationResult {
  valid: boolean;
  errors: string[];
  warnings: string[];
  tables: {
    [tableName: string]: {
      exists: boolean;
      columns: string[];
      missingColumns?: string[];
