/**
 * Validate SQLite database schema
 */
export async function validateSQLiteSchema(db: SQLiteDBConnection): Promise<SchemaValidationResult> {
  const result: SchemaValidationResult = {
    valid: true,
    errors: [],
    warnings: [],
    tables: {}
  };

  try {
    // Get list of all tables
    const tablesQuery = await db.query(
      "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%';"
    );

    const existingTables = new Set(
      tablesQuery.values?.map((row: any) => row.name) || []
    );

    // Check each expected table
    for (const [tableName, expectedColumns] of Object.entries(EXPECTED_SCHEMA)) {
      if (!existingTables.has(tableName)) {
        result.valid = false;
        result.errors.push(`Missing table: ${tableName}`);
        result.tables[tableName] = {
          exists: false,
          columns: []
        };
        continue;
      }

      // Get table columns
      const columnsQuery = await db.query(`PRAGMA table_info(${tableName});`);
      const actualColumns = columnsQuery.values?.map((col: any) => col.name) || [];

      const actualSet = new Set(actualColumns);
      const expectedSet = new Set(expectedColumns);

      const missingColumns = expectedColumns.filter(col => !actualSet.has(col));
      const extraColumns = actualColumns.filter(col => !expectedSet.has(col));

      result.tables[tableName] = {
        exists: true,
        columns: actualColumns,
        missingColumns,
        extraColumns
      };

      if (missingColumns.length > 0) {
        result.valid = false;
        result.errors.push(
          `Table '${tableName}' missing columns: ${missingColumns.join(', ')}`
        );
      }

      if (extraColumns.length > 0) {
        result.warnings.push(
          `Table '${tableName}' has extra columns: ${extraColumns.join(', ')}`
        );
      }
    }

    // Check for unexpected tables
    const expectedTableNames = new Set(Object.keys(EXPECTED_SCHEMA));
    for (const tableName of existingTables) {
      if (!expectedTableNames.has(tableName) && tableName !== 'kv_store') {
        result.warnings.push(`Unexpected table found: ${tableName}`);
      }
    }

  } catch (error) {
    result.valid = false;
    result.errors.push(`Schema validation failed: ${error}`);
  }

  return result;
}

/**
 * Get human-readable validation report
 */
export function formatValidationReport(result: SchemaValidationResult): string {
  const lines: string[] = [];

  lines.push('='.repeat(60));
  lines.push('DATABASE SCHEMA VALIDATION REPORT');
  lines.push('='.repeat(60));
  lines.push('');

  if (result.valid) {
    lines.push('Ô£à Schema validation PASSED');
  } else {
    lines.push('ÔØî Schema validation FAILED');
  }

  lines.push('');

  if (result.errors.length > 0) {
    lines.push('ERRORS:');
    result.errors.forEach(err => lines.push(`  ÔØî ${err}`));
    lines.push('');
  }

  if (result.warnings.length > 0) {
    lines.push('WARNINGS:');
    result.warnings.forEach(warn => lines.push(`  ÔÜá´©Å  ${warn}`));
    lines.push('');
  }

  lines.push('TABLE DETAILS:');
  lines.push('-'.repeat(60));

  for (const [tableName, info] of Object.entries(result.tables)) {
    if (!info.exists) {
      lines.push(`ÔØî ${tableName}: MISSING`);
      continue;
    }

    const status = (info.missingColumns?.length || 0) > 0 ? 'ÔØî' : 'Ô£à';
    lines.push(`${status} ${tableName}: ${info.columns.length} columns`);

    if (info.missingColumns && info.missingColumns.length > 0) {
      lines.push(`     Missing: ${info.missingColumns.join(', ')}`);
    }

    if (info.extraColumns && info.extraColumns.length > 0) {
      lines.push(`     Extra: ${info.extraColumns.join(', ')}`);
    }
  }

  lines.push('='.repeat(60));

  return lines.join('\n');
}

/**
 * Log validation results to console
 */
export function logValidationResults(result: SchemaValidationResult): void {
  console.log(formatValidationReport(result));

  // Also log structured data for debugging
  console.log('­ƒôè Schema validation details:', {
    valid: result.valid,
    errorCount: result.errors.length,
    warningCount: result.warnings.length,
    tables: Object.keys(result.tables).length
  });
}

/**
 * SQLite Connection Pool
 * Manages a pool of SQLite connections to prevent conflicts and crashes
 */

import { SQLiteConnection, SQLiteDBConnection } from '@capacitor-community/sqlite';

interface PooledConnection {
  connection: SQLiteDBConnection;
  inUse: boolean;
  lastUsed: number;
}

export class SQLiteConnectionPool {
  private connections: Map<string, PooledConnection> = new Map();
  private waitQueue: Array<{
    resolve: (conn: SQLiteDBConnection) => void;
    reject: (error: Error) => void;
    timeout: NodeJS.Timeout;
  }> = [];
  private creatingConnection = false;

  private maxConnections = 3; // Conservative limit for mobile
  private connectionTimeout = 10000; // 10 seconds
  private idleTimeout = 30000; // 30 seconds before closing idle connection

  constructor(
    private sqlite: SQLiteConnection,
    private dbName: string,
    private encrypted = false,
    private mode = 'no-encryption',
    private version = 1
  ) {}

  /**
   * Acquire a connection from the pool
   */
  async acquire(): Promise<SQLiteDBConnection> {
    // Try to find an available connection
    for (const [id, pooled] of this.connections.entries()) {
      if (!pooled.inUse) {
        pooled.inUse = true;
        pooled.lastUsed = Date.now();
        console.log(`ÔÖ╗´©Å Reusing connection ${id}`);
        return pooled.connection;
      }
    }

    // Create new connection if under limit and no other creation is in-flight
    if (this.connections.size < this.maxConnections && !this.creatingConnection) {
      try {
        this.creatingConnection = true;
        const conn = await this.createConnection();
        const id = this.generateConnectionId();

        this.connections.set(id, {
          connection: conn,
          inUse: true,
          lastUsed: Date.now()
        });

        console.log(`Ô£à Created new connection ${id} (${this.connections.size}/${this.maxConnections})`);
        return conn;
      } catch (error) {
        console.error('ÔØî Failed to create connection:', error);
        throw error;
      } finally {
        this.creatingConnection = false;
      }
    }

    // Pool is full or a connection is already being created, wait for availability
    console.log('ÔÅ│ Connection pool busy, waiting for an available connection...');
    return this.waitForConnection();
  }

  /**
   * Release a connection back to the pool
   */
  release(connection: SQLiteDBConnection): void {
    for (const [id, pooled] of this.connections.entries()) {
      if (pooled.connection === connection) {
        pooled.inUse = false;
        pooled.lastUsed = Date.now();
        console.log(`Ô£à Released connection ${id}`);

        // If someone is waiting, give them this connection
        if (this.waitQueue.length > 0) {
          const waiter = this.waitQueue.shift();
          if (waiter) {
            clearTimeout(waiter.timeout);
            pooled.inUse = true;
            waiter.resolve(connection);
            console.log(`­ƒöä Handed connection to waiting request`);
          }
        }
        return;
      }
    }

    console.warn('ÔÜá´©Å Attempted to release unknown connection');
  }

  /**
   * Execute a query with automatic connection management
   * Handles connection acquisition and release automatically
   */
  async execute<T>(operation: (conn: SQLiteDBConnection) => Promise<T>): Promise<T> {
    const conn = await this.acquire();
    try {
      return await operation(conn);
    } finally {
      this.release(conn);
    }
  }

  /**
   * Close all connections and clean up
   */
  async closeAll(): Promise<void> {
    console.log(`­ƒöÆ Closing all ${this.connections.size} connections...`);

    // Cancel all waiting requests
    for (const waiter of this.waitQueue) {
      clearTimeout(waiter.timeout);
      waiter.reject(new Error('Connection pool is closing'));
    }
    this.waitQueue = [];

    // Close all connections
    const closePromises: Promise<void>[] = [];
    for (const [id, pooled] of this.connections.entries()) {
      closePromises.push(
        pooled.connection.close()
          .then(() => console.log(`Ô£à Closed connection ${id}`))
          .catch(err => console.error(`ÔØî Failed to close connection ${id}:`, err))
      );
    }

    await Promise.allSettled(closePromises);
    this.connections.clear();
    console.log('Ô£à All connections closed');
  }

  /**
   * Clean up idle connections
   */
  async cleanupIdleConnections(): Promise<void> {
    const now = Date.now();
    const toRemove: string[] = [];

    for (const [id, pooled] of this.connections.entries()) {
      if (!pooled.inUse && (now - pooled.lastUsed) > this.idleTimeout) {
        toRemove.push(id);
      }
    }

    if (toRemove.length > 0) {
      console.log(`­ƒº╣ Cleaning up ${toRemove.length} idle connections`);

      for (const id of toRemove) {
        const pooled = this.connections.get(id);
        if (pooled) {
          try {
            await pooled.connection.close();
            this.connections.delete(id);
            console.log(`Ô£à Closed idle connection ${id}`);
          } catch (error) {
            console.error(`ÔØî Failed to close idle connection ${id}:`, error);
          }
        }
      }
    }
  }

  /**
   * Get pool statistics
   */
  getStats(): {
    total: number;
    inUse: number;
    available: number;
    waiting: number;
  } {
    let inUse = 0;
    for (const pooled of this.connections.values()) {
      if (pooled.inUse) inUse++;
    }

    return {
      total: this.connections.size,
      inUse,
      available: this.connections.size - inUse,
      waiting: this.waitQueue.length
    };
  }

  // Private methods

  private async createConnection(): Promise<SQLiteDBConnection> {
    try {
      console.log('[Pool] Creating/retrieving connection for:', this.dbName);

      // First, check if a connection already exists and try to retrieve it
      const existing = await this.sqlite.isConnection(this.dbName, false);
      if (existing.result) {
        console.log('[Pool] Connection already exists, retrieving it');
        try {
          const conn = await this.sqlite.retrieveConnection(this.dbName, false);
          // Make sure it's open and wait for stability (increased to 2s)
          await conn.open();
          console.log('[Pool] Waiting 2 seconds for retrieved connection to stabilize...');
          await new Promise(resolve => setTimeout(resolve, 2000));
          console.log('[Pool] Ô£à Retrieved connection ready');
          return conn;
        } catch (retrieveError: any) {
          console.warn('[Pool] Failed to retrieve existing connection:', retrieveError?.message);
          // If retrieve fails, try to close and create fresh
          try {
            await this.sqlite.closeConnection(this.dbName, true);
            await new Promise(resolve => setTimeout(resolve, 200));
          } catch (closeErr) {
            console.warn('[Pool] Close failed (continuing anyway):', closeErr);
          }
        }
      }

      // Create new connection
      console.log('[Pool] Creating new connection...');
      const conn = await this.sqlite.createConnection(
        this.dbName,
        this.encrypted,
        this.mode,
        this.version,
        false // readonly = false
      );

      // Open the connection
      await conn.open();
      console.log('[Pool] Connection opened, waiting for stability...');

      // CRITICAL FIX: Wait for connection to fully stabilize on Android
      // Android SQLite needs significant time before transactions work
      // Increased from 1s to 3s to ensure readiness
      console.log('[Pool] Waiting 3 seconds for Android SQLite to stabilize...');
      await new Promise(resolve => setTimeout(resolve, 3000));
      console.log('[Pool] Ô£à Connection ready');

      return conn;
    } catch (createError: any) {
      console.error('[Pool] ÔØî Failed to create/open connection:', createError?.message || createError);
      throw new Error(`Failed to create database connection: ${createError?.message || createError}`);
    }
  }

  private waitForConnection(): Promise<SQLiteDBConnection> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        // Remove from queue
        const index = this.waitQueue.findIndex(w => w.timeout === timeout);
        if (index !== -1) {
          this.waitQueue.splice(index, 1);
        }
        reject(new Error(`Connection pool timeout after ${this.connectionTimeout}ms`));
      }, this.connectionTimeout);

      this.waitQueue.push({ resolve, reject, timeout });
    });
  }

  private generateConnectionId(): string {
    return `conn_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

/**
 * On-demand tile download service
 * Downloads map tiles dynamically when user navigates to areas without offline coverage
 */

import { Capacitor } from '@capacitor/core';

interface TileCoordinate {
  x: number;
  y: number;
  zoom: number;
}

interface TileBounds {
  north: number;
  south: number;
  east: number;
  west: number;
}

// Lower Saxony bounds (pre-downloaded offline tiles)
const LOWER_SAXONY_BOUNDS: TileBounds = {
  north: 53.9,
  south: 51.3,
  east: 11.6,
  west: 6.7
};

// Track downloaded tiles
const downloadedTiles = new Set<string>();
const downloadQueue = new Map<string, Promise<void>>();

// Tile template (self-hosted only). Must be configured via VITE_ONLINE_TILE_URL.
const ONLINE_TILE_TEMPLATE = (import.meta.env.VITE_ONLINE_TILE_URL as string | undefined) || '';

/**
 * Check if coordinates are within Lower Saxony (offline coverage area)
 */
function isInLowerSaxony(lat: number, lon: number): boolean {
  return (
    lat >= LOWER_SAXONY_BOUNDS.south &&
    lat <= LOWER_SAXONY_BOUNDS.north &&
    lon >= LOWER_SAXONY_BOUNDS.west &&
    lon <= LOWER_SAXONY_BOUNDS.east
  );
}

/**
 * Convert lat/lon to tile coordinates
 */
function latLonToTile(lat: number, lon: number, zoom: number): TileCoordinate {
  const latRad = (lat * Math.PI) / 180;
  const n = Math.pow(2, zoom);
  const x = Math.floor(((lon + 180) / 360) * n);
  const y = Math.floor(((1 - Math.asinh(Math.tan(latRad)) / Math.PI) / 2) * n);
  return { x, y, zoom };
}

/**
 * Convert tile coordinates to lat/lon bounds
 */
function tileToBounds(x: number, y: number, zoom: number): TileBounds {
  const n = Math.pow(2, zoom);
  const west = (x / n) * 360 - 180;
  const east = ((x + 1) / n) * 360 - 180;
  const northRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / n)));
  const southRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * (y + 1)) / n)));
  const north = (northRad * 180) / Math.PI;
  const south = (southRad * 180) / Math.PI;
  return { north, south, east, west };
}

/**
 * Get unique key for tile
 */
function getTileKey(x: number, y: number, zoom: number): string {
  return `${zoom}/${x}/${y}`;
}

/**
 * Download a single tile and cache it
 */
async function downloadTile(x: number, y: number, zoom: number): Promise<void> {
  const key = getTileKey(x, y, zoom);

  // Check if already downloaded
  if (downloadedTiles.has(key)) {
    return;
  }

  // Check if already downloading
  if (downloadQueue.has(key)) {
    return downloadQueue.get(key);
  }

  // Start download
  const downloadPromise = (async () => {
    try {
      if (!ONLINE_TILE_TEMPLATE) {
        throw new Error('No online tile template configured (VITE_ONLINE_TILE_URL).');
      }

      const url = ONLINE_TILE_TEMPLATE
        .replace('{z}', String(zoom))
        .replace('{x}', String(x))
        .replace('{y}', String(y));
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`Failed to download tile: ${response.status}`);
      }

      const blob = await response.blob();

      // Cache in IndexedDB or localStorage
      await cacheTile(key, blob);

      downloadedTiles.add(key);
      console.log(`[TileDownload] Ô£à Downloaded tile: ${key}`);
    } catch (error) {
      console.error(`[TileDownload] ÔØî Failed to download tile ${key}:`, error);
    } finally {
      downloadQueue.delete(key);
    }
  })();

  downloadQueue.set(key, downloadPromise);
  return downloadPromise;
}

/**
 * Cache tile in IndexedDB
 */
async function cacheTile(key: string, blob: Blob): Promise<void> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => reject(request.error);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains('tiles')) {
        db.createObjectStore('tiles');
      }
    };

    request.onsuccess = () => {
      const db = request.result;
      const transaction = db.transaction(['tiles'], 'readwrite');
      const store = transaction.objectStore('tiles');

      const putRequest = store.put(blob, key);

      putRequest.onsuccess = () => resolve();
      putRequest.onerror = () => reject(putRequest.error);
    };
  });
}

/**
 * Get cached tile from IndexedDB
 */
export async function getCachedTile(x: number, y: number, zoom: number): Promise<Blob | null> {
  const key = getTileKey(x, y, zoom);

  return new Promise((resolve) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => resolve(null);

    request.onsuccess = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains('tiles')) {
        resolve(null);
        return;
      }

      const transaction = db.transaction(['tiles'], 'readonly');
      const store = transaction.objectStore('tiles');
      const getRequest = store.get(key);

      getRequest.onsuccess = () => {
        resolve(getRequest.result || null);
      };

      getRequest.onerror = () => resolve(null);
    };
  });
}

/**
 * Request tiles for a map viewport
 * Downloads tiles outside Lower Saxony on-demand
 */
export async function requestTilesForViewport(
  bounds: TileBounds,
  zoom: number,
  maxZoom: number = 15
): Promise<void> {
  // Only download up to max zoom
  if (zoom > maxZoom) {
    zoom = maxZoom;
  }

  // Get center of viewport
  const centerLat = (bounds.north + bounds.south) / 2;
  const centerLon = (bounds.east + bounds.west) / 2;

  // Check if we're in Lower Saxony
  if (isInLowerSaxony(centerLat, centerLon)) {
    // Already have offline tiles
    return;
  }

  // Calculate which tiles are visible
  const topLeft = latLonToTile(bounds.north, bounds.west, zoom);
  const bottomRight = latLonToTile(bounds.south, bounds.east, zoom);

  console.log(`[TileDownload] Requesting tiles for viewport outside Lower Saxony (zoom ${zoom})`);

  // Download visible tiles
  const downloadPromises: Promise<void>[] = [];

  for (let x = topLeft.x; x <= bottomRight.x; x++) {
    for (let y = topLeft.y; y <= bottomRight.y; y++) {
      downloadPromises.push(downloadTile(x, y, zoom));

      // Limit concurrent downloads
      if (downloadPromises.length >= 6) {
        await Promise.all(downloadPromises);
        downloadPromises.length = 0;
      }
    }
  }

  // Wait for remaining downloads
  if (downloadPromises.length > 0) {
    await Promise.all(downloadPromises);
  }
}

/**
 * Clear tile cache
 */
export async function clearTileCache(): Promise<void> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.deleteDatabase('MapTilesCache');
    request.onsuccess = () => {
      downloadedTiles.clear();
      console.log('[TileDownload] Ô£à Tile cache cleared');
      resolve();
    };
    request.onerror = () => reject(request.error);
  });
}

/**
 * Get cache statistics
 */
export async function getTileCacheStats(): Promise<{ count: number; sizeEstimate: string }> {
  return new Promise((resolve) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => resolve({ count: 0, sizeEstimate: '0 MB' });

    request.onsuccess = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains('tiles')) {
        resolve({ count: 0, sizeEstimate: '0 MB' });
        return;
      }

      const transaction = db.transaction(['tiles'], 'readonly');
      const store = transaction.objectStore('tiles');
      const countRequest = store.count();

      countRequest.onsuccess = () => {
        const count = countRequest.result;
        const sizeEstimate = ((count * 15) / 1024).toFixed(2) + ' MB'; // ~15KB per tile
        resolve({ count, sizeEstimate });
      };

      countRequest.onerror = () => resolve({ count: 0, sizeEstimate: '0 MB' });
    };
  });
}

export default {
  requestTilesForViewport,
  getCachedTile,
  clearTileCache,
  getTileCacheStats
};

/**
 * Track Export/Import Service
 * Handles GPX, KML, and GeoJSON export/import for GPS tracks
 * Works on both web and native platforms
 */

import { Filesystem, Directory, Encoding } from '@capacitor/filesystem';
import { Capacitor } from '@capacitor/core';
import type { GpsTrackDetail, GpsPoint } from '../types';

export class TrackExportService {
  /**
   * Export track to GPX format
   */
  static async exportToGPX(track: GpsTrackDetail): Promise<string> {
    const points = track.gps_points || [];

    const gpxContent = `<?xml version="1.0" encoding="UTF-8"?>
<gpx version="1.1" creator="GPS Tracker App" xmlns="http://www.topografix.com/GPX/1/1">
  <metadata>
    <name>${this.escapeXml(track.name)}</name>
    <time>${new Date().toISOString()}</time>
  </metadata>
  <trk>
    <name>${this.escapeXml(track.name)}</name>
    <trkseg>
${points.map(pt => `      <trkpt lat="${pt.latitude}" lon="${pt.longitude}">
        ${pt.altitude ? `<ele>${pt.altitude}</ele>` : ''}
        <time>${pt.timestamp || new Date().toISOString()}</time>
      </trkpt>`).join('\n')}
    </trkseg>
  </trk>
</gpx>`;

    return gpxContent;
  }

  /**
   * Export track to KML format
   */
  static async exportToKML(track: GpsTrackDetail): Promise<string> {
    const points = track.gps_points || [];

    const kmlContent = `<?xml version="1.0" encoding="UTF-8"?>
<kml xmlns="http://www.opengis.net/kml/2.2">
  <Document>
    <name>${this.escapeXml(track.name)}</name>
    <Style id="trackStyle">
      <LineStyle>
        <color>${this.colorToKml(track.color || '#3B82F6')}</color>
        <width>4</width>
      </LineStyle>
    </Style>
    <Placemark>
      <name>${this.escapeXml(track.name)}</name>
      <styleUrl>#trackStyle</styleUrl>
      <LineString>
        <coordinates>
${points.map(pt => `          ${pt.longitude},${pt.latitude}${pt.altitude ? ',' + pt.altitude : ''}`).join('\n')}
        </coordinates>
      </LineString>
    </Placemark>
  </Document>
</kml>`;

    return kmlContent;
  }

  /**
   * Export track to GeoJSON format
   */
  static async exportToGeoJSON(track: GpsTrackDetail): Promise<string> {
    const points = track.gps_points || [];

    const geojson = {
      type: 'Feature',
      properties: {
        name: track.name,
        color: track.color || '#3B82F6',
        started_at: track.started_at,
        ended_at: track.ended_at,
      },
      geometry: {
        type: 'LineString',
        coordinates: points.map(pt => [
          pt.longitude,
          pt.latitude,
          pt.altitude || 0
        ])
      }
    };

    return JSON.stringify(geojson, null, 2);
  }

  /**
   * Download/save track file
   */
  static async downloadTrack(
    track: GpsTrackDetail,
    format: 'gpx' | 'kml' | 'geojson'
  ): Promise<void> {
    let content: string;
    let mimeType: string;
    let extension: string;

    // Generate content based on format
    switch (format) {
      case 'gpx':
        content = await this.exportToGPX(track);
        mimeType = 'application/gpx+xml';
        extension = 'gpx';
        break;
      case 'kml':
        content = await this.exportToKML(track);
        mimeType = 'application/vnd.google-earth.kml+xml';
        extension = 'kml';
        break;
      case 'geojson':
        content = await this.exportToGeoJSON(track);
        mimeType = 'application/geo+json';
        extension = 'geojson';
        break;
    }

    const filename = `${this.sanitizeFilename(track.name)}.${extension}`;

    // Native platform (Android/iOS)
    if (Capacitor.isNativePlatform()) {
      try {
        // Write file to Documents directory
        const result = await Filesystem.writeFile({
          path: filename,
          data: content,
          directory: Directory.Documents,
          encoding: Encoding.UTF8,
        });

        console.log('File saved to:', result.uri);

        // On Android, try to share the file if share plugin is available
        try {
          const { Share } = await import('@capacitor/share');
          await Share.share({
            title: `Export ${track.name}`,
            text: `GPS Track: ${track.name}`,
            url: result.uri,
            dialogTitle: 'Save or Share Track',
          });
        } catch (shareError) {
          // Share plugin not available, file is still saved
          console.log('Share not available, file saved to:', result.uri);
        }
      } catch (error) {
        console.error('Error saving file on native:', error);
        throw new Error('Failed to save track file');
      }
    } else {
      // Web platform - trigger download
      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    }
  }

  /**
   * Import GPX file
   */
  static async importFromGPX(gpxContent: string): Promise<Partial<GpsTrackDetail>> {
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(gpxContent, 'text/xml');

    // Check for parsing errors
    if (xmlDoc.querySelector('parsererror')) {
      throw new Error('Invalid GPX file');
    }

    const track: Partial<GpsTrackDetail> = {
      gps_points: [],
    };

    // Get track name
    const trkName = xmlDoc.querySelector('trk > name')?.textContent;
    if (trkName) track.name = trkName;

    // Parse track points
    const trkpts = xmlDoc.querySelectorAll('trkpt');
    trkpts.forEach((trkpt) => {
      const lat = parseFloat(trkpt.getAttribute('lat') || '0');
      const lon = parseFloat(trkpt.getAttribute('lon') || '0');
      const ele = trkpt.querySelector('ele')?.textContent;
      const time = trkpt.querySelector('time')?.textContent;

      track.gps_points!.push({
        latitude: lat,
        longitude: lon,
        altitude: ele ? parseFloat(ele) : undefined,
        timestamp: time || new Date().toISOString(),
      } as GpsPoint);
    });

    return track;
  }

  /**
   * Import KML file
   */
  static async importFromKML(kmlContent: string): Promise<Partial<GpsTrackDetail>> {
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(kmlContent, 'text/xml');

    // Check for parsing errors
    if (xmlDoc.querySelector('parsererror')) {
      throw new Error('Invalid KML file');
    }

    const track: Partial<GpsTrackDetail> = {
      gps_points: [],
    };

    // Get placemark name
    const placemarkName = xmlDoc.querySelector('Placemark > name')?.textContent;
    if (placemarkName) track.name = placemarkName;

    // Parse coordinates
    const coordinates = xmlDoc.querySelector('LineString > coordinates')?.textContent;
    if (coordinates) {
      const coords = coordinates.trim().split(/\s+/);
      coords.forEach((coord) => {
        const [lon, lat, alt] = coord.split(',').map(parseFloat);
        if (!isNaN(lat) && !isNaN(lon)) {
          track.gps_points!.push({
            latitude: lat,
            longitude: lon,
            altitude: alt,
            timestamp: new Date().toISOString(),
          } as GpsPoint);
        }
      });
    }

    return track;
  }

  /**
   * Import GeoJSON file
   */
  static async importFromGeoJSON(geojsonContent: string): Promise<Partial<GpsTrackDetail>> {
    const geojson = JSON.parse(geojsonContent);

    if (geojson.type !== 'Feature' || geojson.geometry?.type !== 'LineString') {
      throw new Error('Invalid GeoJSON: Must be a Feature with LineString geometry');
    }

    const track: Partial<GpsTrackDetail> = {
      name: geojson.properties?.name || 'Imported Track',
      color: geojson.properties?.color || '#3B82F6',
      gps_points: [],
      samples: [],
    };

    // Parse coordinates
    const coordinates = geojson.geometry.coordinates || [];
    coordinates.forEach((coord: number[]) => {
      const [lon, lat, alt] = coord;
      track.gps_points!.push({
        latitude: lat,
        longitude: lon,
        altitude: alt,
        timestamp: new Date().toISOString(),
      } as GpsPoint);
    });

    return track;
  }

  /**
   * Read file from device (for import)
   */
  static async readFile(filePath: string): Promise<string> {
    if (Capacitor.isNativePlatform()) {
      const result = await Filesystem.readFile({
        path: filePath,
        directory: Directory.Documents,
        encoding: Encoding.UTF8,
      });
      return result.data as string;
    } else {
      throw new Error('File reading not supported on web - use file input');
    }
  }

  // Helper methods
  private static escapeXml(text: string): string {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  private static colorToKml(hexColor: string): string {
    // KML uses AABBGGRR format (alpha, blue, green, red)
    const hex = hexColor.replace('#', '');
    const r = hex.substring(0, 2);
    const g = hex.substring(2, 4);
    const b = hex.substring(4, 6);
    return `ff${b}${g}${r}`; // Full opacity
  }

  private static sanitizeFilename(name: string): string {
    return name.replace(/[^a-zA-Z0-9_-]/g, '_');
  }
}

export const trackExport = TrackExportService;

import { doc, getDoc, setDoc, updateDoc } from 'firebase/firestore';
import { db } from '../firebase';

export interface UserProfile {
  uid: string;
  email: string;
  customerNumber?: string;
  firstName?: string;
  lastName?: string;
  company?: string;
  street?: string;
  postalCode?: string;
  city?: string;
  phone?: string;
  country?: string;
  federalState?: string;
  accessDisabled?: boolean;
  accessDisabledAt?: string | null;
  accessExpiresAt?: string | null;
  accessUpdatedAt?: string;
  createdAt: string;
  updatedAt: string;
}

class UserProfileService {
  private readonly COLLECTION = 'user_profiles';

  async createProfile(profile: UserProfile): Promise<void> {
    const docRef = doc(db, this.COLLECTION, profile.uid);
    // Filter out undefined values
    const cleanProfile = Object.fromEntries(
      Object.entries(profile).filter(([_, value]) => value !== undefined)
    );
    console.log('­ƒöä Creating user profile:', cleanProfile);
    await setDoc(docRef, cleanProfile);
    console.log('Ô£à User profile created successfully');
  }

  async getProfile(uid: string): Promise<UserProfile | null> {
    try {
      const docRef = doc(db, this.COLLECTION, uid);
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        const data = docSnap.data() as UserProfile;
        console.log('­ƒôû Retrieved user profile:', data);
        return data;
      }
      console.log('­ƒôû No user profile found for uid:', uid);
      return null;
    } catch (error) {
      console.error('Error fetching user profile:', error);
      return null;
    }
  }

  async updateProfile(uid: string, updates: Partial<UserProfile>): Promise<void> {
    const docRef = doc(db, this.COLLECTION, uid);
    // Filter out undefined values
    const cleanUpdates = Object.fromEntries(
      Object.entries(updates).filter(([_, value]) => value !== undefined)
    );
    await updateDoc(docRef, {
      ...cleanUpdates,
      updatedAt: new Date().toISOString()
    });
  }

  async upsertProfile(profile: Partial<UserProfile> & { uid: string; email: string }): Promise<void> {
    const docRef = doc(db, this.COLLECTION, profile.uid);
    const now = new Date().toISOString();

    const existing = await this.getProfile(profile.uid);

    if (existing) {
      // Filter out undefined values for update
      const cleanUpdates = Object.fromEntries(
        Object.entries(profile).filter(([_, value]) => value !== undefined)
      );
      await updateDoc(docRef, {
        ...cleanUpdates,
        updatedAt: now
      });
    } else {
      // Filter out undefined values for create
      const cleanProfile = Object.fromEntries(
        Object.entries({
          ...profile,
          createdAt: now,
          updatedAt: now
        }).filter(([_, value]) => value !== undefined)
      );
      await setDoc(docRef, cleanProfile);
    }
  }
}

