// Force refresh Firebase auth token to get updated custom claims
// Run this after setting admin role for a user

import { auth } from '../firebase';

export async function refreshAuthToken(): Promise<void> {
  const user = auth.currentUser;
  if (!user) {
    console.error('No user is currently signed in');
    throw new Error('No user signed in');
  }

  console.log('­ƒöä Refreshing auth token for user:', user.email);

  try {
    // Force refresh the ID token
    const token = await user.getIdToken(true); // true = force refresh
    console.log('Ô£à Token refreshed successfully');

    // Get the token result to see custom claims
    const tokenResult = await user.getIdTokenResult();
    console.log('­ƒôï Custom claims:', tokenResult.claims);
    console.log('­ƒôï Admin claim:', tokenResult.claims.admin);

    // Check if admin claim exists
    if (!tokenResult.claims.admin) {
      console.warn('ÔÜá´©Å Admin claim not found in token. You may need to:');
      console.warn('   1. Run: node scripts/set-admin-user.js your-email@example.com');
      console.warn('   2. Wait 5 minutes for changes to propagate');
      console.warn('   3. Log out and log back in');
    }

    return;
  } catch (error) {
    console.error('ÔØî Error refreshing token:', error);
    throw error;
  }
}

