/**
 * Debug configuration for performance optimization
 * Disable console logging on production/deployed builds
 * Keep it enabled in development for troubleshooting
 */

const DEBUG_ENABLED = import.meta.env.DEV; // Only log in development mode

export function debugLog(prefix: string, message: any, data?: any) {
  if (DEBUG_ENABLED) {
    if (data) {
      console.log(`[${prefix}] ${message}`, data);
    } else {
      console.log(`[${prefix}] ${message}`);
    }
  }
}

export function debugWarn(prefix: string, message: any, data?: any) {
  if (DEBUG_ENABLED) {
    if (data) {
      console.warn(`[${prefix}] ${message}`, data);
    } else {
      console.warn(`[${prefix}] ${message}`);
    }
  }
}

export function debugError(prefix: string, message: any, data?: any) {
  // Always log errors, but only in dev
  if (DEBUG_ENABLED) {
    if (data) {
      console.error(`[${prefix}] ${message}`, data);
    } else {
      console.error(`[${prefix}] ${message}`);
    }
  }
}

export const isDebugEnabled = DEBUG_ENABLED;

/**
 * Device Detection Utilities
 * Detects Windows tablets, mobile devices, and platform capabilities
 */

/**
 * Detect if the device is a Windows tablet
 * Windows tablets typically have:
 * - Touch support
 * - Windows OS
 * - Potentially smaller screen sizes or specific user agents
 */
export function isWindowsTablet(): boolean {
  if (typeof window === 'undefined') return false;

  const userAgent = navigator.userAgent.toLowerCase();
  const platform = navigator.platform?.toLowerCase() || '';

  // Check for Windows OS
  const isWindows = platform.includes('win') || userAgent.includes('windows');

  // Check for touch support (primary indicator of tablet/touch device)
  const hasTouch = 'ontouchstart' in window || 
                   navigator.maxTouchPoints > 0 || 
                   (navigator as any).msMaxTouchPoints > 0;

  // Check for tablet-specific indicators
  const isTablet = userAgent.includes('tablet') || 
                   userAgent.includes('ipad') ||
                   // Surface devices
                   userAgent.includes('surface') ||
                   // Some Windows tablets identify as 'touch'
                   userAgent.includes('touch');

  // Windows tablet = Windows OS + Touch support
  // OR explicitly marked as tablet/surface
  return (isWindows && hasTouch) || (isWindows && isTablet);
}

/**
 * Detect if device is mobile (phone or tablet)
 */
export function isMobileDevice(): boolean {
  if (typeof window === 'undefined') return false;

  const userAgent = navigator.userAgent.toLowerCase();

  return /android|webos|iphone|ipad|ipod|blackberry|iemobile|opera mini|mobile|tablet/i.test(userAgent) ||
         (navigator.maxTouchPoints > 0 && window.innerWidth < 1024);
}

/**
 * Detect compact landscape screens, primarily phones used in landscape.
 * This intentionally excludes tablets and larger touch devices.
 */
export function isCompactLandscapeScreen(): boolean {
  if (typeof window === 'undefined') return false;

  const width = window.innerWidth;
  const height = window.innerHeight;
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= height) {
    return false;
  }

  const shortSide = Math.min(width, height);
  const longSide = Math.max(width, height);
  const userAgent = navigator.userAgent.toLowerCase();
  const hasTouch = 'ontouchstart' in window ||
    navigator.maxTouchPoints > 0 ||
    (navigator as any).msMaxTouchPoints > 0;
  const looksLikeTablet = userAgent.includes('ipad') || userAgent.includes('tablet') || userAgent.includes('surface');

  if (!hasTouch || looksLikeTablet) {
    return false;
  }

  return isMobileDevice() && shortSide <= 600 && longSide <= 960;
}

/**
 * Detect if device has GPS capabilities
 */
export function hasGPSCapability(): boolean {
  return 'geolocation' in navigator;
}

/**
 * Detect if device supports Web Serial API (for USB GPS)
 */
export function supportsSerialAPI(): boolean {
  return 'serial' in navigator;
}

/**
 * Get comprehensive device info
 */
export function getDeviceInfo() {
  return {
    isWindowsTablet: isWindowsTablet(),
    isMobile: isMobileDevice(),
    isCompactLandscape: isCompactLandscapeScreen(),
    hasGPS: hasGPSCapability(),
    hasSerialAPI: supportsSerialAPI(),
    userAgent: navigator.userAgent,
    platform: navigator.platform,
    touchPoints: navigator.maxTouchPoints,
    screenSize: {
      width: window.innerWidth,
      height: window.innerHeight
    }
  };
}

/**
 * Check if device can track GPS
 * - Native apps always can
 * - Windows tablets can
 * - Mobile devices can
 * - Desktop browsers without special detection cannot
 */
export function canTrackGPS(isNativeApp: boolean): boolean {
  // Native apps always support tracking
  if (isNativeApp) return true;

  // Windows tablets can track
  if (isWindowsTablet()) return true;

  // Mobile devices can track
  if (isMobileDevice()) return true;

  // Desktop browsers can track if they have geolocation
  // (allow for debugging and development)
  return hasGPSCapability();
}

/**
 * Device Validation and Management Utilities
 * Fixes Issue #22: Device management validation and state tracking
 */

import { DEVICE_TYPES, CONNECTION_TYPES } from '../config/constants';

export interface DeviceCapabilities {
  hasGPS?: boolean;
  hasBluetooth?: boolean;
  hasWiFi?: boolean;
  hasUSB?: boolean;
  supportsRTK?: boolean; // Real-Time Kinematic positioning
  supportsNMEA?: boolean;
  maxUpdateRate?: number; // Hz
  accuracy?: string; // e.g., "sub-meter", "centimeter"
}

export interface DeviceConfig {
  baudRate?: number;
  dataBits?: number;
  stopBits?: number;
  parity?: 'none' | 'even' | 'odd';
  autoConnect?: boolean;
  reconnectInterval?: number; // ms
  timeout?: number; // ms
}

export interface DeviceConnectionState {
  connected: boolean;
  lastConnected?: string; // ISO timestamp
  lastDisconnected?: string;
  connectionAttempts?: number;
  lastError?: string;
  signalStrength?: number; // 0-100
  batteryLevel?: number; // 0-100
}

export interface GPSDevice {
  id: string;
  name: string;
  device_type: keyof typeof DEVICE_TYPES;
  connection_type: keyof typeof CONNECTION_TYPES;
  address?: string; // MAC address for Bluetooth, IP for WiFi
  manufacturer?: string;
  model?: string;
  capabilities?: DeviceCapabilities | string; // Can be JSON string
  config?: DeviceConfig | string; // Can be JSON string
  connectionState?: DeviceConnectionState;
  is_active?: boolean;
  created_at: string;
  updated_at?: string;
  last_connected?: string;
}

/**
 * Validate device object structure
 */
export function validateDevice(device: Partial<GPSDevice>): {
  valid: boolean;
  errors: string[];
  warnings: string[];
} {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Required fields
  if (!device.name || device.name.trim().length === 0) {
    errors.push('Device name is required');
  }

  if (!device.device_type) {
    errors.push('Device type is required');
  } else if (!Object.keys(DEVICE_TYPES).includes(device.device_type)) {
    errors.push(`Invalid device type: ${device.device_type}`);
  }

  if (!device.connection_type) {
    errors.push('Connection type is required');
  } else if (!Object.keys(CONNECTION_TYPES).includes(device.connection_type)) {
    errors.push(`Invalid connection type: ${device.connection_type}`);
  }

  // Bluetooth devices need MAC address
  if (device.connection_type === 'bluetooth' || device.connection_type === 'BLUETOOTH') {
    if (!device.address) {
      warnings.push('Bluetooth device should have MAC address');
    } else if (!isValidMACAddress(device.address)) {
      warnings.push('Invalid MAC address format');
    }
  }

  // WiFi devices need IP address
  if (device.connection_type === 'wifi' || device.connection_type === 'WIFI') {
    if (!device.address) {
      warnings.push('WiFi device should have IP address');
    } else if (!isValidIPAddress(device.address)) {
      warnings.push('Invalid IP address format');
    }
  }

  // Validate capabilities if provided
  if (device.capabilities) {
    try {
      const caps = typeof device.capabilities === 'string' 
        ? JSON.parse(device.capabilities)
        : device.capabilities;

      if (typeof caps !== 'object') {
        warnings.push('Capabilities should be an object');
      }
    } catch (e) {
      warnings.push('Invalid capabilities JSON');
    }
  }

  // Validate config if provided
  if (device.config) {
    try {
      const config = typeof device.config === 'string'
        ? JSON.parse(device.config)
        : device.config;

      if (typeof config !== 'object') {
        warnings.push('Config should be an object');
      }
    } catch (e) {
      warnings.push('Invalid config JSON');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings
  };
}

/**
 * Validate MAC address format
 */
function isValidMACAddress(address: string): boolean {
  // Match formats: AA:BB:CC:DD:EE:FF or AA-BB-CC-DD-EE-FF
  const macPattern = /^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$/;
  return macPattern.test(address);
}

/**
 * Validate IP address format (IPv4)
 */
function isValidIPAddress(address: string): boolean {
  const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
  if (!ipPattern.test(address)) return false;

  const parts = address.split('.');
  return parts.every(part => {
    const num = parseInt(part, 10);
    return num >= 0 && num <= 255;
  });
}

/**
 * Parse capabilities from string or object
 */
export function parseCapabilities(capabilities?: DeviceCapabilities | string): DeviceCapabilities {
  if (!capabilities) {
    return {};
  }

  if (typeof capabilities === 'string') {
    try {
      return JSON.parse(capabilities);
    } catch (e) {
      console.warn('Failed to parse capabilities:', e);
      return {};
    }
  }

  return capabilities;
}

/**
 * Parse config from string or object
 */
export function parseConfig(config?: DeviceConfig | string): DeviceConfig {
  if (!config) {
    return {};
  }

  if (typeof config === 'string') {
    try {
      return JSON.parse(config);
    } catch (e) {
      console.warn('Failed to parse config:', e);
      return {};
    }
  }

  return config;
}

/**
 * Check if device is currently connected
 */
export function isDeviceConnected(device: GPSDevice): boolean {
  return device.connectionState?.connected || false;
}

/**
 * Check if device should attempt auto-reconnect
 */
export function shouldAutoReconnect(device: GPSDevice): boolean {
  const config = parseConfig(device.config);
  return config.autoConnect !== false; // Default to true
}

/**
 * Get default config for device type
 */
export function getDefaultConfig(deviceType: keyof typeof DEVICE_TYPES): DeviceConfig {
  const defaults: DeviceConfig = {
    baudRate: 9600,
    dataBits: 8,
    stopBits: 1,
    parity: 'none',
    autoConnect: true,
    reconnectInterval: 5000,
    timeout: 10000
  };

  // USB GPS devices often use higher baud rates
  if (deviceType === 'usb_gps' || deviceType === 'USB_GPS') {
    defaults.baudRate = 115200;
  }

  return defaults;
}

/**
 * Update device connection state
 */
export function updateConnectionState(
  device: GPSDevice,
  connected: boolean,
  error?: string
): GPSDevice {
  const now = new Date().toISOString();

  const connectionState: DeviceConnectionState = {
    ...device.connectionState,
    connected,
    lastError: error,
    connectionAttempts: connected 
      ? 0 
      : (device.connectionState?.connectionAttempts || 0) + 1
  };

  if (connected) {
    connectionState.lastConnected = now;
  } else {
    connectionState.lastDisconnected = now;
  }

  return {
    ...device,
    connectionState,
    last_connected: connected ? now : device.last_connected,
    updated_at: now
  };
}

/**
 * Sanitize device for storage
 */
export function sanitizeDevice(device: Partial<GPSDevice>): Partial<GPSDevice> {
  const sanitized: Partial<GPSDevice> = {
    name: device.name?.trim(),
    device_type: device.device_type,
    connection_type: device.connection_type,
    address: device.address?.trim(),
    manufacturer: device.manufacturer?.trim(),
    model: device.model?.trim(),
  };

  // Convert capabilities to string for storage
  if (device.capabilities) {
    sanitized.capabilities = typeof device.capabilities === 'string'
      ? device.capabilities
      : JSON.stringify(device.capabilities);
  }

  // Convert config to string for storage
  if (device.config) {
    sanitized.config = typeof device.config === 'string'
      ? device.config
      : JSON.stringify(device.config);
  }

  // Preserve timestamps
  if (device.created_at) sanitized.created_at = device.created_at;
  if (device.updated_at) sanitized.updated_at = device.updated_at;
  if (device.last_connected) sanitized.last_connected = device.last_connected;
  if (device.is_active !== undefined) sanitized.is_active = device.is_active;

  return sanitized;
}

/**
 * Check if device needs reconnection attempt
 */
export function needsReconnect(device: GPSDevice): boolean {
  if (isDeviceConnected(device)) return false;
  if (!shouldAutoReconnect(device)) return false;

  const config = parseConfig(device.config);
  const reconnectInterval = config.reconnectInterval || 5000;

  const lastAttempt = device.connectionState?.lastDisconnected;
  if (!lastAttempt) return true;

  const timeSinceLastAttempt = Date.now() - new Date(lastAttempt).getTime();
  return timeSinceLastAttempt >= reconnectInterval;
}

/**
 * Ô£à ISSUE #10 FIX: Standardized Error Handling with Categories
 * 
 * Provides consistent error categorization, retry logic, and user feedback
 * across the entire application.
 */

export enum ErrorCategory {
  NETWORK = 'network',           // Network connectivity issues
  AUTH = 'auth',                 // Authentication/authorization errors
  PERMISSION = 'permission',     // Permission denied errors
  VALIDATION = 'validation',     // Data validation errors
  STORAGE = 'storage',          // Storage quota/access errors
  DATABASE = 'database',        // Database operation errors
  TIMEOUT = 'timeout',          // Operation timeout errors
  CONFLICT = 'conflict',        // Data conflict errors
  NOT_FOUND = 'not-found',      // Resource not found
  UNKNOWN = 'unknown'           // Uncategorized errors
}

export interface CategorizedError {
  category: ErrorCategory;
  message: string;
  originalError: any;
  isRetriable: boolean;
  shouldNotifyUser: boolean;
  userMessage: string;
  timestamp: number;
}

/**
 * Categorize an error and determine appropriate handling
 */
export function categorizeError(
  error: any, 
  t?: (key: string, fallback?: string) => string
): CategorizedError {
  const timestamp = Date.now();
  let category = ErrorCategory.UNKNOWN;
  let isRetriable = false;
  let shouldNotifyUser = true;
  let userMessage = t?.('error.categories.unexpectedError') || 'An unexpected error occurred';
  let message = error?.message || String(error);

  // Network errors
  if (
    message.includes('network') ||
    message.includes('fetch') ||
    message.includes('timeout') ||
    message.includes('offline') ||
    error?.code === 'unavailable' ||
    error?.code === 'deadline-exceeded'
  ) {
    category = ErrorCategory.NETWORK;
    isRetriable = true;
    shouldNotifyUser = false; // Silent retry for network issues
    userMessage = t?.('error.categories.networkError') || 'Network connection issue. Will retry automatically.';
  }

  // Timeout errors
  else if (
    message.includes('timeout') ||
    message.includes('timed out') ||
    error?.code === 'deadline-exceeded'
  ) {
    category = ErrorCategory.TIMEOUT;
    isRetriable = true;
    shouldNotifyUser = false;
    userMessage = t?.('error.categories.timeoutError') || 'Operation timed out. Will retry automatically.';
  }

  // Authentication errors
  else if (
    message.includes('auth') ||
    message.includes('unauthenticated') ||
    message.includes('not authenticated') ||
    message.includes('mismatch') ||
    error?.code?.startsWith('auth/') ||
    error?.code === 'auth/mismatch'
  ) {
    category = ErrorCategory.AUTH;
    isRetriable = false;
    shouldNotifyUser = true;
    userMessage = t?.('error.categories.authError') || 'Please log in again to continue.';
  }

  // Permission errors
  else if (
    message.includes('permission') ||
    message.includes('denied') ||
    message.includes('forbidden') ||
    error?.code === 'permission-denied'
  ) {
    category = ErrorCategory.PERMISSION;
    isRetriable = false;
    shouldNotifyUser = true;
    userMessage = t?.('error.categories.permissionError') || 'You do not have permission to perform this action.';
  }

  // Storage errors
  else if (
    message.includes('quota') ||
    message.includes('storage') ||
    message.includes('disk') ||
    message.includes('space')
  ) {
    category = ErrorCategory.STORAGE;
    isRetriable = false;
    shouldNotifyUser = true;
    userMessage = t?.('error.categories.storageError') || 'Storage is full. Please free up space.';
  }

  // Database errors
  else if (
    message.includes('database') ||
    message.includes('indexeddb') ||
    message.includes('connection')
  ) {
    category = ErrorCategory.DATABASE;
    isRetriable = true;
    shouldNotifyUser = true;
    userMessage = t?.('error.categories.databaseError') || 'Database error. Please try again.';
  }

  // Not found errors
  else if (
    message.includes('not found') ||
    message.includes('missing') ||
    error?.code === 'not-found'
  ) {
    category = ErrorCategory.NOT_FOUND;
    isRetriable = false;
    shouldNotifyUser = false; // Often expected
    userMessage = t?.('error.categories.notFoundError') || 'Item not found.';
  }

  // Validation errors
  else if (
    message.includes('invalid') ||
    message.includes('validation') ||
    message.includes('required')
  ) {
    category = ErrorCategory.VALIDATION;
    isRetriable = false;
    shouldNotifyUser = true;
    userMessage = message; // Use original message for validation errors
  }

  return {
    category,
    message,
    originalError: error,
    isRetriable,
    shouldNotifyUser,
    userMessage,
    timestamp
  };
}

/**
 * Check if an error is retriable
 */
export function isRetriableError(error: any): boolean {
  const categorized = categorizeError(error);
  return categorized.isRetriable;
}

/**
 * Get user-friendly error message
 */
export function getUserErrorMessage(error: any): string {
  const categorized = categorizeError(error);
  return categorized.userMessage;
}

/**
 * Log error with category context
 */
export function logCategorizedError(context: string, error: any): void {
  const categorized = categorizeError(error);

  const logEntry = {
    context,
    category: categorized.category,
    message: categorized.message,
    retriable: categorized.isRetriable,
    timestamp: new Date(categorized.timestamp).toISOString()
  };

  // Use appropriate console method based on category
  if (categorized.category === ErrorCategory.NETWORK || 
      categorized.category === ErrorCategory.TIMEOUT) {
    console.warn(`[${context}]`, logEntry);
  } else if (categorized.category === ErrorCategory.NOT_FOUND) {
    console.info(`[${context}]`, logEntry);
  } else {
    console.error(`[${context}]`, logEntry);
  }
}

/**
 * Create standardized error with category
 */
export function createCategorizedError(
  category: ErrorCategory,
  message: string,
  originalError?: any
): Error {
  const error = new Error(message);
  (error as any).category = category;
  (error as any).originalError = originalError;
  return error;
}

/**
 * Error Translation Helper
 * Maps error codes to i18n translation keys
 * Fixes Issue #23: Translation keys missing for error messages
 */

import { ERROR_MESSAGES } from '../config/constants';

export type ErrorCategory = 
  | 'database'
  | 'sync' 
  | 'gps'
  | 'device'
  | 'field'
  | 'track'
  | 'sample'
  | 'common';

export interface TranslatedError {
  key: string; // i18n translation key
  category: ErrorCategory;
  message: string; // English fallback
  params?: Record<string, any>; // Parameters for interpolation
}

/**
 * Error code to translation key mapping
 */
const ERROR_KEY_MAP: Record<string, string> = {
  // Auth errors
  'auth/requires-recent-login': 'errors.database.authentication_required',
  'auth/user-not-found': 'errors.database.authentication_required',
  'permission-denied': 'errors.database.permission_denied',

  // Network errors
  'network-request-failed': 'errors.database.network_error',
  'unavailable': 'errors.database.device_offline',
  'timeout': 'errors.database.operation_timeout',

  // Data errors
  'not-found': 'errors.database.not_found',
  'invalid-argument': 'errors.database.invalid_data',
  'already-exists': 'errors.database.invalid_data',

  // Storage errors
  'quota-exceeded': 'errors.database.storage_quota_exceeded',
  'failed-precondition': 'errors.database.database_error',

  // GPS errors
  'POSITION_UNAVAILABLE': 'errors.gps.location_unavailable',
  'PERMISSION_DENIED': 'errors.gps.permission_denied',
  'TIMEOUT': 'errors.gps.timeout',

  // Sync errors
  'sync-failed': 'errors.database.sync_failed',
  'conflict': 'errors.sync.conflict_detected',
};

/**
 * Translate error to i18n key
 */
export function translateError(error: Error | string | any): TranslatedError {
  const errorMsg = typeof error === 'string' ? error : error?.message || error?.code || 'unknown';
  const errorCode = typeof error === 'object' ? error?.code : errorMsg;

  // Try direct mapping first
  if (errorCode && ERROR_KEY_MAP[errorCode]) {
    return {
      key: ERROR_KEY_MAP[errorCode],
      category: getCategoryFromKey(ERROR_KEY_MAP[errorCode]),
      message: errorMsg
    };
  }

  // Pattern matching for common error types
  if (errorMsg.toLowerCase().includes('network')) {
    return {
      key: 'errors.database.network_error',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('offline')) {
    return {
      key: 'errors.database.device_offline',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('timeout')) {
    return {
      key: 'errors.database.operation_timeout',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('permission')) {
    return {
      key: 'errors.database.permission_denied',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('not found')) {
    return {
      key: 'errors.database.not_found',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('invalid') || errorMsg.toLowerCase().includes('validation')) {
    return {
      key: 'errors.database.invalid_data',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('gps') || errorMsg.toLowerCase().includes('location')) {
    return {
      key: 'errors.gps.location_unavailable',
      category: 'gps',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('device') || errorMsg.toLowerCase().includes('bluetooth')) {
    return {
      key: 'errors.device.connection_failed',
      category: 'device',
      message: errorMsg
    };
  }

  // Fallback to unknown error
  return {
    key: 'errors.common.unknown_error',
    category: 'common',
    message: errorMsg
  };
}

/**
 * Get category from translation key
 */
function getCategoryFromKey(key: string): ErrorCategory {
  const parts = key.split('.');
  if (parts.length >= 2 && parts[0] === 'errors') {
    return parts[1] as ErrorCategory;
  }
  return 'common';
}

/**
 * Format error for user display with i18n
 */
export function formatErrorForUser(
  error: Error | string | any,
  t: (key: string, params?: any) => string
): string {
  const translated = translateError(error);

  try {
    // Try translation with params
    const translatedMsg = t(translated.key, translated.params);

    // If translation returns the key itself, use fallback
    if (translatedMsg === translated.key) {
      return translated.message;
    }

    return translatedMsg;
  } catch (e) {
    // Fallback to English message
    return translated.message;
  }
}

/**
 * Check if error is retriable based on translation
 */
export function isRetriableFromTranslation(error: Error | string | any): boolean {
  const translated = translateError(error);

  const retriableKeys = [
    'errors.database.network_error',
    'errors.database.device_offline',
    'errors.database.operation_timeout',
    'errors.database.sync_failed',
    'errors.gps.timeout',
    'errors.device.connection_timeout',
  ];

  return retriableKeys.includes(translated.key);
}

/**
 * Get user-friendly action suggestion based on error
 */
export function getErrorAction(
  error: Error | string | any,
  t: (key: string) => string
): string | null {
  const translated = translateError(error);

  const actionMap: Record<string, string> = {
    'errors.database.device_offline': 'errors.common.try_again',
    'errors.database.network_error': 'errors.common.try_again',
    'errors.database.operation_timeout': 'errors.common.try_again',
    'errors.gps.permission_denied': 'errors.common.contact_support',
    'errors.database.permission_denied': 'errors.common.contact_support',
    'errors.database.storage_quota_exceeded': 'errors.common.contact_support',
  };

  const actionKey = actionMap[translated.key];
  if (actionKey) {
    try {
      return t(actionKey);
    } catch (e) {
      return null;
    }
  }

  return null;
}

/**
 * Create error notification config for toast/snackbar
 */
export interface ErrorNotificationConfig {
  message: string;
  action?: string;
  severity: 'error' | 'warning' | 'info';
  duration?: number;
  retriable: boolean;
}

export function createErrorNotification(
  error: Error | string | any,
  t: (key: string, params?: any) => string
): ErrorNotificationConfig {
  const translated = translateError(error);
  const message = formatErrorForUser(error, t);
  const action = getErrorAction(error, t);
  const retriable = isRetriableFromTranslation(error);

  // Determine severity based on category
  let severity: 'error' | 'warning' | 'info' = 'error';
  if (translated.category === 'sync' || translated.key.includes('offline')) {
    severity = 'warning'; // Offline/sync issues are warnings, not critical
  }

  // Duration based on severity
  const duration = severity === 'error' ? 5000 : 3000;

  return {
    message,
    action: action || undefined,
    severity,
    duration,
    retriable
  };
}

/**
 * Standardized error handling for the application
 * Provides error categorization, severity levels, and user-friendly messaging
 */

import toast from 'react-hot-toast';

export enum ErrorSeverity {
  INFO = 'info',
  WARNING = 'warning',
  ERROR = 'error',
  CRITICAL = 'critical'
}

export enum ErrorCategory {
  NETWORK = 'network',
  DATABASE = 'database',
  AUTHENTICATION = 'auth',
  VALIDATION = 'validation',
  PERMISSION = 'permission',
  STORAGE = 'storage',
  SYNC = 'sync',
  UNKNOWN = 'unknown'
}

export class AppError extends Error {
  constructor(
    message: string,
    public category: ErrorCategory,
    public severity: ErrorSeverity,
    public isRetriable: boolean = false,
    public context?: any
  ) {
    super(message);
    this.name = 'AppError';
  }
}

export class ErrorHandler {
  private static listeners: Array<(error: AppError) => void> = [];
  private static errorCounts = new Map<string, number>();

  static handle(error: Error | AppError, silent: boolean = false): void {
    const appError = error instanceof AppError
      ? error
      : this.categorize(error);

    // Count errors
    const errorKey = `${appError.category}:${appError.message}`;
    this.errorCounts.set(errorKey, (this.errorCounts.get(errorKey) || 0) + 1);

    // Log with context
    const logLevel = appError.severity === ErrorSeverity.CRITICAL || appError.severity === ErrorSeverity.ERROR
      ? console.error
      : appError.severity === ErrorSeverity.WARNING
      ? console.warn
      : console.info;

    logLevel(
      `[${appError.severity.toUpperCase()}] ${appError.category}:`,
      appError.message,
      appError.context || ''
    );

    // Notify listeners
    this.listeners.forEach(listener => {
      try {
        listener(appError);
      } catch (e) {
        console.error('Error in error listener:', e);
      }
    });

    // User notification (unless silent)
    if (!silent) {
      if (appError.severity === ErrorSeverity.CRITICAL || appError.severity === ErrorSeverity.ERROR) {
        toast.error(appError.message);
      } else if (appError.severity === ErrorSeverity.WARNING) {
        toast(appError.message, { icon: 'ÔÜá´©Å', duration: 4000 });
      }
    }
  }

  static categorize(error: Error): AppError {
    const message = error.message.toLowerCase();

    // Network errors
    if (message.includes('timeout') || message.includes('network') || 
        message.includes('fetch') || message.includes('connection')) {
      return new AppError(
        'Network error - please check your connection',
        ErrorCategory.NETWORK,
        ErrorSeverity.WARNING,
        true,
        { originalError: error.message }
      );
    }

    // Auth errors
    if (message.includes('permission') || message.includes('unauthorized') || 
        message.includes('auth') || message.includes('not authenticated')) {
      return new AppError(
        'Authentication error - please log in again',
        ErrorCategory.AUTHENTICATION,
        ErrorSeverity.ERROR,
        false,
        { originalError: error.message }
      );
    }

    // Database errors
    if (message.includes('database') || 
        message.includes('firestore') || message.includes('indexeddb')) {
      return new AppError(
        'Database error - your data has been saved locally',
        ErrorCategory.DATABASE,
        ErrorSeverity.WARNING,
        true,
        { originalError: error.message }
      );
    }

    // Storage errors
    if (message.includes('quota') || message.includes('storage')) {
      return new AppError(
        'Storage quota exceeded - please clear some data',
        ErrorCategory.STORAGE,
        ErrorSeverity.WARNING,
        false,
        { originalError: error.message }
      );
    }

    // Sync errors
    if (message.includes('sync') || message.includes('queue')) {
      return new AppError(
        'Sync error - will retry automatically',
        ErrorCategory.SYNC,
        ErrorSeverity.INFO,
        true,
        { originalError: error.message }
      );
    }

    // Validation errors
    if (message.includes('invalid') || message.includes('validation')) {
      return new AppError(
        'Validation error - please check your input',
        ErrorCategory.VALIDATION,
        ErrorSeverity.WARNING,
        false,
        { originalError: error.message }
      );
    }

    // Unknown
    return new AppError(
      'An unexpected error occurred',
      ErrorCategory.UNKNOWN,
      ErrorSeverity.ERROR,
      false,
      { originalError: error.message }
    );
  }

  static subscribe(listener: (error: AppError) => void): () => void {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  static getErrorCount(category?: ErrorCategory): number {
    if (!category) {
      return Array.from(this.errorCounts.values()).reduce((a, b) => a + b, 0);
    }

    let count = 0;
    for (const [key, value] of this.errorCounts.entries()) {
      if (key.startsWith(`${category}:`)) {
        count += value;
      }
    }
    return count;
  }

  static clearErrorCounts(): void {
    this.errorCounts.clear();
  }
}

import area from '@turf/area';
import intersect from '@turf/intersect';
import { featureCollection } from '@turf/helpers';

export type PolygonGeometry = GeoJSON.Polygon | GeoJSON.MultiPolygon;

type SplitAxis = 'lng' | 'lat';

export type GeometryBounds = {
  minLng: number;
  maxLng: number;
  minLat: number;
  maxLat: number;
};

export type BalancedSamplingCell = {
  geometry: PolygonGeometry;
  areaHa: number;
  index: number;
  row: number;
  column: number;
};

const MIN_CELL_AREA_HA = 0.08;
const BINARY_SEARCH_ITERATIONS = 24;
const AXIS_EPSILON = 1e-9;
const DEFAULT_MIN_CELL_AREA_RATIO = 1 / 3;
const MAX_MERGED_CELL_AREA_MULTIPLIER = 1.85;

const asPolygonGeometry = (geometry: GeoJSON.Geometry | null | undefined): PolygonGeometry | null => {
  if (!geometry) return null;
  if (geometry.type === 'Polygon' || geometry.type === 'MultiPolygon') {
    return geometry;
  }
  return null;
};

export const geometryAreaHa = (geometry: PolygonGeometry): number => {
  const rawArea = area({ type: 'Feature', properties: {}, geometry }) / 10000;
  if (!Number.isFinite(rawArea) || rawArea <= 0) return 0;
  return Number(rawArea.toFixed(6));
};

export const buildGeometryBounds = (geometry: PolygonGeometry): GeometryBounds | null => {
  let minLng = Infinity;
  let maxLng = -Infinity;
  let minLat = Infinity;
  let maxLat = -Infinity;

  const walk = (node: any) => {
    if (!Array.isArray(node) || node.length === 0) return;
    if (typeof node[0] === 'number') {
      const lng = Number(node[0]);
      const lat = Number(node[1]);
      if (!Number.isFinite(lng) || !Number.isFinite(lat)) return;
      minLng = Math.min(minLng, lng);
      maxLng = Math.max(maxLng, lng);
      minLat = Math.min(minLat, lat);
      maxLat = Math.max(maxLat, lat);
      return;
    }
    node.forEach((child) => walk(child));
  };

  walk(geometry.coordinates);

  if (![minLng, maxLng, minLat, maxLat].every(Number.isFinite)) {
    return null;
  }

  return { minLng, maxLng, minLat, maxLat };
};

const toMultiPolygonCoordinates = (geometry: PolygonGeometry): number[][][][] => (
  geometry.type === 'Polygon'
    ? [geometry.coordinates as number[][][]]
    : (geometry.coordinates as number[][][][])
);

const mergeCellGeometry = (
  left: PolygonGeometry,
  right: PolygonGeometry
): PolygonGeometry => {
  const coordinates = [
    ...toMultiPolygonCoordinates(left),
    ...toMultiPolygonCoordinates(right),
  ];

  if (coordinates.length === 1) {
    return {
      type: 'Polygon',
      coordinates: coordinates[0],
    };
  }

  return {
    type: 'MultiPolygon',
    coordinates,
  };
};

const normalizeCellIndexes = (cells: BalancedSamplingCell[]): BalancedSamplingCell[] => (
  cells.map((cell, index) => ({
    ...cell,
    index: index + 1,
    row: index,
    column: 0,
  }))
);

const mergeTinyCells = (
  cells: BalancedSamplingCell[],
  targetCellAreaHa: number,
  minPreferredCellAreaHa: number
): BalancedSamplingCell[] => {
  if (cells.length <= 1) {
    return normalizeCellIndexes(cells);
  }

  const maxMergedAreaHa = Math.max(
    targetCellAreaHa * MAX_MERGED_CELL_AREA_MULTIPLIER,
    minPreferredCellAreaHa * 1.5
  );

  const working = cells.map((cell) => ({
    ...cell,
    areaHa: Number(cell.areaHa.toFixed(6)),
  }));

  let index = 0;
  while (index < working.length && working.length > 1) {
    const current = working[index];
    if (current.areaHa >= minPreferredCellAreaHa) {
      index += 1;
      continue;
    }

    const leftIndex = index > 0 ? index - 1 : -1;
    const rightIndex = index < working.length - 1 ? index + 1 : -1;

    const candidates: Array<{ neighborIndex: number; mergedArea: number; overflow: number }> = [];
    if (leftIndex >= 0) {
      const mergedArea = current.areaHa + working[leftIndex].areaHa;
      candidates.push({
        neighborIndex: leftIndex,
        mergedArea,
        overflow: Math.max(0, mergedArea - maxMergedAreaHa),
      });
    }
    if (rightIndex >= 0) {
      const mergedArea = current.areaHa + working[rightIndex].areaHa;
      candidates.push({
        neighborIndex: rightIndex,
        mergedArea,
        overflow: Math.max(0, mergedArea - maxMergedAreaHa),
      });
    }

    if (!candidates.length) {
      index += 1;
      continue;
    }

    candidates.sort((a, b) => {
      if (a.overflow !== b.overflow) return a.overflow - b.overflow;
      const aDistance = Math.abs(a.mergedArea - targetCellAreaHa);
      const bDistance = Math.abs(b.mergedArea - targetCellAreaHa);
      return aDistance - bDistance;
    });

    const neighborIndex = candidates[0].neighborIndex;
    if (neighborIndex < index) {
      const merged = {
        ...working[neighborIndex],
        geometry: mergeCellGeometry(working[neighborIndex].geometry, current.geometry),
        areaHa: Number((working[neighborIndex].areaHa + current.areaHa).toFixed(6)),
      };
      working[neighborIndex] = merged;
      working.splice(index, 1);
      index = Math.max(0, neighborIndex - 1);
      continue;
    }

    const merged = {
      ...current,
      geometry: mergeCellGeometry(current.geometry, working[neighborIndex].geometry),
      areaHa: Number((current.areaHa + working[neighborIndex].areaHa).toFixed(6)),
    };
    working[neighborIndex] = merged;
    working.splice(index, 1);
    index = Math.max(0, index - 1);
  }

  return normalizeCellIndexes(working);
};

const buildAxisWindowPolygon = (
  axis: SplitAxis,
  start: number,
  end: number,
  bounds: GeometryBounds
): GeoJSON.Polygon => {
  if (axis === 'lng') {
    return {
      type: 'Polygon',
      coordinates: [[
        [start, bounds.minLat],
        [end, bounds.minLat],
        [end, bounds.maxLat],
        [start, bounds.maxLat],
        [start, bounds.minLat],
      ]],
    };
  }

  return {
    type: 'Polygon',
    coordinates: [[
      [bounds.minLng, start],
      [bounds.maxLng, start],
      [bounds.maxLng, end],
      [bounds.minLng, end],
      [bounds.minLng, start],
    ]],
  };
};

const clipGeometryByAxisWindow = (
  sourceFeature: GeoJSON.Feature<PolygonGeometry>,
  bounds: GeometryBounds,
  axis: SplitAxis,
  start: number,
  end: number
): PolygonGeometry | null => {
  if (!Number.isFinite(start) || !Number.isFinite(end) || end - start <= AXIS_EPSILON) {
    return null;
  }

  const windowFeature: GeoJSON.Feature<GeoJSON.Polygon> = {
    type: 'Feature',
    properties: {},
    geometry: buildAxisWindowPolygon(axis, start, end, bounds),
  };

  const clipped = intersect(featureCollection([
    sourceFeature as GeoJSON.Feature<GeoJSON.Polygon | GeoJSON.MultiPolygon>,
    windowFeature as GeoJSON.Feature<GeoJSON.Polygon | GeoJSON.MultiPolygon>,
  ]));

  return asPolygonGeometry(clipped?.geometry);
};

type AxisPlan = {
  cells: BalancedSamplingCell[];
  score: number;
  minAreaHa: number;
};

const buildAxisPlan = (
  geometry: PolygonGeometry,
  bounds: GeometryBounds,
  axis: SplitAxis,
  desiredCount: number,
  targetCellAreaHa: number,
  totalAreaHa: number,
  minPreferredCellAreaHa: number
): AxisPlan | null => {
  const axisMin = axis === 'lng' ? bounds.minLng : bounds.minLat;
  const axisMax = axis === 'lng' ? bounds.maxLng : bounds.maxLat;
  if (!Number.isFinite(axisMin) || !Number.isFinite(axisMax) || axisMax - axisMin <= AXIS_EPSILON) {
    return null;
  }

  const sourceFeature: GeoJSON.Feature<PolygonGeometry> = {
    type: 'Feature',
    properties: {},
    geometry,
  };

  const cuts: number[] = [axisMin];
  for (let index = 1; index < desiredCount; index += 1) {
    const targetCumulativeArea = (totalAreaHa * index) / desiredCount;
    let low = cuts[cuts.length - 1];
    let high = axisMax;

    for (let iteration = 0; iteration < BINARY_SEARCH_ITERATIONS; iteration += 1) {
      const mid = (low + high) / 2;
      const clipped = clipGeometryByAxisWindow(sourceFeature, bounds, axis, axisMin, mid);
      const clippedAreaHa = clipped ? geometryAreaHa(clipped) : 0;
      if (clippedAreaHa < targetCumulativeArea) {
        low = mid;
      } else {
        high = mid;
      }
    }

    cuts.push((low + high) / 2);
  }
  cuts.push(axisMax);

  const cells: BalancedSamplingCell[] = [];
  for (let index = 1; index < cuts.length; index += 1) {
    const start = cuts[index - 1];
    const end = cuts[index];
    const clipped = clipGeometryByAxisWindow(sourceFeature, bounds, axis, start, end);
    if (!clipped) continue;
    const clippedAreaHa = geometryAreaHa(clipped);
    if (clippedAreaHa < MIN_CELL_AREA_HA) continue;

    const cellIndex = cells.length + 1;
    cells.push({
      geometry: clipped,
      areaHa: clippedAreaHa,
      index: cellIndex,
      row: cellIndex - 1,
      column: 0,
    });
  }

  if (!cells.length) return null;

  const mergedCells = mergeTinyCells(cells, targetCellAreaHa, minPreferredCellAreaHa);
  if (!mergedCells.length) return null;

  const areas = mergedCells.map((cell) => cell.areaHa);
  const totalCoveredArea = areas.reduce((sum, value) => sum + value, 0);
  const averageArea = totalCoveredArea / mergedCells.length;
  const minArea = Math.min(...areas);
  const maxArea = Math.max(...areas);
  const spread = maxArea - minArea;
  const tinyCount = areas.filter((value) => value < minPreferredCellAreaHa).length;
  const countPenalty = Math.abs(mergedCells.length - desiredCount) * targetCellAreaHa;
  const averagePenalty = Math.abs(averageArea - targetCellAreaHa);
  const coveragePenalty = Math.max(0, 1 - (totalCoveredArea / Math.max(totalAreaHa, AXIS_EPSILON))) * targetCellAreaHa * 8;

  const score = -(
    (averagePenalty * 2.2)
    + (spread * 0.9)
    + (tinyCount * targetCellAreaHa * 7)
    + countPenalty
    + coveragePenalty
  );

  return {
    cells: mergedCells,
    score,
    minAreaHa: minArea,
  };
};

const buildSingleCellFallback = (geometry: PolygonGeometry): BalancedSamplingCell[] => {
  const areaHa = geometryAreaHa(geometry);
  if (!areaHa) return [];
  return [{
    geometry,
    areaHa,
    index: 1,
    row: 0,
    column: 0,
  }];
};

export const buildBalancedSamplingCells = (
  geometry: PolygonGeometry,
  targetCellAreaHa: number,
  maxCells: number = 500
): BalancedSamplingCell[] => {
  const safeTargetCellAreaHa = Math.max(0.1, Number(targetCellAreaHa) || 0.1);
  const safeMaxCells = Math.max(1, Math.floor(maxCells));
  const minPreferredCellAreaHa = Math.max(MIN_CELL_AREA_HA, safeTargetCellAreaHa * DEFAULT_MIN_CELL_AREA_RATIO);
  const totalAreaHa = geometryAreaHa(geometry);

  if (!totalAreaHa) return [];
  if (totalAreaHa <= Math.max(safeTargetCellAreaHa * 0.75, MIN_CELL_AREA_HA * 1.5)) {
    return buildSingleCellFallback(geometry);
  }

  const bounds = buildGeometryBounds(geometry);
  if (!bounds) {
    return buildSingleCellFallback(geometry);
  }

  const rawCount = totalAreaHa / safeTargetCellAreaHa;
  const maxCountByMinimum = Math.max(1, Math.floor(totalAreaHa / minPreferredCellAreaHa));
  const countCandidates = Array.from(new Set([
    Math.max(1, Math.floor(rawCount)),
    Math.max(1, Math.round(rawCount)),
    Math.max(1, Math.ceil(rawCount)),
  ]))
    .filter((value) => value <= safeMaxCells && value <= maxCountByMinimum)
    .sort((a, b) => a - b);

  if (!countCandidates.length) {
    countCandidates.push(Math.max(1, Math.min(safeMaxCells, Math.round(rawCount) || 1)));
  }
  if (!countCandidates.includes(1)) {
    countCandidates.unshift(1);
  }

  let bestPlan: AxisPlan | null = null;
  countCandidates.forEach((candidateCount) => {
    (['lng', 'lat'] as SplitAxis[]).forEach((axis) => {
      const candidatePlan = buildAxisPlan(
        geometry,
        bounds,
        axis,
        candidateCount,
        safeTargetCellAreaHa,
        totalAreaHa,
        minPreferredCellAreaHa
      );
      if (!candidatePlan) return;
      if (!bestPlan) {
        bestPlan = candidatePlan;
        return;
      }

      if (
        candidatePlan.score > bestPlan.score
        || (
          Math.abs(candidatePlan.score - bestPlan.score) < 1e-6
          && candidatePlan.minAreaHa > bestPlan.minAreaHa
        )
      ) {
        bestPlan = candidatePlan;
      }
    });
  });

  if (!bestPlan || !bestPlan.cells.length) {
    return buildSingleCellFallback(geometry);
  }

  return bestPlan.cells;
};

/**
 * Firebase Sync Debug Utility
 * Helps diagnose sync issues between tablet and Firebase
 */

import { hybridDB } from '../services/hybridDatabase';
import { initializeDatabaseSafely, recoverDatabase, resetDatabaseCompletely } from '../services/databaseRecovery';
import { firebaseGPS } from '../services/firebaseSync';
import { auth } from '../firebase';
import { localDB } from '../services/localDatabase';

export class FirebaseSyncDebugger {
  /**
   * Comprehensive sync status check
   */
  static async checkSyncStatus(uid?: string): Promise<any> {
    const userId = uid || auth.currentUser?.uid || '';

    console.log('­ƒöì Firebase Sync Debug Check Started');

    const results = {
      timestamp: new Date().toISOString(),
      networkStatus: {
        navigatorOnline: navigator.onLine,
        connection: (navigator as any).connection?.effectiveType || 'unknown'
      },
      authentication: {
        isAuthenticated: !!auth.currentUser,
        userId: auth.currentUser?.uid || 'none',
        email: auth.currentUser?.email || 'none',
        isAnonymous: auth.currentUser?.isAnonymous || false
      },
      firebaseConnectivity: null as any,
      hybridDbStatus: null as any,
      projectsCheck: null as any,
      syncQueueCheck: null as any
    };

    // 1. Check Firebase connectivity
    try {
      console.log('­ƒôí Testing Firebase connectivity...');
      const pingStart = Date.now();
      results.firebaseConnectivity = await firebaseGPS.ping();
      results.firebaseConnectivity.duration = Date.now() - pingStart;
      console.log('­ƒôí Firebase ping result:', results.firebaseConnectivity);
    } catch (error: any) {
      results.firebaseConnectivity = { success: false, error: error.message };
    }

    // 2. Check hybrid DB status
    try {
      console.log('­ƒùä´©Å Checking hybrid DB status...');
      results.hybridDbStatus = {
        uid: userId,
        hasUserId: !!userId,
        // Access private properties via any cast for debugging
        isOnline: (hybridDB as any).isOnline,
        isBackendAvailable: (hybridDB as any).isBackendAvailable,
        backendOnline: (hybridDB as any).backendOnline,
        connectivityBackoffMs: (hybridDB as any).connectivityBackoffMs,
        lastConnectivityCheck: (hybridDB as any).lastConnectivityCheck,
        syncQueueLength: (hybridDB as any).syncQueue?.length || 0
      };
    } catch (error: any) {
      results.hybridDbStatus = { error: error.message };
    }

    // 3. Test projects fetch directly from Firebase
    if (userId && results.authentication.isAuthenticated) {
      try {
        console.log('­ƒôï Testing direct Firebase projects fetch...');
        const projectsStart = Date.now();
        const firebaseProjects = await firebaseGPS.getProjects(userId);
        results.projectsCheck = {
          success: true,
          count: firebaseProjects.length,
          duration: Date.now() - projectsStart,
          projects: firebaseProjects.map((p: any) => ({ id: p.id, name: p.name, created_at: p.created_at }))
        };
        console.log('­ƒôï Firebase projects result:', results.projectsCheck);
      } catch (error: any) {
        results.projectsCheck = { success: false, error: error.message };
      }
    } else {
      results.projectsCheck = { skipped: 'No authenticated user' };
    }

    // 4. Check local sync queue
    try {
      console.log('­ƒôñ Checking sync queue...');
      const syncQueue = (hybridDB as any).syncQueue || [];
      results.syncQueueCheck = {
        queueLength: syncQueue.length,
        items: syncQueue.slice(0, 5).map((item: any) => ({
          id: item.id,
          type: item.type,
          action: item.action,
          timestamp: new Date(item.timestamp).toISOString(),
          attempts: item.attempts || 0,
          nextAttemptAt: item.nextAttemptAt ? new Date(item.nextAttemptAt).toISOString() : null
        }))
      };
    } catch (error: any) {
      results.syncQueueCheck = { error: error.message };
    }

    console.log('­ƒöì Firebase Sync Debug Complete:', results);
    return results;
  }

  /**
   * Force sync attempt
   */
  static async forceSyncAttempt(): Promise<any> {
    console.log('­ƒöä Forcing sync attempt...');

    try {
      // Force connectivity refresh
      const connectivityResult = await (hybridDB as any).refreshConnectivity(true);
      console.log('­ƒôí Connectivity refresh:', connectivityResult);

      // Trigger sync
      if (connectivityResult.success) {
        await (hybridDB as any).syncToFirebaseNonBlocking();
        console.log('­ƒöä Sync triggered');
      }

      return { success: true, connectivity: connectivityResult };
    } catch (error: any) {
      console.error('­ƒöä Force sync failed:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Inspect sync queue with full details
   */
  static inspectQueue(): any {
    try {
      const queue = (hybridDB as any).syncQueue || [];
      const summary = {
        total: queue.length,
        byType: queue.reduce((acc: Record<string, number>, it: any) => {
          acc[it.type] = (acc[it.type] || 0) + 1;
          return acc;
        }, {}),
        byAction: queue.reduce((acc: Record<string, number>, it: any) => {
          acc[it.action] = (acc[it.action] || 0) + 1;
          return acc;
        }, {}),
        tracks: queue.filter((it: any) => it.type === 'track'),
        samples: queue.filter((it: any) => it.type === 'sample'),
        points: queue.filter((it: any) => it.type === 'point')
      };

      console.log('­ƒôñ Sync Queue Summary:', summary);
      console.log('­ƒôè Tracks in queue:', summary.tracks.map((t: any) => ({ id: t.id, name: t.data?.name, action: t.action })));
      console.log('­ƒº¬ Samples in queue:', summary.samples.map((s: any) => ({ id: s.id, name: s.data?.name, track_id: s.data?.track_id, attempts: s.attempts })));
      console.log('­ƒôì GPS Points in queue:', summary.points.length);

      queue.forEach((item: any, idx: number) => {
        const display: any = {
          id: item.id,
          type: item.type,
          action: item.action,
          data: {
            name: item.data?.name,
            project_id: item.data?.project_id,
            track_id: item.data?.track_id,
            field_boundary_id: item.data?.field_boundary_id
          },
          attempts: item.attempts || 0,
          nextAttemptAt: item.nextAttemptAt ? new Date(item.nextAttemptAt).toISOString() : 'ready',
          timestamp: item.timestamp ? new Date(item.timestamp).toISOString() : 'n/a'
        };

        // Highlight local track IDs
        if (item.data?.track_id && item.data.track_id.startsWith('local_')) {
          display.WARNING = 'ÔÜá´©Å References local track ID - may need track sync first';
        }

        console.log(`[${idx + 1}/${queue.length}]`, display);
      });
      return { success: true, summary, items: queue };
    } catch (error: any) {
      console.error('ÔØî Failed to inspect queue:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Clear sync queue (optionally filter by type/action)
   * Usage:
   *  - FirebaseSyncDebugger.clearQueue() // clears all
   *  - FirebaseSyncDebugger.clearQueue({ type: 'track' })
   *  - FirebaseSyncDebugger.clearQueue({ type: 'track', action: 'update' })
   */
  static async clearQueue(filter?: { type?: string; action?: string }): Promise<any> {
    try {
      const dbAny = (hybridDB as any);
      const queue: any[] = dbAny.syncQueue || [];
      const before = queue.length;

      let newQueue = queue;
      if (filter?.type || filter?.action) {
        newQueue = queue.filter(it => {
          const typeOk = filter?.type ? it.type !== filter.type : true;
          const actionOk = filter?.action ? it.action !== filter.action : true;
          return typeOk || actionOk; // remove only when BOTH match
        });
      } else {
        newQueue = [];
      }

      dbAny.syncQueue = newQueue;
      await dbAny.saveSyncQueue();

      const removed = before - newQueue.length;
      console.warn(`­ƒº╣ Cleared ${removed} item(s) from sync queue${filter ? ' (filtered)' : ''}.`);
      return { success: true, removed, remaining: newQueue.length };
    } catch (error: any) {
      console.error('ÔØî Failed to clear queue:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Remove a specific item from sync queue by ID
   * Usage: FirebaseSyncDebugger.removeQueueItem('update_1765953496107')
   */
  static async removeQueueItem(itemId: string): Promise<any> {
    try {
      const dbAny = (hybridDB as any);
      const queue: any[] = dbAny.syncQueue || [];
      const before = queue.length;

      const item = queue.find(it => it.id === itemId);
      if (!item) {
        console.warn(`ÔÜá´©Å Item ${itemId} not found in queue`);
        return { success: false, error: 'Item not found' };
      }

      console.log(`­ƒùæ´©Å Removing item from queue:`, {
        id: item.id,
        type: item.type,
        action: item.action,
        attempts: item.attempts,
        name: item.data?.name
      });

      dbAny.syncQueue = queue.filter(it => it.id !== itemId);
      await dbAny.saveSyncQueue();

      console.log(`Ô£à Removed item ${itemId} from sync queue (${before} -> ${dbAny.syncQueue.length})`);
      return { success: true, removed: item, remaining: dbAny.syncQueue.length };
    } catch (error: any) {
      console.error('ÔØî Failed to remove queue item:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Remove all items with high attempt counts (likely broken)
   * Usage: FirebaseSyncDebugger.clearBrokenItems(10) // removes items with 10+ attempts
   */
  static async clearBrokenItems(minAttempts: number = 10): Promise<any> {
    try {
      const dbAny = (hybridDB as any);
      const queue: any[] = dbAny.syncQueue || [];
      const before = queue.length;

      const brokenItems = queue.filter(it => (it.attempts || 0) >= minAttempts);
      console.log(`­ƒöì Found ${brokenItems.length} items with ${minAttempts}+ attempts:`, 
        brokenItems.map(it => ({ id: it.id, type: it.type, action: it.action, attempts: it.attempts }))
      );

      if (brokenItems.length === 0) {
        console.log('Ô£à No broken items found');
        return { success: true, removed: 0, remaining: queue.length };
      }

      dbAny.syncQueue = queue.filter(it => (it.attempts || 0) < minAttempts);
      await dbAny.saveSyncQueue();

      const removed = before - dbAny.syncQueue.length;
      console.warn(`­ƒº╣ Removed ${removed} broken item(s) from sync queue`);
      return { success: true, removed, brokenItems, remaining: dbAny.syncQueue.length };
    } catch (error: any) {
      console.error('ÔØî Failed to clear broken items:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Retry now: triggers connectivity refresh and non-blocking sync
   */
  static async retryNow(): Promise<any> {
    try {
      await (hybridDB as any).refreshConnectivity(true);
      await (hybridDB as any).syncToFirebaseNonBlocking();
      console.log('­ƒöü Retry sync triggered');
      return { success: true };
    } catch (error: any) {
      return { success: false, error: error.message };
    }
  }

  /**
   * Compare local vs Firebase data
   */
  static async compareLocalVsFirebase(uid?: string): Promise<any> {
    const userId = uid || auth.currentUser?.uid || '';

    if (!userId) {
      return { error: 'No user ID available' };
    }

    console.log('­ƒöä Comparing local vs Firebase data...');

    const comparison = {
      local: null as any,
      firebase: null as any,
      differences: [] as string[]
    };

    try {
      // Get local projects
      const localProjects = await hybridDB.getProjects();
      comparison.local = {
        projectCount: localProjects.length,
        projects: localProjects.map(p => ({ id: p.id, name: p.name, created_at: p.created_at }))
      };

      // Get Firebase projects
      const firebaseProjects = await firebaseGPS.getProjects(userId);
      comparison.firebase = {
        projectCount: firebaseProjects.length,
        projects: firebaseProjects.map(p => ({ id: p.id, name: p.name, created_at: p.created_at }))
      };

      // Find differences
      if (comparison.local.projectCount !== comparison.firebase.projectCount) {
        comparison.differences.push(`Project count mismatch: local=${comparison.local.projectCount}, firebase=${comparison.firebase.projectCount}`);
      }

      // Check for missing projects
      const localIds = new Set(localProjects.map(p => p.id));
      const firebaseIds = new Set(firebaseProjects.map((p: any) => p.id));

      for (const fbId of firebaseIds) {
        if (!localIds.has(fbId)) {
          const fbProject = firebaseProjects.find((p: any) => p.id === fbId);
          comparison.differences.push(`Missing locally: ${fbProject.name} (${fbId})`);
        }
      }

      for (const localId of localIds) {
        if (!firebaseIds.has(localId)) {
          const localProject = localProjects.find(p => p.id === localId);
          comparison.differences.push(`Missing from Firebase: ${localProject.name} (${localId})`);
        }
      }

    } catch (error: any) {
      comparison.differences.push(`Comparison failed: ${error.message}`);
    }

    console.log('­ƒöä Comparison complete:', comparison);
    return comparison;
  }

