import { Geolocation } from '@capacitor/geolocation';
import MockLocationDetector from '../plugins/MockLocationDetector';

/**
 * Enhanced position options with network-based location support
 * This enables cell tower and WiFi triangulation for improved accuracy
 */
export interface EnhancedPositionOptions extends PositionOptions {
  // Use network location providers (cell towers, WiFi) in addition to GPS
  useNetworkLocation?: boolean;
  // Prefer network-based location for faster results
  preferNetworkLocation?: boolean;
  // Android (Capacitor): minimum interval between watch updates in ms
  minimumUpdateInterval?: number;
}

// Detect Capacitor runtime (native shell or ionic protocol)
export const isCapacitor = (): boolean => {
  if (typeof window === 'undefined') return false;
  const protocol = window.location?.protocol;
  return protocol === 'capacitor:' || protocol === 'ionic:' || !!(window as any).Capacitor?.isNativePlatform?.();
};

export const requestLocationPermission = async (): Promise<boolean> => {
  try {
    if (isCapacitor()) {
      const status = await Geolocation.requestPermissions();
      const locationStatus = (status as any).location || (status as any).coarseLocation;
      return locationStatus === 'granted' || locationStatus === 'prompt';
    }
    if (typeof navigator !== 'undefined' && (navigator as any).permissions?.query) {
      const res = await (navigator as any).permissions.query({ name: 'geolocation' });
      return res.state === 'granted' || res.state === 'prompt';
    }
    return typeof navigator !== 'undefined' && !!navigator.geolocation;
  } catch (error) {
    console.warn('Geolocation permission check failed:', error);
    return false;
  }
};

export const getCurrentPosition = async (options?: EnhancedPositionOptions): Promise<GeolocationPosition> => {
  if (isCapacitor()) {
    // For Android: enableHighAccuracy=true uses GPS + network (cell towers, WiFi)
    // For Android: enableHighAccuracy=false uses only network providers
    // This provides better accuracy in urban areas and faster initial fix
    const useHighAccuracy = options?.enableHighAccuracy ?? true;

    console.log('­ƒôì Getting position with settings:', {
      enableHighAccuracy: useHighAccuracy,
      useNetworkLocation: options?.useNetworkLocation ?? true,
      timeout: options?.timeout ?? 60000
    });

    const position = await Geolocation.getCurrentPosition({
      // On Android, this enables:
      // - true: GPS + Network (cell towers + WiFi) for best accuracy
      // - false: Network only (faster, less accurate)
      enableHighAccuracy: useHighAccuracy,
      timeout: options?.timeout ?? 60000,
      maximumAge: options?.maximumAge ?? 0,
    });

    // Check if this is a mock location using native plugin
    let isMockLocation = false;
    try {
      const mockCheck = await MockLocationDetector.isMockLocation();
      isMockLocation = mockCheck.isMock;
      console.log('­ƒôì Native mock location check:', mockCheck);
    } catch (error) {
      console.log('­ƒôì Native mock detection not available, using fallback');
      // Fallback: Check multiple possible mock location indicators
      isMockLocation = 
        (position as any).mocked === true || 
        (position as any).mock === true ||
        (position as any).isMock === true ||
        (position as any).coords?.mocked === true ||
        (position as any).coords?.mock === true ||
        (position as any).coords?.isMock === true ||
        (position as any).isFromMockProvider === true;
    }

    // Log position data
    console.log('­ƒôì ============ POSITION DATA START ============');
    console.log('­ƒôì Lat/Lng:', position.coords.latitude.toFixed(6), position.coords.longitude.toFixed(6));
    console.log('­ƒôì Accuracy:', position.coords.accuracy);
    console.log('­ƒø░´©Å MOCK LOCATION:', isMockLocation);
    console.log('­ƒôì ============ POSITION DATA END ============');

    return {
      coords: {
        latitude: position.coords.latitude,
        longitude: position.coords.longitude,
        accuracy: position.coords.accuracy,
        altitude: position.coords.altitude,
        altitudeAccuracy: position.coords.altitudeAccuracy ?? null,
        heading: position.coords.heading ?? null,
        speed: position.coords.speed ?? null,
      },
      timestamp: position.timestamp,
      // Add mock location indicator
      ...(isMockLocation && { mocked: true }),
    } as GeolocationPosition & { mocked?: boolean };
  }

  return new Promise((resolve, reject) => {
    // For web browsers, ensure we use the best available positioning:
    // - enableHighAccuracy: true uses GPS if available, WiFi positioning, and IP geolocation
    // - maximumAge: 0 ensures fresh location data
    // - timeout gives enough time for WiFi positioning to work
    const webOptions = {
      enableHighAccuracy: options?.enableHighAccuracy ?? true,
      timeout: options?.timeout ?? 15000,
      maximumAge: options?.maximumAge ?? 0,
    };
    navigator.geolocation.getCurrentPosition(resolve, reject, webOptions);
  });
};

export const watchPosition = async (
  success: (position: GeolocationPosition) => void,
  error?: (error: GeolocationPositionError) => void,
  options?: EnhancedPositionOptions
): Promise<string | number> => {
  if (isCapacitor()) {
    // Enable network-based location by default for improved accuracy
    const useHighAccuracy = options?.enableHighAccuracy ?? true;

    console.log('­ƒôì Starting position watch with settings:', {
      enableHighAccuracy: useHighAccuracy,
      useNetworkLocation: options?.useNetworkLocation ?? true
    });

    const nativeWatchOptions: any = {
      // On Android with enableHighAccuracy=true:
      // - Uses GPS satellites (primary)
      // - Uses cell tower triangulation (secondary)
      // - Uses WiFi positioning (tertiary)
      // This combination provides best accuracy and faster fix times
      enableHighAccuracy: useHighAccuracy,
      timeout: options?.timeout ?? 60000,
      maximumAge: options?.maximumAge ?? 0,
      // Capacitor Android defaults to a slower cadence if this is not set.
      minimumUpdateInterval: options?.minimumUpdateInterval ?? 1000,
    };

    const id = await Geolocation.watchPosition(
      nativeWatchOptions,
      (position, err) => {
        if (err && error) {
          error({
            code: 2,
            message: err?.message || 'Unknown error',
            PERMISSION_DENIED: 1,
            POSITION_UNAVAILABLE: 2,
            TIMEOUT: 3,
          } as GeolocationPositionError);
        } else if (position) {
          const isMockLocation = 
            (position as any).mocked === true || 
            (position as any).mock === true ||
            (position as any).isMock === true ||
            (position as any).coords?.mocked === true ||
            (position as any).coords?.mock === true ||
            (position as any).coords?.isMock === true ||
            (position as any).isFromMockProvider === true;

          // Only log when mock location detected (reduce spam)
          if (isMockLocation) {
            console.log('­ƒôì ============ WATCH POSITION UPDATE ============');
            console.log('­ƒôì Position keys:', Object.keys(position));
            console.log('­ƒôì Coords keys:', Object.keys(position.coords));
            console.log('­ƒôì Accuracy:', position.coords.accuracy);
            console.log('­ƒø░´©Å MOCK LOCATION:', isMockLocation);
            console.log('­ƒôì ============================================');
          }

          success({
            coords: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude,
              accuracy: position.coords.accuracy,
              altitude: position.coords.altitude,
              altitudeAccuracy: position.coords.altitudeAccuracy ?? null,
              heading: position.coords.heading ?? null,
              speed: position.coords.speed ?? null,
            },
            timestamp: position.timestamp,
            ...(isMockLocation && { mocked: true }),
          } as GeolocationPosition & { mocked?: boolean });
        }
      }
    );
    return id;
  }

  // For web browsers, ensure we use the best available positioning:
  // - enableHighAccuracy: true uses GPS if available, WiFi positioning, and IP geolocation
  // - maximumAge: 0 ensures fresh location updates
  // - timeout gives enough time for WiFi positioning to work
  const webOptions = {
    enableHighAccuracy: options?.enableHighAccuracy ?? true,
    timeout: options?.timeout ?? 15000,
    maximumAge: options?.maximumAge ?? 0,
  };
  return navigator.geolocation.watchPosition(success, error, webOptions);
};

export const clearWatch = async (watchId: string | number | null | undefined) => {
  if (!watchId) return;
  if (isCapacitor() && typeof watchId === 'string') {
    await Geolocation.clearWatch({ id: watchId });
  } else if (typeof watchId === 'number') {
    navigator.geolocation.clearWatch(watchId);
  }
};

/**
 * Geometry Validation and Normalization Utility
 * 
 * Handles GeoJSON geometry objects with proper validation and serialization.
 * Fixes Issue #13: Double serialization and type inconsistency problems.
 * 
 * Key improvements:
 * - Single source of truth for geometry validation
 * - Prevents double serialization
 * - Type-safe GeoJSON handling
 * - Coordinate precision preservation
 * - Proper error messages
 */

export interface GeoJSONGeometry {
  type: 'Point' | 'LineString' | 'Polygon' | 'MultiPoint' | 'MultiLineString' | 'MultiPolygon';
  coordinates: any; // Varies by type
}

export interface GeoJSONFeature {
  type: 'Feature';
  geometry: GeoJSONGeometry;
  properties?: Record<string, any>;
}

export interface GeoJSONFeatureCollection {
  type: 'FeatureCollection';
  features: GeoJSONFeature[];
}

export type GeoJSON = GeoJSONGeometry | GeoJSONFeature | GeoJSONFeatureCollection;

/**
 * Validate that geometry has required GeoJSON structure
 */
export function isValidGeoJSONGeometry(geometry: any): geometry is GeoJSONGeometry {
  if (!geometry || typeof geometry !== 'object') return false;

  const validTypes = ['Point', 'LineString', 'Polygon', 'MultiPoint', 'MultiLineString', 'MultiPolygon'];
  if (!validTypes.includes(geometry.type)) return false;

  if (!geometry.coordinates) return false;
  if (!Array.isArray(geometry.coordinates)) return false;
  if (geometry.coordinates.length === 0) return false;

  return true;
}

/**
 * Validate coordinate precision (avoid floating point issues)
 */
export function validateCoordinatePrecision(coords: number, maxPrecision: number = 8): number {
  // Round to specified decimal places to avoid floating point drift
  return Math.round(coords * Math.pow(10, maxPrecision)) / Math.pow(10, maxPrecision);
}

/**
 * Normalize geometry input from various sources
 * Handles:
 * - Raw GeoJSON objects
 * - JSON strings
 * - Wrapped objects { geometry: {...} }
 * - Feature objects with nested geometry
 */
export function normalizeGeometry(input: any): GeoJSONGeometry {
  if (!input) {
    throw new Error('Geometry is required');
  }

  let geometry = input;

  // CRITICAL FIX: If it's a string, parse it repeatedly until we get an object
  // Handles single, double, or even triple serialized JSON strings
  while (typeof geometry === 'string') {
    try {
      geometry = JSON.parse(geometry);
    } catch (error) {
      throw new Error(`Invalid geometry JSON string: ${error instanceof Error ? error.message : 'parse failed'}`);
    }
  }

  // Unwrap Feature objects
  if (geometry.type === 'Feature' && geometry.geometry) {
    geometry = geometry.geometry;
  }

  // Unwrap nested { geometry: {...} } wrapper
  if (geometry.geometry && typeof geometry.geometry === 'object') {
    geometry = geometry.geometry;
  }

  // Validate final structure
  if (!isValidGeoJSONGeometry(geometry)) {
    throw new Error(
      `Invalid GeoJSON geometry: ${
        !geometry.type ? 'missing type' :
        !geometry.coordinates ? 'missing coordinates' :
        !Array.isArray(geometry.coordinates) ? 'coordinates must be an array' :
        geometry.coordinates.length === 0 ? 'coordinates cannot be empty' :
        'invalid structure'
      }`
    );
  }

  return geometry;
}

/**
 * Serialize geometry for Firestore storage
 * Firestore doesn't support nested arrays, so we store as JSON string
 * 
 * IMPORTANT: This is the ONLY place geometry should be stringified
 */
export function serializeGeometryForFirestore(geometry: GeoJSONGeometry): string {
  if (!isValidGeoJSONGeometry(geometry)) {
    throw new Error('Cannot serialize invalid geometry');
  }

  // Use JSON.stringify with NO space parameter to minimize size
  // This is deterministic and preserves precision
  return JSON.stringify(geometry);
}

/**
 * Simplify geometry by downsampling rings to a maximum number of points.
 * Keeps closure for polygon rings when needed.
 */
export function simplifyGeometryForStorage(
  geometry: GeoJSONGeometry,
  maxPointsPerRing: number = 2000
): GeoJSONGeometry {
  if (!isValidGeoJSONGeometry(geometry)) {
    throw new Error('Cannot simplify invalid geometry');
  }

  const simplifyRing = (ring: number[][]): number[][] => {
    if (!Array.isArray(ring) || ring.length <= maxPointsPerRing) {
      return ring;
    }

    const step = Math.max(1, Math.ceil(ring.length / maxPointsPerRing));
    const simplified = ring.filter((_, idx) => idx % step === 0);
    if (simplified.length < 4) {
      return ring;
    }

    const first = simplified[0];
    const last = simplified[simplified.length - 1];
    if (first[0] !== last[0] || first[1] !== last[1]) {
      simplified.push(first);
    }

    return simplified;
  };

  if (geometry.type === 'Polygon') {
    return {
      ...geometry,
      coordinates: geometry.coordinates.map(simplifyRing)
    };
  }

  if (geometry.type === 'MultiPolygon') {
    return {
      ...geometry,
      coordinates: geometry.coordinates.map(poly => poly.map(simplifyRing))
    };
  }

  return geometry;
}

/**
 * Deserialize geometry from Firestore storage
 * 
 * IMPORTANT: This is the ONLY place geometry strings should be parsed
 */
export function deserializeGeometryFromFirestore(input: any): GeoJSONGeometry {
  // If already an object, validate and return
  if (typeof input === 'object' && input !== null) {
    if (isValidGeoJSONGeometry(input)) {
      return input;
    }
    throw new Error('Invalid geometry object from Firestore');
  }

  // If string, parse once
  if (typeof input === 'string') {
    try {
      const parsed = JSON.parse(input);
      if (!isValidGeoJSONGeometry(parsed)) {
        throw new Error('Parsed geometry is invalid');
      }
      return parsed;
    } catch (error) {
      throw new Error(`Failed to deserialize geometry: ${error instanceof Error ? error.message : 'parse failed'}`);
    }
  }

  throw new Error(`Invalid geometry type from Firestore: ${typeof input}`);
}

/**
 * Calculate approximate area of a polygon in square meters
 * Uses Shoelace formula for simple polygons
 */
export function calculatePolygonArea(geometry: GeoJSONGeometry): number {
  if (geometry.type !== 'Polygon') {
    throw new Error('Can only calculate area for Polygon geometry');
  }

  const coords = geometry.coordinates[0]; // Outer ring
  if (!coords || coords.length < 3) {
    return 0;
  }

  // Approximate conversion: 1 degree latitude Ôëê 111km, longitude varies by latitude
  const latToMeters = 111000;
  let area = 0;

  for (let i = 0; i < coords.length - 1; i++) {
    const [lon1, lat1] = coords[i];
    const [lon2, lat2] = coords[i + 1];

    const lonToMeters = 111000 * Math.cos((lat1 * Math.PI) / 180);
    const x1 = lon1 * lonToMeters;
    const y1 = lat1 * latToMeters;
    const x2 = lon2 * lonToMeters;
    const y2 = lat2 * latToMeters;

    area += (x1 * y2) - (x2 * y1);
  }

  return Math.abs(area / 2);
}

/**
 * Calculate length of a LineString in meters
 */
export function calculateLineStringLength(geometry: GeoJSONGeometry): number {
  if (geometry.type !== 'LineString') {
    throw new Error('Can only calculate length for LineString geometry');
  }

  const coords = geometry.coordinates;
  if (!coords || coords.length < 2) {
    return 0;
  }

  let totalLength = 0;
  for (let i = 0; i < coords.length - 1; i++) {
    const [lon1, lat1] = coords[i];
    const [lon2, lat2] = coords[i + 1];

    // Haversine formula for great-circle distance
    const R = 6371000; // Earth radius in meters
    const ¤å1 = (lat1 * Math.PI) / 180;
    const ¤å2 = (lat2 * Math.PI) / 180;
    const ╬ö¤å = ((lat2 - lat1) * Math.PI) / 180;
    const ╬ö╬╗ = ((lon2 - lon1) * Math.PI) / 180;

    const a = Math.sin(╬ö¤å / 2) * Math.sin(╬ö¤å / 2) +
              Math.cos(¤å1) * Math.cos(¤å2) *
              Math.sin(╬ö╬╗ / 2) * Math.sin(╬ö╬╗ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    totalLength += R * c;
  }

  return totalLength;
}

/**
 * Get bounding box for geometry [minLon, minLat, maxLon, maxLat]
 */
export function getBoundingBox(geometry: GeoJSONGeometry): [number, number, number, number] {
  let allCoords: number[][] = [];

  // Extract all coordinates based on geometry type
  switch (geometry.type) {
    case 'Point':
      allCoords = [geometry.coordinates];
      break;
    case 'LineString':
      allCoords = geometry.coordinates;
      break;
    case 'Polygon':
      allCoords = geometry.coordinates.flat();
      break;
    case 'MultiPoint':
      allCoords = geometry.coordinates;
      break;
    case 'MultiLineString':
      allCoords = geometry.coordinates.flat();
      break;
    case 'MultiPolygon':
      allCoords = geometry.coordinates.flat(2);
      break;
  }

  if (allCoords.length === 0) {
    throw new Error('No coordinates found in geometry');
  }

  let minLon = Infinity, minLat = Infinity;
  let maxLon = -Infinity, maxLat = -Infinity;

  for (const [lon, lat] of allCoords) {
    minLon = Math.min(minLon, lon);
    minLat = Math.min(minLat, lat);
    maxLon = Math.max(maxLon, lon);
    maxLat = Math.max(maxLat, lat);
  }

  return [minLon, minLat, maxLon, maxLat];
}

/**
 * GPS Connection Diagnostic Tool
 * Tests various connection methods to help troubleshoot GPS device connectivity
 */

export interface ConnectionTest {
  method: string;
  url: string;
  result: 'success' | 'failed' | 'timeout' | 'cors-blocked';
  error?: string;
  data?: string;
  duration: number;
}

export class GPSConnectionDiagnostic {
  private results: ConnectionTest[] = [];

  async testConnection(deviceIP: string, port: number = 9001): Promise<ConnectionTest[]> {
    this.results = [];
    console.log(`­ƒöì Starting GPS connection diagnostics for ${deviceIP}:${port}`);

    // Test 1: WebSocket connection (what most GPS devices use for streaming)
    await this.testWebSocket(deviceIP, port);

    // Test 2: WebSocket on port 80 (some devices)
    if (port !== 80) {
      await this.testWebSocket(deviceIP, 80);
    }

    // Test 3: HTTP endpoints (polling fallback)
    await this.testHTTPEndpoints(deviceIP, port);

    // Test 4: Basic ping/connectivity test
    await this.testBasicConnectivity(deviceIP);

    // Test 5: NMEA data format test
    await this.testNMEAEndpoints(deviceIP);

    this.printDiagnosticReport();
    return this.results;
  }

  private async testWebSocket(ip: string, port: number): Promise<void> {
    const wsUrl = `ws://${ip}:${port}`;
    const startTime = Date.now();

    return new Promise((resolve) => {
      const ws = new WebSocket(wsUrl);
      let resolved = false;

      const cleanup = () => {
        if (!resolved) {
          resolved = true;
          resolve();
        }
      };

      const timeout = setTimeout(() => {
        ws.close();
        if (!resolved) {
          this.results.push({
            method: 'WebSocket',
            url: wsUrl,
            result: 'timeout',
            error: 'Connection timeout (3 seconds)',
            duration: Date.now() - startTime
          });
          cleanup();
        }
      }, 3000);

      ws.onopen = () => {
        clearTimeout(timeout);
        this.results.push({
          method: 'WebSocket',
          url: wsUrl,
          result: 'success',
          data: 'Connection established',
          duration: Date.now() - startTime
        });
        ws.close();
        cleanup();
      };

      ws.onerror = () => {
        clearTimeout(timeout);
        this.results.push({
          method: 'WebSocket',
          url: wsUrl,
          result: 'failed',
          error: 'WebSocket connection failed',
          duration: Date.now() - startTime
        });
        cleanup();
      };

      ws.onclose = (event) => {
        clearTimeout(timeout);
        if (event.code !== 1000 && !resolved) {
          this.results.push({
            method: 'WebSocket',
            url: wsUrl,
            result: 'failed',
            error: `WebSocket closed with code ${event.code}: ${event.reason}`,
            duration: Date.now() - startTime
          });
          cleanup();
        }
      };
    });
  }

  private async testHTTPEndpoints(ip: string, port: number): Promise<void> {
    const endpoints = [
      `http://${ip}:${port}/`,
      `http://${ip}:${port}/nmea`,
      `http://${ip}:${port}/gps`,
      `http://${ip}:${port}/position`,
      `http://${ip}/nmea`,
      `http://${ip}/gps`,
      `http://${ip}/position`
    ];

    for (const endpoint of endpoints) {
      await this.testHTTPEndpoint(endpoint);
    }
  }

  private async testHTTPEndpoint(url: string): Promise<void> {
    const startTime = Date.now();

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch(url, {
        method: 'GET',
        mode: 'no-cors',
        cache: 'no-cache',
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      this.results.push({
        method: 'HTTP',
        url: url,
        result: 'success',
        data: `Status: ${response.status} (CORS mode)`,
        duration: Date.now() - startTime
      });
    } catch (error: any) {
      this.results.push({
        method: 'HTTP',
        url: url,
        result: error.name === 'AbortError' ? 'timeout' : 'failed',
        error: error.message,
        duration: Date.now() - startTime
      });
    }
  }

  private async testBasicConnectivity(ip: string): Promise<void> {
    const startTime = Date.now();

    try {
      // Try to reach the device on port 80 (most basic test)
      await fetch(`http://${ip}/`, {
        method: 'HEAD',
        mode: 'no-cors',
        cache: 'no-cache',
        signal: AbortSignal.timeout(3000)
      });

      this.results.push({
        method: 'Ping',
        url: `http://${ip}/`,
        result: 'success',
        data: 'Device appears reachable',
        duration: Date.now() - startTime
      });
    } catch (error: any) {
      this.results.push({
        method: 'Ping',
        url: `http://${ip}/`,
        result: 'failed',
        error: `Device not reachable: ${error.message}`,
        duration: Date.now() - startTime
      });
    }
  }

  private async testNMEAEndpoints(ip: string): Promise<void> {
    // Test common NMEA streaming endpoints
    const nmeaEndpoints = [
      `http://${ip}:9001/`,
      `http://${ip}/api/nmea`,
      `http://${ip}/stream/nmea`,
      `http://${ip}/nmea.txt`,
      `http://${ip}/data/nmea`
    ];

    for (const endpoint of nmeaEndpoints) {
      await this.testNMEAEndpoint(endpoint);
    }
  }

  private async testNMEAEndpoint(url: string): Promise<void> {
    const startTime = Date.now();

    try {
      const response = await fetch(url, {
        method: 'GET',
        mode: 'cors', // Try CORS first for NMEA data
        cache: 'no-cache',
        signal: AbortSignal.timeout(3000)
      });

      const text = await response.text();
      const isNMEA = text.includes('$GP') || text.includes('$GN') || text.includes('$GL');

      this.results.push({
        method: 'NMEA',
        url: url,
        result: isNMEA ? 'success' : 'failed',
        data: isNMEA ? `NMEA data found: ${text.substring(0, 100)}...` : 'No NMEA data detected',
        duration: Date.now() - startTime
      });
    } catch (error: any) {
      if (error.message.includes('CORS')) {
        this.results.push({
          method: 'NMEA',
          url: url,
          result: 'cors-blocked',
          error: 'CORS policy blocks access',
          duration: Date.now() - startTime
        });
      } else {
        this.results.push({
          method: 'NMEA',
          url: url,
          result: 'failed',
          error: error.message,
          duration: Date.now() - startTime
        });
      }
    }
  }

  private printDiagnosticReport(): void {
    console.log('\n­ƒöì === GPS CONNECTION DIAGNOSTIC REPORT ===');

    const successful = this.results.filter(r => r.result === 'success');
    const failed = this.results.filter(r => r.result === 'failed');
    const blocked = this.results.filter(r => r.result === 'cors-blocked');
    const timeouts = this.results.filter(r => r.result === 'timeout');

    console.log(`Ô£à Successful connections: ${successful.length}`);
    console.log(`ÔØî Failed connections: ${failed.length}`);
    console.log(`­ƒÜ½ CORS blocked: ${blocked.length}`);
    console.log(`ÔÅ▒´©Å Timeouts: ${timeouts.length}`);

    if (successful.length > 0) {
      console.log('\nÔ£à WORKING CONNECTIONS:');
      successful.forEach(result => {
        console.log(`  ${result.method}: ${result.url} (${result.duration}ms)`);
        if (result.data) console.log(`    Data: ${result.data}`);
      });
    }

    if (blocked.length > 0) {
      console.log('\n­ƒÜ½ CORS BLOCKED (but device may be reachable):');
      blocked.forEach(result => {
        console.log(`  ${result.method}: ${result.url}`);
      });
    }

    if (failed.length > 0 || timeouts.length > 0) {
      console.log('\nÔØî FAILED/TIMEOUT CONNECTIONS:');
      [...failed, ...timeouts].forEach(result => {
        console.log(`  ${result.method}: ${result.url} - ${result.error}`);
      });
    }

    console.log('\n­ƒÆí RECOMMENDATIONS:');

    if (successful.filter(r => r.method === 'WebSocket').length > 0) {
      console.log('  Ô£ô WebSocket connection works - GPS should connect successfully');
    } else if (successful.filter(r => r.method === 'HTTP').length > 0) {
      console.log('  Ô£ô HTTP endpoints work - GPS will use polling mode');
    } else if (blocked.length > 0) {
      console.log('  ÔÜá´©Å Device is reachable but CORS blocks access');
      console.log('  ­ƒÆí Solution: Configure GPS device to allow CORS or use mobile app');
    } else {
      console.log('  ÔØî Device not reachable. Check:');
      console.log('    1. Device is powered on and WiFi hotspot is active');
      console.log('    2. You are connected to the device\'s WiFi network');
      console.log('    3. Device IP address is correct (usually 192.168.42.1)');
      console.log('    4. Device firewall allows connections');
    }

    console.log('===========================================\n');
  }
}

